            ["/source-charset:utf-8 は付けられませんでした (C++ のプロジェクト (.vcxproj) が見つかりません。CMake なら add_compile_options(/source-charset:utf-8) を書きます)。"] = new[] { "/source-charset:utf-8 could not be added (no C++ project (.vcxproj) found. For CMake, write add_compile_options(/source-charset:utf-8)).", "无法添加 /source-charset:utf-8（找不到 C++ 项目 (.vcxproj)。若使用 CMake，请写 add_compile_options(/source-charset:utf-8)）。", "/source-charset:utf-8를 붙이지 못했습니다 (C++ 프로젝트(.vcxproj)를 찾을 수 없습니다. CMake라면 add_compile_options(/source-charset:utf-8)를 씁니다).", "No se pudo añadir /source-charset:utf-8 (no se encontró un proyecto C++ (.vcxproj). En CMake, escriba add_compile_options(/source-charset:utf-8)).", "Não foi possível adicionar /source-charset:utf-8 (nenhum projeto C++ (.vcxproj) encontrado. No CMake, escreva add_compile_options(/source-charset:utf-8)).", "/source-charset:utf-8 konnte nicht hinzugefügt werden (kein C++-Projekt (.vcxproj) gefunden. Bei CMake add_compile_options(/source-charset:utf-8) schreiben).", "Impossible d'ajouter /source-charset:utf-8 (aucun projet C++ (.vcxproj) trouvé. Avec CMake, écrivez add_compile_options(/source-charset:utf-8)).", "Не удалось добавить /source-charset:utf-8 (проект C++ (.vcxproj) не найден. Для CMake напишите add_compile_options(/source-charset:utf-8))." },
            ["/source-charset:utf-8 を {0} 個のプロジェクトに付けました"] = new[] { "Added /source-charset:utf-8 to {0} projects", "已为 {0} 个项目添加 /source-charset:utf-8", "/source-charset:utf-8을 프로젝트 {0}개에 붙였습니다", "Se añadió /source-charset:utf-8 a {0} proyectos", "/source-charset:utf-8 adicionado a {0} projetos", "/source-charset:utf-8 zu {0} Projekten hinzugefügt", "/source-charset:utf-8 ajouté à {0} projets", "/source-charset:utf-8 добавлен в проектов: {0}" },
            ["BOM なし UTF-8 のとき、プロジェクトに /source-charset:utf-8 を付ける (MSVC が Shift-JIS として読まないように)"] = new[] { "For UTF-8 without BOM, add /source-charset:utf-8 to the project (so MSVC does not read it as Shift-JIS)", "使用无 BOM 的 UTF-8 时，为项目添加 /source-charset:utf-8（避免 MSVC 按 Shift-JIS 读取）", "BOM 없는 UTF-8일 때 프로젝트에 /source-charset:utf-8 붙이기 (MSVC가 Shift-JIS로 읽지 않도록)", "Para UTF-8 sin BOM, añadir /source-charset:utf-8 al proyecto (para que MSVC no lo lea como Shift-JIS)", "Para UTF-8 sem BOM, adicionar /source-charset:utf-8 ao projeto (para o MSVC não ler como Shift-JIS)", "Bei UTF-8 ohne BOM /source-charset:utf-8 zum Projekt hinzufügen (damit MSVC es nicht als Shift-JIS liest)", "Pour l'UTF-8 sans BOM, ajouter /source-charset:utf-8 au projet (pour que MSVC ne le lise pas en Shift-JIS)", "Для UTF-8 без BOM добавлять в проект /source-charset:utf-8 (чтобы MSVC не читал как Shift-JIS)" },
            ["CRLF にそろえる (Windows の標準)"] = new[] { "Unify to CRLF (Windows standard)", "统一为 CRLF（Windows 标准）", "CRLF로 통일 (Windows 표준)", "Unificar en CRLF (estándar de Windows)", "Unificar em CRLF (padrão do Windows)", "Auf CRLF vereinheitlichen (Windows-Standard)", "Uniformiser en CRLF (standard Windows)", "Привести к CRLF (стандарт Windows)" },
            ["K-Cpp: ファイルの文字コードをそろえる"] = new[] { "K-Cpp: Unify file encodings", "K-Cpp: 统一文件编码", "K-Cpp: 파일 인코딩 통일", "K-Cpp: Unificar codificaciones de archivos", "K-Cpp: Unificar codificações dos arquivos", "K-Cpp: Dateikodierungen vereinheitlichen", "K-Cpp: Uniformiser l'encodage des fichiers", "K-Cpp: Привести кодировки файлов к одной" },
            ["LF にそろえる"] = new[] { "Unify to LF", "统一为 LF", "LF로 통일", "Unificar en LF", "Unificar em LF", "Auf LF vereinheitlichen", "Uniformiser en LF", "Привести к LF" },
            ["Shift-JIS (CP932) … 古いプロジェクトに合わせるとき"] = new[] { "Shift-JIS (CP932) … to match older projects", "Shift-JIS (CP932) … 配合旧项目时", "Shift-JIS (CP932) … 오래된 프로젝트에 맞출 때", "Shift-JIS (CP932) … para coincidir con proyectos antiguos", "Shift-JIS (CP932) … para combinar com projetos antigos", "Shift-JIS (CP932) … passend zu älteren Projekten", "Shift-JIS (CP932) … pour correspondre aux anciens projets", "Shift-JIS (CP932) … под старые проекты" },
            ["UTF-8 (BOM なし) … Git や他のエディターと相性がよい。MSVC には /source-charset:utf-8 が要ります"] = new[] { "UTF-8 (no BOM) … works well with Git and other editors. MSVC needs /source-charset:utf-8", "UTF-8（无 BOM）… 与 Git 及其他编辑器兼容性好。MSVC 需要 /source-charset:utf-8", "UTF-8 (BOM 없음) … Git이나 다른 편집기와 잘 맞습니다. MSVC에는 /source-charset:utf-8이 필요합니다", "UTF-8 (sin BOM) … funciona bien con Git y otros editores. MSVC necesita /source-charset:utf-8", "UTF-8 (sem BOM) … funciona bem com Git e outros editores. O MSVC precisa de /source-charset:utf-8", "UTF-8 (ohne BOM) … funktioniert gut mit Git und anderen Editoren. MSVC braucht /source-charset:utf-8", "UTF-8 (sans BOM) … fonctionne bien avec Git et d'autres éditeurs. MSVC requiert /source-charset:utf-8", "UTF-8 (без BOM) … хорошо дружит с Git и другими редакторами. MSVC нужен /source-charset:utf-8" },
            ["UTF-8 (BOM 付き) … Visual Studio と MSVC がそのまま読めます (おすすめ)"] = new[] { "UTF-8 (with BOM) … Visual Studio and MSVC read it as is (recommended)", "UTF-8（带 BOM）… Visual Studio 与 MSVC 可直接读取（推荐）", "UTF-8 (BOM 포함) … Visual Studio와 MSVC가 그대로 읽습니다 (추천)", "UTF-8 (con BOM) … Visual Studio y MSVC lo leen tal cual (recomendado)", "UTF-8 (com BOM) … Visual Studio e MSVC leem como está (recomendado)", "UTF-8 (mit BOM) … Visual Studio und MSVC lesen es direkt (empfohlen)", "UTF-8 (avec BOM) … Visual Studio et MSVC le lisent tel quel (recommandé)", "UTF-8 (с BOM) … Visual Studio и MSVC читают как есть (рекомендуется)" },
            ["\n.editorconfig は Shift-JIS を書けない (規格にない) ので、文字コードは書きません。改行だけ書きます。"] = new[] { "\n.editorconfig cannot specify Shift-JIS (not in the spec), so the encoding is not written. Only the line ending is written.", "\n.editorconfig 无法写入 Shift-JIS（规范中没有），因此不写编码。只写换行。", "\n.editorconfig는 Shift-JIS를 쓸 수 없어(규격에 없음) 인코딩은 쓰지 않습니다. 줄바꿈만 씁니다.", "\n.editorconfig no puede especificar Shift-JIS (no está en la especificación), así que no se escribe la codificación. Solo se escribe el fin de línea.", "\n.editorconfig não pode especificar Shift-JIS (não está na especificação), então a codificação não é escrita. Só a quebra de linha é escrita.", "\n.editorconfig kann Shift-JIS nicht angeben (nicht in der Spezifikation), daher wird die Kodierung nicht geschrieben. Nur das Zeilenende wird geschrieben.", "\n.editorconfig ne peut pas indiquer Shift-JIS (absent de la spécification) : l'encodage n'est pas écrit. Seule la fin de ligne l'est.", "\n.editorconfig не умеет задавать Shift-JIS (нет в спецификации), поэтому кодировка не записывается. Записывается только перевод строк." },
            ["\n開いていないファイルは、そのまま保存します (Ctrl+Z では戻せません。戻すときは Git などを使います)。"] = new[] { "\nFiles that are not open are saved directly (Ctrl+Z cannot undo this; use Git etc. to revert).", "\n未打开的文件将直接保存（无法用 Ctrl+Z 撤销；请用 Git 等恢复）。", "\n열려 있지 않은 파일은 그대로 저장합니다 (Ctrl+Z로 되돌릴 수 없습니다. 되돌릴 때는 Git 등을 쓰세요).", "\nLos archivos no abiertos se guardan directamente (Ctrl+Z no lo deshace; use Git, etc. para revertir).", "\nArquivos não abertos são salvos diretamente (Ctrl+Z não desfaz; use Git etc. para reverter).", "\nNicht geöffnete Dateien werden direkt gespeichert (Ctrl+Z macht das nicht rückgängig; zum Zurücksetzen Git o. Ä. verwenden).", "\nLes fichiers non ouverts sont enregistrés directement (Ctrl+Z ne peut pas l'annuler ; utilisez Git, etc. pour revenir en arrière).", "\nНеоткрытые файлы сохраняются сразу (Ctrl+Z не отменит; для отката используйте Git и т. п.)." },
