            ["リンカー > 入力 > 追加の依存ファイル に {0} を追加します。"] = new[] { "Add {0} to Linker > Input > Additional Dependencies.", "将 {0} 添加到“链接器 > 输入 > 附加依赖项”。", "링커 > 입력 > 추가 종속성에 {0}을(를) 추가합니다.", "Añada {0} a Vinculador > Entrada > Dependencias adicionales.", "Adicione {0} em Vinculador > Entrada > Dependências adicionais.", "{0} zu Linker > Eingabe > Zusätzliche Abhängigkeiten hinzufügen.", "Ajoutez {0} à Éditeur de liens > Entrée > Dépendances supplémentaires.", "Добавьте {0} в «Компоновщик > Ввод > Дополнительные зависимости»." },
            ["リンカー > 全般 > 追加のライブラリ ディレクトリ に {0} を追加します(絶対パスでも可)。"] = new[] { "Add {0} to Linker > General > Additional Library Directories (an absolute path is fine).", "将 {0} 添加到“链接器 > 常规 > 附加库目录”（绝对路径也可以）。", "링커 > 일반 > 추가 라이브러리 디렉터리에 {0}을(를) 추가합니다(절대 경로도 가능).", "Añada {0} a Vinculador > General > Directorios de bibliotecas adicionales (vale una ruta absoluta).", "Adicione {0} em Vinculador > Geral > Diretórios de bibliotecas adicionais (caminho absoluto também serve).", "{0} zu Linker > Allgemein > Zusätzliche Bibliotheksverzeichnisse hinzufügen (absoluter Pfad geht auch).", "Ajoutez {0} à Éditeur de liens > Général > Répertoires de bibliothèques supplémentaires (un chemin absolu convient).", "Добавьте {0} в «Компоновщик > Общие > Дополнительные каталоги библиотек» (можно абсолютный путь)." },
            ["同じソリューション内のプロジェクトなら、参照の追加(プロジェクト参照)で、リンクが自動で済みます。"] = new[] { "If it is a project in the same solution, adding a reference (project reference) links it automatically.", "如果是同一解决方案中的项目，添加引用（项目引用）即可自动链接。", "같은 솔루션 안의 프로젝트라면 참조 추가(프로젝트 참조)로 링크가 자동으로 됩니다.", "Si es un proyecto de la misma solución, agregar una referencia (referencia de proyecto) lo enlaza automáticamente.", "Se for um projeto da mesma solução, adicionar uma referência (referência de projeto) vincula automaticamente.", "Ist es ein Projekt derselben Projektmappe, linkt ein Verweis (Projektverweis) automatisch.", "S'il s'agit d'un projet de la même solution, ajouter une référence (référence de projet) le lie automatiquement.", "Если это проект в том же решении, добавление ссылки (ссылки на проект) скомпонует его автоматически." },
            ["コードで済ませるなら、#pragma comment(lib, \"{0}\") でも同じ効果です。"] = new[] { "To do it in code, #pragma comment(lib, \"{0}\") has the same effect.", "如果想在代码中解决，#pragma comment(lib, \"{0}\") 也有同样效果。", "코드로 처리하려면 #pragma comment(lib, \"{0}\")도 같은 효과입니다.", "Para hacerlo en código, #pragma comment(lib, \"{0}\") tiene el mismo efecto.", "Para fazer no código, #pragma comment(lib, \"{0}\") tem o mesmo efeito.", "Im Code hat #pragma comment(lib, \"{0}\") dieselbe Wirkung.", "Dans le code, #pragma comment(lib, \"{0}\") a le même effet.", "В коде то же самое делает #pragma comment(lib, \"{0}\")." },
            ["{0} はビット数が違います ({1})"] = new[] { "{0} has a different bitness ({1})", "{0} 的位数不同（{1}）", "{0}은(는) 비트 수가 다릅니다({1})", "{0} tiene otra arquitectura ({1})", "{0} tem outra arquitetura ({1})", "{0} hat eine andere Bitbreite ({1})", "{0} n'a pas la même architecture ({1})", "У {0} другая разрядность ({1})" },
            ["{0} に実体はありますが、{1} 用です。いまのビルドは {2} です。"] = new[] { "{0} has the definition, but it is for {1}. The current build is {2}.", "{0} 中有实体，但它是 {1} 用的。当前生成是 {2}。", "{0}에 실체는 있지만 {1}용입니다. 현재 빌드는 {2}입니다.", "{0} tiene la definición, pero es para {1}. La compilación actual es {2}.", "{0} tem a definição, mas é para {1}. A compilação atual é {2}.", "{0} enthält die Definition, aber für {1}. Der aktuelle Build ist {2}.", "{0} contient la définition, mais pour {1}. La génération actuelle est {2}.", "В {0} определение есть, но для {1}. Текущая сборка — {2}." },
            ["同じプラットフォーム ({0}) でビルドした .lib を使います。"] = new[] { "Use a .lib built for the same platform ({0}).", "使用以相同平台（{0}）生成的 .lib。", "같은 플랫폼({0})으로 빌드한 .lib를 사용합니다.", "Use un .lib compilado para la misma plataforma ({0}).", "Use um .lib compilado para a mesma plataforma ({0}).", "Eine für dieselbe Plattform ({0}) erstellte .lib verwenden.", "Utilisez un .lib généré pour la même plateforme ({0}).", "Используйте .lib, собранный для той же платформы ({0})." },
            ["ライブラリのプロジェクトも、アクティブなプラットフォームでビルドしたか確かめます。"] = new[] { "Check that the library project was also built for the active platform.", "确认库项目也是以活动平台生成的。", "라이브러리 프로젝트도 활성 플랫폼으로 빌드했는지 확인합니다.", "Compruebe que el proyecto de la biblioteca también se compiló para la plataforma activa.", "Verifique se o projeto da biblioteca também foi compilado para a plataforma ativa.", "Prüfen, ob auch das Bibliotheksprojekt für die aktive Plattform erstellt wurde.", "Vérifiez que le projet de bibliothèque a aussi été généré pour la plateforme active.", "Проверьте, что проект библиотеки тоже собран для активной платформы." },
            ["{0} は静的ライブラリですが、ヘッダーは dllimport で宣言しています"] = new[] { "{0} is a static library, but the header declares with dllimport", "{0} 是静态库，但头文件用 dllimport 声明", "{0}은(는) 정적 라이브러리인데 헤더는 dllimport로 선언하고 있습니다", "{0} es una biblioteca estática, pero el encabezado declara con dllimport", "{0} é uma biblioteca estática, mas o cabeçalho declara com dllimport", "{0} ist eine statische Bibliothek, aber der Header deklariert mit dllimport", "{0} est une bibliothèque statique, mais l'en-tête déclare avec dllimport", "{0} — статическая библиотека, но заголовок объявляет с dllimport" },
            ["シンボル名の頭の __imp_ は、ヘッダーが __declspec(dllimport) で宣言している印です。ところが {0} には、__imp_ の付かない普通のシンボルしかありません (静的ライブラリ)。"] = new[] { "The __imp_ at the start of the symbol name means the header declares it with __declspec(dllimport). But {0} only has ordinary symbols without __imp_ (a static library).", "符号名开头的 __imp_ 表示头文件用 __declspec(dllimport) 声明。但 {0} 中只有不带 __imp_ 的普通符号（静态库）。", "심볼 이름 앞의 __imp_는 헤더가 __declspec(dllimport)로 선언했다는 표시입니다. 그런데 {0}에는 __imp_가 붙지 않은 보통 심볼만 있습니다(정적 라이브러리).", "El __imp_ al inicio del nombre del símbolo indica que el encabezado lo declara con __declspec(dllimport). Pero {0} solo tiene símbolos normales sin __imp_ (biblioteca estática).", "O __imp_ no início do nome do símbolo indica que o cabeçalho o declara com __declspec(dllimport). Mas {0} só tem símbolos comuns sem __imp_ (biblioteca estática).", "Das __imp_ am Anfang des Symbolnamens zeigt, dass der Header mit __declspec(dllimport) deklariert. {0} enthält aber nur normale Symbole ohne __imp_ (statische Bibliothek).", "Le __imp_ en tête du nom de symbole indique que l'en-tête le déclare avec __declspec(dllimport). Mais {0} ne contient que des symboles ordinaires sans __imp_ (bibliothèque statique).", "Префикс __imp_ в имени символа означает, что заголовок объявляет его с __declspec(dllimport). Но в {0} только обычные символы без __imp_ (статическая библиотека)." },
            ["ヘッダーの API マクロ (PREST_API など) が、静的ライブラリのときは何も展開されないようにします。多くは「XXX_STATIC」のようなマクロを定義します。"] = new[] { "Make the header's API macro (PREST_API, etc.) expand to nothing for a static library. Usually you define a macro like \"XXX_STATIC\".", "让头文件的 API 宏（PREST_API 等）在静态库时什么都不展开。通常定义类似“XXX_STATIC”的宏。", "헤더의 API 매크로(PREST_API 등)가 정적 라이브러리일 때는 아무것도 전개되지 않게 합니다. 보통 \"XXX_STATIC\" 같은 매크로를 정의합니다.", "Haga que la macro de API del encabezado (PREST_API, etc.) no se expanda a nada con biblioteca estática. Normalmente se define una macro como \"XXX_STATIC\".", "Faça a macro de API do cabeçalho (PREST_API etc.) não expandir para nada em biblioteca estática. Normalmente se define uma macro como \"XXX_STATIC\".", "Das API-Makro des Headers (PREST_API usw.) bei statischer Bibliothek zu nichts expandieren lassen. Meist definiert man ein Makro wie \"XXX_STATIC\".", "Faites en sorte que la macro d'API de l'en-tête (PREST_API, etc.) ne se développe en rien pour une bibliothèque statique. On définit souvent une macro comme « XXX_STATIC ».", "Сделайте, чтобы макрос API заголовка (PREST_API и т. п.) для статической библиотеки ни во что не раскрывался. Обычно определяют макрос вроде «XXX_STATIC»." },
            ["利用側のプロジェクトに、そのマクロが定義されているか確かめます (プリプロセッサの定義)。"] = new[] { "Check that the consuming project defines that macro (preprocessor definitions).", "确认使用方的项目定义了那个宏（预处理器定义）。", "사용하는 쪽 프로젝트에 그 매크로가 정의되어 있는지 확인합니다(전처리기 정의).", "Compruebe que el proyecto que la usa define esa macro (definiciones del preprocesador).", "Verifique se o projeto que a usa define essa macro (definições do pré-processador).", "Prüfen, ob das nutzende Projekt dieses Makro definiert (Präprozessordefinitionen).", "Vérifiez que le projet utilisateur définit cette macro (définitions du préprocesseur).", "Проверьте, что в использующем проекте определён этот макрос (определения препроцессора)." },
            ["DLL として使うつもりなら、提供元を DLL でビルドし直して、その import lib をリンクします。"] = new[] { "If you mean to use it as a DLL, rebuild the provider as a DLL and link its import lib.", "如果打算作为 DLL 使用，就把提供方重新生成为 DLL，并链接其 import lib。", "DLL로 쓸 생각이라면 제공 측을 DLL로 다시 빌드하고 그 import lib를 링크합니다.", "Si quiere usarla como DLL, recompile el proveedor como DLL y enlace su import lib.", "Se quer usá-la como DLL, recompile o fornecedor como DLL e vincule sua import lib.", "Soll sie als DLL genutzt werden, den Anbieter als DLL neu erstellen und dessen Importbibliothek linken.", "Pour l'utiliser en DLL, régénérez le fournisseur en DLL et liez son import lib.", "Если нужна DLL, пересоберите поставщика как DLL и скомпонуйте его import lib." },
            ["{0} の変数を、dllimport なしで参照しています"] = new[] { "A variable from {0} is referenced without dllimport", "在没有 dllimport 的情况下引用了 {0} 的变量", "{0}의 변수를 dllimport 없이 참조하고 있습니다", "Se referencia una variable de {0} sin dllimport", "Uma variável de {0} é referenciada sem dllimport", "Eine Variable aus {0} wird ohne dllimport referenziert", "Une variable de {0} est référencée sans dllimport", "Переменная из {0} используется без dllimport" },
            ["DLL が持つ変数 (データ) は、__declspec(dllimport) 付きで宣言しないと参照できません。関数と違い、変数にはリンク用の代わりの入口がありません。"] = new[] { "A variable (data) owned by a DLL can only be referenced if declared with __declspec(dllimport). Unlike functions, variables have no substitute entry point for linking.", "DLL 拥有的变量（数据）必须用 __declspec(dllimport) 声明才能引用。与函数不同，变量没有用于链接的替代入口。", "DLL이 가진 변수(데이터)는 __declspec(dllimport)를 붙여 선언하지 않으면 참조할 수 없습니다. 함수와 달리 변수에는 링크용 대체 입구가 없습니다.", "Una variable (datos) de una DLL solo se puede referenciar si se declara con __declspec(dllimport). A diferencia de las funciones, las variables no tienen un punto de entrada alternativo para enlazar.", "Uma variável (dados) de uma DLL só pode ser referenciada se declarada com __declspec(dllimport). Diferente das funções, variáveis não têm entrada alternativa para vincular.", "Variablen (Daten) einer DLL lassen sich nur mit __declspec(dllimport)-Deklaration referenzieren. Anders als Funktionen haben Variablen keinen Ersatzeinstieg fürs Linken.", "Une variable (donnée) d'une DLL ne peut être référencée que si elle est déclarée avec __declspec(dllimport). Contrairement aux fonctions, les variables n'ont pas de point d'entrée de substitution pour la liaison.", "Переменную (данные) DLL можно использовать, только объявив с __declspec(dllimport). В отличие от функций, у переменных нет запасной точки входа для компоновки." },
            ["ヘッダーで、変数の宣言に API マクロ (dllimport を展開するもの) を付けます。"] = new[] { "In the header, put the API macro (the one that expands to dllimport) on the variable declaration.", "在头文件中，给变量声明加上 API 宏（展开为 dllimport 的那个）。", "헤더에서 변수 선언에 API 매크로(dllimport로 전개되는 것)를 붙입니다.", "En el encabezado, ponga la macro de API (la que se expande a dllimport) en la declaración de la variable.", "No cabeçalho, coloque a macro de API (a que expande para dllimport) na declaração da variável.", "Im Header das API-Makro (das zu dllimport expandiert) an die Variablendeklaration setzen.", "Dans l'en-tête, mettez la macro d'API (celle qui donne dllimport) sur la déclaration de la variable.", "В заголовке добавьте к объявлению переменной макрос API (раскрывающийся в dllimport)." },
            ["C ランタイム(CRT)の内部の関数が見つかりません"] = new[] { "Internal C runtime (CRT) function not found", "找不到 C 运行时（CRT）的内部函数", "C 런타임(CRT) 내부 함수를 찾을 수 없습니다", "No se encuentra una función interna del runtime de C (CRT)", "Função interna do runtime C (CRT) não encontrada", "Interne Funktion der C-Laufzeit (CRT) nicht gefunden", "Fonction interne du runtime C (CRT) introuvable", "Не найдена внутренняя функция среды выполнения C (CRT)" },
            ["これらはコンパイラが自動で呼び出す関数で、ランタイム ライブラリ (vcruntime / ucrt) が提供します。ランタイムがリンクされていない構成で出ます。"] = new[] { "These are functions the compiler calls automatically, provided by the runtime library (vcruntime / ucrt). This appears in configurations where the runtime is not linked.", "这些是编译器自动调用的函数，由运行时库（vcruntime / ucrt）提供。在未链接运行时的配置中会出现。", "이것들은 컴파일러가 자동으로 호출하는 함수로, 런타임 라이브러리(vcruntime / ucrt)가 제공합니다. 런타임이 링크되지 않은 구성에서 나옵니다.", "Son funciones que el compilador llama automáticamente, provistas por la biblioteca de runtime (vcruntime / ucrt). Aparece en configuraciones donde el runtime no se enlaza.", "São funções que o compilador chama automaticamente, fornecidas pela biblioteca de runtime (vcruntime / ucrt). Aparece em configurações em que o runtime não é vinculado.", "Diese Funktionen ruft der Compiler automatisch auf; die Laufzeitbibliothek (vcruntime / ucrt) stellt sie bereit. Tritt in Konfigurationen ohne gelinkte Laufzeit auf.", "Ce sont des fonctions appelées automatiquement par le compilateur, fournies par la bibliothèque runtime (vcruntime / ucrt). Cela apparaît quand le runtime n'est pas lié.", "Эти функции компилятор вызывает автоматически; их даёт библиотека среды выполнения (vcruntime / ucrt). Возникает в конфигурациях, где она не компонуется." },
            ["リンカー > 入力 > 「すべての既定のライブラリを無視」が「はい (/NODEFAULTLIB)」になっていないか確かめます。"] = new[] { "Check that Linker > Input > \"Ignore All Default Libraries\" is not \"Yes (/NODEFAULTLIB)\".", "确认“链接器 > 输入 > 忽略所有默认库”没有设为“是 (/NODEFAULTLIB)”。", "링커 > 입력 > \"모든 기본 라이브러리 무시\"가 \"예 (/NODEFAULTLIB)\"로 되어 있지 않은지 확인합니다.", "Compruebe que Vinculador > Entrada > \"Omitir todas las bibliotecas predeterminadas\" no esté en \"Sí (/NODEFAULTLIB)\".", "Verifique se Vinculador > Entrada > \"Ignorar todas as bibliotecas padrão\" não está em \"Sim (/NODEFAULTLIB)\".", "Prüfen, ob Linker > Eingabe > \"Alle Standardbibliotheken ignorieren\" nicht auf \"Ja (/NODEFAULTLIB)\" steht.", "Vérifiez que Éditeur de liens > Entrée > « Ignorer toutes les bibliothèques par défaut » n'est pas sur « Oui (/NODEFAULTLIB) ».", "Проверьте, что «Компоновщик > Ввод > Игнорировать все стандартные библиотеки» не равно «Да (/NODEFAULTLIB)»." },
            ["カーネル モードやスタートアップを自作する構成なら、_fltused や __security_cookie などを自分で定義します。"] = new[] { "For kernel mode or a custom startup, define _fltused, __security_cookie and so on yourself.", "如果是内核模式或自制启动代码的配置，请自己定义 _fltused 或 __security_cookie 等。", "커널 모드나 스타트업을 직접 만드는 구성이라면 _fltused나 __security_cookie 등을 직접 정의합니다.", "En modo kernel o con un arranque propio, defina usted mismo _fltused, __security_cookie, etc.", "Em modo kernel ou com inicialização própria, defina você mesmo _fltused, __security_cookie etc.", "Bei Kernelmodus oder eigenem Startcode _fltused, __security_cookie usw. selbst definieren.", "En mode noyau ou avec un démarrage personnalisé, définissez vous-même _fltused, __security_cookie, etc.", "Для режима ядра или своего кода запуска определите _fltused, __security_cookie и т. п. сами." },
            ["/GS (バッファー セキュリティ チェック) を切ると、__security_cookie の参照は消えます。"] = new[] { "Turning off /GS (Buffer Security Check) removes the reference to __security_cookie.", "关闭 /GS（缓冲区安全检查）后，对 __security_cookie 的引用会消失。", "/GS(버퍼 보안 검사)를 끄면 __security_cookie 참조가 사라집니다.", "Al desactivar /GS (comprobación de seguridad del búfer), desaparece la referencia a __security_cookie.", "Desligar /GS (verificação de segurança de buffer) remove a referência a __security_cookie.", "Wird /GS (Puffersicherheitsüberprüfung) abgeschaltet, entfällt der Verweis auf __security_cookie.", "Désactiver /GS (vérification de la sécurité de la mémoire tampon) supprime la référence à __security_cookie.", "Если отключить /GS (проверку безопасности буфера), ссылка на __security_cookie исчезнет." },
            ["/MT と /MD の混在や、別のコンパイラで作った .lib のときも出ます。ランタイム ライブラリをそろえます。"] = new[] { "It also appears when /MT and /MD are mixed, or with a .lib built by another compiler. Make the runtime libraries match.", "/MT 与 /MD 混用，或使用其他编译器生成的 .lib 时也会出现。请统一运行时库。", "/MT와 /MD가 섞였거나 다른 컴파일러로 만든 .lib일 때도 나옵니다. 런타임 라이브러리를 맞춥니다.", "También aparece al mezclar /MT y /MD, o con un .lib de otro compilador. Unifique las bibliotecas de runtime.", "Também aparece ao misturar /MT e /MD, ou com um .lib de outro compilador. Unifique as bibliotecas de runtime.", "Tritt auch auf, wenn /MT und /MD gemischt werden oder bei einer .lib eines anderen Compilers. Laufzeitbibliotheken angleichen.", "Cela apparaît aussi en mélangeant /MT et /MD, ou avec un .lib d'un autre compilateur. Harmonisez les bibliothèques runtime.", "Бывает и при смешении /MT и /MD или с .lib от другого компилятора. Приведите библиотеки среды выполнения к одной." },
            ["Windows / SDK の関数です ({0} が必要)"] = new[] { "A Windows / SDK function ({0} needed)", "这是 Windows / SDK 的函数（需要 {0}）", "Windows / SDK 함수입니다({0} 필요)", "Es una función de Windows / SDK (se necesita {0})", "É uma função do Windows / SDK (precisa de {0})", "Eine Windows-/SDK-Funktion ({0} nötig)", "Fonction Windows / SDK ({0} requis)", "Функция Windows / SDK (нужен {0})" },
            ["これらは {0} が提供する関数です。ヘッダーを include しただけでは、リンクされません。"] = new[] { "These functions are provided by {0}. Including the header alone does not link it.", "这些是 {0} 提供的函数。只 include 头文件不会链接。", "이것들은 {0}이(가) 제공하는 함수입니다. 헤더를 include하는 것만으로는 링크되지 않습니다.", "Estas funciones las proporciona {0}. Incluir el encabezado no basta para enlazarlas.", "Estas funções são fornecidas por {0}. Só incluir o cabeçalho não as vincula.", "Diese Funktionen stellt {0} bereit. Nur den Header einzubinden linkt sie nicht.", "Ces fonctions sont fournies par {0}. Inclure l'en-tête ne suffit pas à les lier.", "Эти функции предоставляет {0}. Одно подключение заголовка их не компонует." },
            ["{0} の vtable (仮想関数の表) が見つかりません"] = new[] { "vtable (virtual function table) of {0} not found", "找不到 {0} 的 vtable（虚函数表）", "{0}의 vtable(가상 함수 표)을 찾을 수 없습니다", "No se encuentra la vtable (tabla de funciones virtuales) de {0}", "vtable (tabela de funções virtuais) de {0} não encontrada", "vtable (Tabelle virtueller Funktionen) von {0} nicht gefunden", "vtable (table des fonctions virtuelles) de {0} introuvable", "Не найдена vtable (таблица виртуальных функций) {0}" },
            ["vtable は、最初の非 inline の仮想関数 (キー関数) の定義と一緒に作られます。そのため、仮想関数の定義が 1 つ抜けていると、vtable ごと未解決になります。"] = new[] { "The vtable is created along with the definition of the first non-inline virtual function (the key function). So if one virtual function definition is missing, the whole vtable becomes unresolved.", "vtable 与第一个非 inline 虚函数（关键函数）的定义一起生成。因此缺少一个虚函数的定义，整个 vtable 都会无法解析。", "vtable은 첫 번째 비 inline 가상 함수(키 함수)의 정의와 함께 만들어집니다. 그래서 가상 함수 정의가 하나 빠지면 vtable 전체가 미해결이 됩니다.", "La vtable se crea junto con la definición de la primera función virtual no inline (la función clave). Por eso, si falta la definición de una función virtual, toda la vtable queda sin resolver.", "A vtable é criada junto com a definição da primeira função virtual não inline (a função-chave). Por isso, se faltar a definição de uma função virtual, a vtable inteira fica não resolvida.", "Die vtable entsteht mit der Definition der ersten nicht-inline virtuellen Funktion (Schlüsselfunktion). Fehlt eine Definition einer virtuellen Funktion, bleibt daher die ganze vtable unaufgelöst.", "La vtable est créée avec la définition de la première fonction virtuelle non inline (fonction clé). Si une définition de fonction virtuelle manque, toute la vtable reste donc non résolue.", "vtable создаётся вместе с определением первой не-inline виртуальной функции (ключевой функции). Поэтому если нет определения одной виртуальной функции, неразрешённой становится вся vtable." },
            ["{0} の virtual 関数 (純粋仮想関数 = 0 を除く) の、すべてに定義があるか確かめます。"] = new[] { "Check that every virtual function of {0} (except pure virtual = 0) has a definition.", "确认 {0} 的所有 virtual 函数（纯虚函数 = 0 除外）都有定义。", "{0}의 virtual 함수(순수 가상 함수 = 0 제외) 모두에 정의가 있는지 확인합니다.", "Compruebe que todas las funciones virtual de {0} (salvo las virtuales puras = 0) tienen definición.", "Verifique se todas as funções virtual de {0} (exceto virtuais puras = 0) têm definição.", "Prüfen, ob alle virtual-Funktionen von {0} (außer rein virtuellen = 0) definiert sind.", "Vérifiez que toutes les fonctions virtual de {0} (sauf virtuelles pures = 0) ont une définition.", "Проверьте, что у всех virtual-функций {0} (кроме чисто виртуальных = 0) есть определения." },
            ["virtual デストラクターの定義 (または = default) を書き忘れていないか確かめます。"] = new[] { "Check that you did not forget the definition of the virtual destructor (or = default).", "确认没有忘记写 virtual 析构函数的定义（或 = default）。", "virtual 소멸자의 정의(또는 = default)를 빠뜨리지 않았는지 확인합니다.", "Compruebe que no olvidó la definición del destructor virtual (o = default).", "Verifique se não esqueceu a definição do destrutor virtual (ou = default).", "Prüfen, ob die Definition des virtuellen Destruktors (oder = default) fehlt.", "Vérifiez que vous n'avez pas oublié la définition du destructeur virtuel (ou = default).", "Проверьте, не забыто ли определение виртуального деструктора (или = default)." },
            ["そのクラスの .cpp が、プロジェクトに入っているか確かめます。"] = new[] { "Check that the class's .cpp is in the project.", "确认该类的 .cpp 在项目中。", "그 클래스의 .cpp가 프로젝트에 들어 있는지 확인합니다.", "Compruebe que el .cpp de la clase está en el proyecto.", "Verifique se o .cpp da classe está no projeto.", "Prüfen, ob die .cpp der Klasse im Projekt ist.", "Vérifiez que le .cpp de la classe est dans le projet.", "Проверьте, что .cpp класса входит в проект." },
            ["(グローバル)"] = new[] { "(global)", "（全局）", "(전역)", "(global)", "(global)", "(global)", "(global)", "(глобальная)" },
            ["{0} の static メンバー変数の定義がありません"] = new[] { "Definition of static member variable of {0} is missing", "缺少 {0} 的 static 成员变量的定义", "{0}의 static 멤버 변수 정의가 없습니다", "Falta la definición de la variable miembro static de {0}", "Falta a definição da variável membro static de {0}", "Definition der static-Membervariable von {0} fehlt", "Définition de la variable membre static de {0} manquante", "Нет определения static-переменной-члена {0}" },
            ["グローバル変数の定義がありません"] = new[] { "Definition of global variable is missing", "缺少全局变量的定义", "전역 변수 정의가 없습니다", "Falta la definición de la variable global", "Falta a definição da variável global", "Definition der globalen Variable fehlt", "Définition de la variable globale manquante", "Нет определения глобальной переменной" },
            ["static メンバーや extern の宣言だけでは、実体は作られません。.cpp に 1 つだけ、定義が要ります。"] = new[] { "A static member or extern declaration alone does not create the object. One definition is needed in exactly one .cpp.", "只有 static 成员或 extern 声明不会创建实体。需要在某一个 .cpp 中写且只写一个定义。", "static 멤버나 extern 선언만으로는 실체가 만들어지지 않습니다. .cpp 하나에 정의가 하나만 필요합니다.", "Una declaración static de miembro o extern por sí sola no crea el objeto. Hace falta una única definición en un .cpp.", "Só a declaração de membro static ou extern não cria o objeto. É preciso uma única definição em um .cpp.", "Eine static-Member- oder extern-Deklaration allein erzeugt kein Objekt. Es braucht genau eine Definition in einer .cpp.", "Une déclaration de membre static ou extern seule ne crée pas l'objet. Il faut une seule définition dans un .cpp.", "Одного объявления static-члена или extern недостаточно — объект не создаётся. Нужно ровно одно определение в одном .cpp." },
            ["いずれかの .cpp に、型を付けて定義を書きます (例: int {0}{1} = 0;)。"] = new[] { "Write a definition with its type in one of the .cpp files (e.g. int {0}{1} = 0;).", "在某个 .cpp 中带上类型写出定义（例：int {0}{1} = 0;）。", ".cpp 중 하나에 타입을 붙여 정의를 씁니다(예: int {0}{1} = 0;).", "Escriba la definición con su tipo en uno de los .cpp (p. ej. int {0}{1} = 0;).", "Escreva a definição com o tipo em um dos .cpp (ex.: int {0}{1} = 0;).", "In einer der .cpp eine Definition mit Typ schreiben (z. B. int {0}{1} = 0;).", "Écrivez une définition avec son type dans l'un des .cpp (ex. int {0}{1} = 0;).", "Напишите определение с типом в одном из .cpp (например, int {0}{1} = 0;)." },
            ["C++17 以降なら、宣言を inline static (または inline constexpr) にすると、ヘッダーだけで済みます。"] = new[] { "In C++17 or later, making the declaration inline static (or inline constexpr) lets the header alone do it.", "C++17 以后，把声明写成 inline static（或 inline constexpr）就只需头文件。", "C++17 이후라면 선언을 inline static(또는 inline constexpr)으로 하면 헤더만으로 됩니다.", "Desde C++17, declarar inline static (o inline constexpr) basta con el encabezado.", "A partir do C++17, declarar inline static (ou inline constexpr) resolve só com o cabeçalho.", "Ab C++17 genügt der Header, wenn die Deklaration inline static (oder inline constexpr) ist.", "À partir de C++17, déclarer inline static (ou inline constexpr) suffit dans l'en-tête.", "С C++17 достаточно заголовка, если объявить inline static (или inline constexpr)." },
            ["ソースに定義らしい行がありました。その .cpp が、プロジェクトに入っているか確かめます。"] = new[] { "A line that looks like the definition was found in the source. Check that its .cpp is in the project.", "源代码中有疑似定义的行。确认那个 .cpp 在项目中。", "소스에 정의로 보이는 줄이 있었습니다. 그 .cpp가 프로젝트에 들어 있는지 확인합니다.", "En el código hay una línea que parece la definición. Compruebe que su .cpp está en el proyecto.", "Há uma linha no código que parece a definição. Verifique se seu .cpp está no projeto.", "Im Quellcode gibt es eine Zeile, die wie die Definition aussieht. Prüfen, ob deren .cpp im Projekt ist.", "Une ligne ressemblant à la définition existe dans le source. Vérifiez que son .cpp est dans le projet.", "В исходниках есть строка, похожая на определение. Проверьте, что её .cpp входит в проект." },
            ["定義はソースにあるのに、リンクされていません"] = new[] { "The definition is in the source but not linked", "定义在源代码中，却没有被链接", "정의는 소스에 있는데 링크되지 않았습니다", "La definición está en el código pero no se enlaza", "A definição está no código, mas não é vinculada", "Die Definition ist im Quellcode, wird aber nicht gelinkt", "La définition est dans le source mais n'est pas liée", "Определение есть в исходниках, но не скомпоновано" },
            ["ソースの中に、これらの関数の定義らしい行が見つかりました (各項目の下に示します)。それでも未解決になるのは、その定義が、このプロジェクトのリンクに入っていないからです。"] = new[] { "Lines that look like definitions of these functions were found in the source (shown under each item). It is still unresolved because those definitions are not in this project's link.", "在源代码中找到了疑似这些函数定义的行（显示在各项下方）。仍然无法解析，是因为这些定义不在此项目的链接中。", "소스 안에서 이 함수들의 정의로 보이는 줄이 발견되었습니다(각 항목 아래에 표시). 그래도 미해결인 것은 그 정의가 이 프로젝트의 링크에 들어 있지 않기 때문입니다.", "Se encontraron en el código líneas que parecen definiciones de estas funciones (se muestran bajo cada elemento). Siguen sin resolverse porque esas definiciones no entran en el enlace de este proyecto.", "Foram encontradas no código linhas que parecem definições destas funções (mostradas sob cada item). Continuam não resolvidas porque essas definições não entram no link deste projeto.", "Im Quellcode wurden Zeilen gefunden, die wie Definitionen dieser Funktionen aussehen (unter jedem Eintrag). Ungelöst bleiben sie, weil diese Definitionen nicht im Link dieses Projekts sind.", "Des lignes ressemblant aux définitions de ces fonctions ont été trouvées dans le source (affichées sous chaque élément). Elles restent non résolues car ces définitions ne font pas partie de la liaison de ce projet.", "В исходниках найдены строки, похожие на определения этих функций (показаны под каждым пунктом). Символы не разрешены, потому что эти определения не попадают в компоновку этого проекта." },
            ["シンボルに __imp_ が付いているので、定義は別の DLL プロジェクトにあり、その import lib (.lib) が必要です。"] = new[] { "The symbol has __imp_, so the definition is in another DLL project and its import lib (.lib) is needed.", "符号带有 __imp_，所以定义在另一个 DLL 项目中，需要它的 import lib（.lib）。", "심볼에 __imp_가 붙어 있으므로 정의는 다른 DLL 프로젝트에 있고, 그 import lib(.lib)가 필요합니다.", "El símbolo tiene __imp_, así que la definición está en otro proyecto DLL y se necesita su import lib (.lib).", "O símbolo tem __imp_, então a definição está em outro projeto de DLL e é preciso sua import lib (.lib).", "Das Symbol hat __imp_, die Definition liegt also in einem anderen DLL-Projekt; dessen Importbibliothek (.lib) wird benötigt.", "Le symbole a __imp_ : la définition est dans un autre projet DLL et son import lib (.lib) est nécessaire.", "У символа есть __imp_, значит определение в другом проекте DLL и нужна его import lib (.lib)." },
            ["その .cpp が、プロジェクトに入っているか (ビルドから除外されていないか) 確かめます。"] = new[] { "Check that the .cpp is in the project (not excluded from the build).", "确认那个 .cpp 在项目中（没有从生成中排除）。", "그 .cpp가 프로젝트에 들어 있는지(빌드에서 제외되지 않았는지) 확인합니다.", "Compruebe que el .cpp está en el proyecto (no excluido de la compilación).", "Verifique se o .cpp está no projeto (não excluído da compilação).", "Prüfen, ob die .cpp im Projekt ist (nicht vom Build ausgeschlossen).", "Vérifiez que le .cpp est dans le projet (non exclu de la génération).", "Проверьте, что .cpp входит в проект (не исключён из сборки)." },
            ["別のプロジェクト (lib / DLL) にあるなら、参照の追加か、追加の依存ファイルで、その .lib をリンクします。"] = new[] { "If it is in another project (lib / DLL), link its .lib by adding a reference or via Additional Dependencies.", "如果在另一个项目（lib / DLL）中，通过添加引用或附加依赖项来链接其 .lib。", "다른 프로젝트(lib / DLL)에 있다면 참조 추가나 추가 종속성으로 그 .lib를 링크합니다.", "Si está en otro proyecto (lib / DLL), enlace su .lib agregando una referencia o con Dependencias adicionales.", "Se estiver em outro projeto (lib / DLL), vincule seu .lib adicionando uma referência ou por Dependências adicionais.", "Liegt es in einem anderen Projekt (lib / DLL), dessen .lib per Verweis oder Zusätzliche Abhängigkeiten linken.", "S'il est dans un autre projet (lib / DLL), liez son .lib via une référence ou les Dépendances supplémentaires.", "Если это в другом проекте (lib / DLL), скомпонуйте его .lib через ссылку или «Дополнительные зависимости»." },
            ["#if や構成の違いで、その定義がコンパイルされていないか確かめます。"] = new[] { "Check that the definition is not left out of compilation by #if or configuration differences.", "确认该定义没有因 #if 或配置差异而未被编译。", "#if나 구성 차이로 그 정의가 컴파일되지 않는 것은 아닌지 확인합니다.", "Compruebe que la definición no queda fuera de la compilación por #if o diferencias de configuración.", "Verifique se a definição não fica fora da compilação por #if ou diferenças de configuração.", "Prüfen, ob die Definition durch #if oder Konfigurationsunterschiede nicht kompiliert wird.", "Vérifiez que la définition n'est pas exclue de la compilation par un #if ou une différence de configuration.", "Проверьте, не выпадает ли определение из компиляции из-за #if или различий конфигураций." },
            ["宣言と定義の引数の型・const・名前空間が、1 つでも違うと別の関数になります。見比べます。"] = new[] { "If even one of the parameter types, const or namespace differs between declaration and definition, it is a different function. Compare them.", "声明与定义的参数类型、const、命名空间只要有一处不同，就是不同的函数。请对照。", "선언과 정의의 인수 타입·const·네임스페이스가 하나라도 다르면 다른 함수가 됩니다. 비교합니다.", "Si difiere en algo el tipo de los parámetros, const o el namespace entre declaración y definición, es otra función. Compárelas.", "Se o tipo dos parâmetros, const ou namespace diferir em algo entre declaração e definição, é outra função. Compare-as.", "Unterscheiden sich Parametertypen, const oder Namespace zwischen Deklaration und Definition auch nur einmal, ist es eine andere Funktion. Vergleichen.", "Si un seul type de paramètre, const ou namespace diffère entre déclaration et définition, c'est une autre fonction. Comparez-les.", "Если хоть что-то из типов параметров, const или namespace различается у объявления и определения, это другая функция. Сравните." },
            ["dllimport で参照している関数の実体が見つかりません{0}"] = new[] { "Definition of a function referenced via dllimport not found{0}", "找不到通过 dllimport 引用的函数的实体{0}", "dllimport로 참조하는 함수의 실체를 찾을 수 없습니다{0}", "No se encuentra la definición de una función referenciada con dllimport{0}", "Definição de função referenciada via dllimport não encontrada{0}", "Definition einer per dllimport referenzierten Funktion nicht gefunden{0}", "Définition d'une fonction référencée via dllimport introuvable{0}", "Не найдено определение функции, используемой через dllimport{0}" },
            ["シンボル名の頭の __imp_ は、ヘッダーが __declspec(dllimport) で宣言している印です。DLL が提供する関数を使うには、その DLL と一緒に作られる import library (.lib) を、リンクする必要があります。"] = new[] { "The __imp_ at the start of the symbol name means the header declares it with __declspec(dllimport). To use functions provided by a DLL, you must link the import library (.lib) built with that DLL.", "符号名开头的 __imp_ 表示头文件用 __declspec(dllimport) 声明。要使用 DLL 提供的函数，必须链接与该 DLL 一起生成的 import library（.lib）。", "심볼 이름 앞의 __imp_는 헤더가 __declspec(dllimport)로 선언했다는 표시입니다. DLL이 제공하는 함수를 쓰려면 그 DLL과 함께 만들어지는 import library(.lib)를 링크해야 합니다.", "El __imp_ al inicio del nombre del símbolo indica que el encabezado lo declara con __declspec(dllimport). Para usar funciones de una DLL hay que enlazar la import library (.lib) que se crea con esa DLL.", "O __imp_ no início do nome do símbolo indica que o cabeçalho o declara com __declspec(dllimport). Para usar funções de uma DLL, é preciso vincular a import library (.lib) criada com essa DLL.", "Das __imp_ am Anfang des Symbolnamens zeigt, dass der Header mit __declspec(dllimport) deklariert. Um Funktionen einer DLL zu nutzen, muss die mit ihr erzeugte Importbibliothek (.lib) gelinkt werden.", "Le __imp_ en tête du nom de symbole indique que l'en-tête le déclare avec __declspec(dllimport). Pour utiliser les fonctions d'une DLL, il faut lier l'import library (.lib) produite avec cette DLL.", "Префикс __imp_ в имени символа означает, что заголовок объявляет его с __declspec(dllimport). Чтобы использовать функции DLL, нужно скомпоновать import library (.lib), создаваемую вместе с этой DLL." },
            ["同じ名前空間のシンボルが並んでいる場合は、1 つの .lib が丸ごと足りない可能性が高いです。"] = new[] { "If symbols from the same namespace are listed together, a whole .lib is most likely missing.", "如果同一命名空间的符号排在一起，很可能是整个 .lib 都缺少了。", "같은 네임스페이스의 심볼이 나란히 있으면 .lib 하나가 통째로 빠졌을 가능성이 높습니다.", "Si aparecen juntos símbolos del mismo namespace, lo más probable es que falte un .lib entero.", "Se aparecem juntos símbolos do mesmo namespace, é bem provável que falte um .lib inteiro.", "Stehen Symbole desselben Namespace beieinander, fehlt sehr wahrscheinlich eine ganze .lib.", "Si des symboles du même namespace se suivent, il manque très probablement un .lib entier.", "Если подряд идут символы одного пространства имён, скорее всего, не хватает целого .lib." },
            ["提供元の DLL プロジェクトをビルドして、.lib ができているか確かめます。"] = new[] { "Build the providing DLL project and check that the .lib is produced.", "生成提供方的 DLL 项目，确认 .lib 已生成。", "제공 측 DLL 프로젝트를 빌드해서 .lib가 만들어졌는지 확인합니다.", "Compile el proyecto DLL proveedor y compruebe que se genera el .lib.", "Compile o projeto de DLL fornecedor e verifique se o .lib é gerado.", "Das bereitstellende DLL-Projekt erstellen und prüfen, ob die .lib entsteht.", "Générez le projet DLL fournisseur et vérifiez que le .lib est produit.", "Соберите проект DLL-поставщика и проверьте, что .lib создаётся." },
            ["その .lib を、リンカー > 入力 > 追加の依存ファイル に追加します (同じソリューションなら、参照の追加が早い)。"] = new[] { "Add that .lib to Linker > Input > Additional Dependencies (in the same solution, adding a reference is faster).", "将那个 .lib 添加到“链接器 > 输入 > 附加依赖项”（同一解决方案中，添加引用更快）。", "그 .lib를 링커 > 입력 > 추가 종속성에 추가합니다(같은 솔루션이면 참조 추가가 빠름).", "Añada ese .lib a Vinculador > Entrada > Dependencias adicionales (en la misma solución, agregar una referencia es más rápido).", "Adicione esse .lib em Vinculador > Entrada > Dependências adicionais (na mesma solução, adicionar referência é mais rápido).", "Diese .lib zu Linker > Eingabe > Zusätzliche Abhängigkeiten hinzufügen (in derselben Projektmappe ist ein Verweis schneller).", "Ajoutez ce .lib à Éditeur de liens > Entrée > Dépendances supplémentaires (dans la même solution, une référence est plus rapide).", "Добавьте этот .lib в «Компоновщик > Ввод > Дополнительные зависимости» (в том же решении быстрее добавить ссылку)." },
            ["静的ライブラリとして使うつもりなら、API マクロ (EXPORT / IMPORT) が dllimport にならないようにします。"] = new[] { "If you mean to use it as a static library, make sure the API macro (EXPORT / IMPORT) does not become dllimport.", "如果打算作为静态库使用，请让 API 宏（EXPORT / IMPORT）不变成 dllimport。", "정적 라이브러리로 쓸 생각이라면 API 매크로(EXPORT / IMPORT)가 dllimport가 되지 않게 합니다.", "Si quiere usarla como biblioteca estática, evite que la macro de API (EXPORT / IMPORT) se convierta en dllimport.", "Se quer usá-la como biblioteca estática, evite que a macro de API (EXPORT / IMPORT) vire dllimport.", "Soll sie als statische Bibliothek dienen, darf das API-Makro (EXPORT / IMPORT) nicht zu dllimport werden.", "Pour l'utiliser en bibliothèque statique, faites en sorte que la macro d'API (EXPORT / IMPORT) ne devienne pas dllimport.", "Если нужна статическая библиотека, сделайте так, чтобы макрос API (EXPORT / IMPORT) не становился dllimport." },
            ["テンプレートのインスタンスが見つかりません"] = new[] { "Template instance not found", "找不到模板的实例", "템플릿 인스턴스를 찾을 수 없습니다", "No se encuentra la instancia de la plantilla", "Instância do template não encontrada", "Template-Instanz nicht gefunden", "Instance du template introuvable", "Не найден экземпляр шаблона" },
            ["テンプレートの定義を .cpp に書くと、使う側の翻訳単位ではインスタンス化できず、リンクで未解決になります。"] = new[] { "If a template's definition is in a .cpp, the using translation unit cannot instantiate it, and it stays unresolved at link time.", "如果把模板的定义写在 .cpp 中，使用方的翻译单元无法实例化，链接时会无法解析。", "템플릿 정의를 .cpp에 쓰면 사용하는 쪽 번역 단위에서는 인스턴스화할 수 없어 링크 때 미해결이 됩니다.", "Si la definición de una plantilla está en un .cpp, la unidad de traducción que la usa no puede instanciarla y queda sin resolver al enlazar.", "Se a definição de um template fica num .cpp, a unidade de tradução que o usa não consegue instanciá-lo e ele fica não resolvido no link.", "Steht die Template-Definition in einer .cpp, kann die nutzende Übersetzungseinheit sie nicht instanziieren, und beim Linken bleibt sie unaufgelöst.", "Si la définition d'un template est dans un .cpp, l'unité de traduction qui l'utilise ne peut pas l'instancier et il reste non résolu à la liaison.", "Если определение шаблона в .cpp, использующая единица трансляции не может его инстанцировать, и при компоновке символ не разрешается." },
            ["テンプレートの定義を、ヘッダーに移します。"] = new[] { "Move the template's definition into the header.", "把模板的定义移到头文件中。", "템플릿 정의를 헤더로 옮깁니다.", "Mueva la definición de la plantilla al encabezado.", "Mova a definição do template para o cabeçalho.", "Die Template-Definition in den Header verschieben.", "Déplacez la définition du template dans l'en-tête.", "Перенесите определение шаблона в заголовок." },
            ["または、定義のある .cpp の末尾で、明示的にインスタンス化します (例: template void f<int>(int);)。"] = new[] { "Or explicitly instantiate it at the end of the .cpp that has the definition (e.g. template void f<int>(int);).", "或者在有定义的 .cpp 末尾显式实例化（例：template void f<int>(int);）。", "또는 정의가 있는 .cpp 끝에서 명시적으로 인스턴스화합니다(예: template void f<int>(int);).", "O instánciela explícitamente al final del .cpp con la definición (p. ej. template void f<int>(int);).", "Ou instancie explicitamente no fim do .cpp com a definição (ex.: template void f<int>(int);).", "Oder am Ende der .cpp mit der Definition explizit instanziieren (z. B. template void f<int>(int);).", "Ou instanciez-le explicitement à la fin du .cpp contenant la définition (ex. template void f<int>(int);).", "Или явно инстанцируйте в конце .cpp с определением (например, template void f<int>(int);)." },
            ["{0} のメンバー関数の定義が見つかりません"] = new[] { "Definition of a member function of {0} not found", "找不到 {0} 的成员函数的定义", "{0}의 멤버 함수 정의를 찾을 수 없습니다", "No se encuentra la definición de una función miembro de {0}", "Definição de função membro de {0} não encontrada", "Definition einer Memberfunktion von {0} nicht gefunden", "Définition d'une fonction membre de {0} introuvable", "Не найдено определение функции-члена {0}" },
            ["宣言はあるのに、定義がありません。または、宣言と定義が少しずれて、別の関数になっています。"] = new[] { "There is a declaration but no definition. Or the declaration and definition differ slightly and became different functions.", "有声明却没有定义。或者声明与定义稍有偏差，成了不同的函数。", "선언은 있는데 정의가 없습니다. 또는 선언과 정의가 조금 어긋나 다른 함수가 되었습니다.", "Hay declaración pero no definición. O la declaración y la definición difieren un poco y son funciones distintas.", "Há declaração, mas não definição. Ou declaração e definição diferem um pouco e viraram funções diferentes.", "Es gibt eine Deklaration, aber keine Definition. Oder Deklaration und Definition weichen leicht ab und sind verschiedene Funktionen.", "Il y a une déclaration mais pas de définition. Ou déclaration et définition diffèrent légèrement et sont devenues deux fonctions.", "Объявление есть, а определения нет. Или объявление и определение слегка расходятся и стали разными функциями." },
            ["該当の関数の定義 ({0}::関数名) を、.cpp に書いたか確かめます。"] = new[] { "Check that you wrote the definition of the function ({0}::FunctionName) in a .cpp.", "确认在 .cpp 中写了该函数的定义（{0}::函数名）。", "해당 함수의 정의({0}::함수명)를 .cpp에 썼는지 확인합니다.", "Compruebe que escribió la definición de la función ({0}::NombreFunción) en un .cpp.", "Verifique se escreveu a definição da função ({0}::NomeDaFunção) num .cpp.", "Prüfen, ob die Definition der Funktion ({0}::Funktionsname) in einer .cpp steht.", "Vérifiez que vous avez écrit la définition de la fonction ({0}::NomFonction) dans un .cpp.", "Проверьте, что определение функции ({0}::ИмяФункции) написано в .cpp." },
            ["宣言と定義の引数の型・const・参照・名前空間が、そろっているか確かめます。"] = new[] { "Check that parameter types, const, references and namespaces match between declaration and definition.", "确认声明与定义的参数类型、const、引用、命名空间一致。", "선언과 정의의 인수 타입·const·참조·네임스페이스가 맞는지 확인합니다.", "Compruebe que tipos de parámetros, const, referencias y namespaces coinciden entre declaración y definición.", "Verifique se tipos de parâmetros, const, referências e namespaces batem entre declaração e definição.", "Prüfen, ob Parametertypen, const, Referenzen und Namespaces in Deklaration und Definition übereinstimmen.", "Vérifiez que types de paramètres, const, références et namespaces concordent entre déclaration et définition.", "Проверьте совпадение типов параметров, const, ссылок и пространств имён в объявлении и определении." },
            ["その .cpp が、プロジェクトに入っているか確かめます。"] = new[] { "Check that the .cpp is in the project.", "确认那个 .cpp 在项目中。", "그 .cpp가 프로젝트에 들어 있는지 확인합니다.", "Compruebe que el .cpp está en el proyecto.", "Verifique se o .cpp está no projeto.", "Prüfen, ob die .cpp im Projekt ist.", "Vérifiez que le .cpp est dans le projet.", "Проверьте, что .cpp входит в проект." },
            ["呼ぶつもりのない関数なら、宣言を消します。"] = new[] { "If you do not mean to call the function, delete the declaration.", "如果不打算调用该函数，就删除声明。", "호출할 생각이 없는 함수라면 선언을 지웁니다.", "Si no piensa llamar a la función, borre la declaración.", "Se não pretende chamar a função, apague a declaração.", "Soll die Funktion nicht aufgerufen werden, die Deklaration löschen.", "Si vous ne comptez pas appeler la fonction, supprimez la déclaration.", "Если функцию вызывать не нужно, удалите объявление." },
            ["関数の定義が見つかりません{0}"] = new[] { "Function definition not found{0}", "找不到函数的定义{0}", "함수 정의를 찾을 수 없습니다{0}", "No se encuentra la definición de la función{0}", "Definição da função não encontrada{0}", "Funktionsdefinition nicht gefunden{0}", "Définition de fonction introuvable{0}", "Не найдено определение функции{0}" },
            ["宣言はあるのに、定義がリンクされていません。"] = new[] { "There is a declaration, but the definition is not linked.", "有声明，但定义没有被链接。", "선언은 있는데 정의가 링크되지 않았습니다.", "Hay declaración, pero la definición no se enlaza.", "Há declaração, mas a definição não é vinculada.", "Es gibt eine Deklaration, aber die Definition wird nicht gelinkt.", "Il y a une déclaration, mais la définition n'est pas liée.", "Объявление есть, но определение не скомпоновано." },
            ["装飾のない C の名前です。extern \"C\" の宣言と定義の、両方がそろっているか確かめます。"] = new[] { "An undecorated C name. Check that both the extern \"C\" declaration and definition are in place.", "这是没有修饰的 C 名称。确认 extern \"C\" 的声明和定义两者都齐全。", "장식이 없는 C 이름입니다. extern \"C\" 선언과 정의가 둘 다 갖춰져 있는지 확인합니다.", "Es un nombre de C sin decorar. Compruebe que la declaración y la definición extern \"C\" están ambas.", "É um nome C sem decoração. Verifique se declaração e definição extern \"C\" estão ambas presentes.", "Ein undekorierter C-Name. Prüfen, ob extern \"C\"-Deklaration und -Definition beide vorhanden sind.", "Nom C non décoré. Vérifiez que la déclaration et la définition extern \"C\" sont toutes deux présentes.", "Недекорированное имя C. Проверьте, что есть и объявление, и определение с extern \"C\"." },
            ["関数の定義を書いたか、その .cpp / .lib がプロジェクトに入っているか確かめます。"] = new[] { "Check that you wrote the function's definition and that its .cpp / .lib is in the project.", "确认写了函数定义，并且那个 .cpp / .lib 在项目中。", "함수 정의를 썼는지, 그 .cpp / .lib가 프로젝트에 들어 있는지 확인합니다.", "Compruebe que escribió la definición y que su .cpp / .lib está en el proyecto.", "Verifique se escreveu a definição e se o .cpp / .lib está no projeto.", "Prüfen, ob die Funktionsdefinition existiert und die .cpp / .lib im Projekt ist.", "Vérifiez que la définition existe et que son .cpp / .lib est dans le projet.", "Проверьте, что определение написано и его .cpp / .lib входит в проект." },
            ["宣言と定義の引数の型・const・名前空間が、そろっているか確かめます。"] = new[] { "Check that parameter types, const and namespaces match between declaration and definition.", "确认声明与定义的参数类型、const、命名空间一致。", "선언과 정의의 인수 타입·const·네임스페이스가 맞는지 확인합니다.", "Compruebe que tipos de parámetros, const y namespaces coinciden entre declaración y definición.", "Verifique se tipos de parâmetros, const e namespaces batem entre declaração e definição.", "Prüfen, ob Parametertypen, const und Namespaces in Deklaration und Definition übereinstimmen.", "Vérifiez que types de paramètres, const et namespaces concordent entre déclaration et définition.", "Проверьте совпадение типов параметров, const и пространств имён в объявлении и определении." },
            ["C++ の関数を C のコードから呼ぶ (またはその逆) なら、extern \"C\" の有無をそろえます。"] = new[] { "If a C++ function is called from C code (or the reverse), make extern \"C\" consistent.", "如果从 C 代码调用 C++ 函数（或反过来），请统一是否使用 extern \"C\"。", "C++ 함수를 C 코드에서 부르면(또는 그 반대) extern \"C\" 유무를 맞춥니다.", "Si llama a una función C++ desde código C (o al revés), unifique el uso de extern \"C\".", "Se chama uma função C++ a partir de código C (ou o contrário), unifique o uso de extern \"C\".", "Wird eine C++-Funktion aus C-Code aufgerufen (oder umgekehrt), extern \"C\" einheitlich setzen.", "Si une fonction C++ est appelée depuis du C (ou l'inverse), harmonisez la présence de extern \"C\".", "Если функцию C++ вызывают из C (или наоборот), согласуйте наличие extern \"C\"." },
            ["名前が宣言されていません"] = new[] { "Name not declared", "名称未声明", "이름이 선언되지 않았습니다", "Nombre no declarado", "Nome não declarado", "Name nicht deklariert", "Nom non déclaré", "Имя не объявлено" },
            ["綴り、宣言の場所(スコープ)、#include の不足、名前空間(std:: など)を確かめます。"] = new[] { "Check the spelling, where it is declared (scope), missing #include, and namespace (std:: etc.).", "检查拼写、声明位置（作用域）、#include 是否缺少、命名空间（std:: 等）。", "철자, 선언 위치(스코프), #include 누락, 네임스페이스(std:: 등)를 확인합니다.", "Revise la ortografía, dónde se declara (ámbito), #include que falten y namespace (std::, etc.).", "Verifique a grafia, onde é declarado (escopo), #include faltando e namespace (std:: etc.).", "Schreibweise, Deklarationsort (Gültigkeitsbereich), fehlendes #include und Namespace (std:: usw.) prüfen.", "Vérifiez l'orthographe, l'endroit de la déclaration (portée), un #include manquant et le namespace (std::, etc.).", "Проверьте написание, место объявления (область видимости), недостающий #include и пространство имён (std:: и т. п.)." },
            ["その名前の関数が見つかりません"] = new[] { "No function with that name found", "找不到该名称的函数", "그 이름의 함수를 찾을 수 없습니다", "No se encuentra una función con ese nombre", "Nenhuma função com esse nome encontrada", "Keine Funktion mit diesem Namen gefunden", "Aucune fonction de ce nom trouvée", "Функция с таким именем не найдена" },
            ["#include の不足と、名前空間(std:: など)、宣言より前で使っていないかを確かめます。"] = new[] { "Check for a missing #include, the namespace (std:: etc.), and whether it is used before its declaration.", "检查是否缺少 #include、命名空间（std:: 等），以及是否在声明之前使用。", "#include 누락과 네임스페이스(std:: 등), 선언보다 앞에서 쓰고 있지 않은지 확인합니다.", "Revise si falta un #include, el namespace (std::, etc.) y si se usa antes de declararse.", "Verifique #include faltando, o namespace (std:: etc.) e se é usado antes da declaração.", "Fehlendes #include, Namespace (std:: usw.) und Verwendung vor der Deklaration prüfen.", "Vérifiez un #include manquant, le namespace (std::, etc.) et une utilisation avant la déclaration.", "Проверьте недостающий #include, пространство имён (std:: и т. п.) и не используется ли имя до объявления." },
            ["そのメンバーがありません"] = new[] { "No such member", "没有该成员", "그 멤버가 없습니다", "No existe ese miembro", "Esse membro não existe", "Kein solcher Member", "Ce membre n'existe pas", "Такого члена нет" },
            ["メンバー名の綴りと、そのクラスの宣言、#include を確かめます。std:: のものは、対応するヘッダーが要ります。"] = new[] { "Check the member name's spelling, the class declaration and #include. std:: names need the matching header.", "检查成员名的拼写、该类的声明和 #include。std:: 的成员需要相应的头文件。", "멤버 이름의 철자와 그 클래스의 선언, #include를 확인합니다. std::의 것은 해당 헤더가 필요합니다.", "Revise la ortografía del miembro, la declaración de la clase y el #include. Lo de std:: necesita su encabezado.", "Verifique a grafia do membro, a declaração da classe e o #include. O que é de std:: precisa do cabeçalho correspondente.", "Schreibweise des Members, Klassendeklaration und #include prüfen. std::-Namen brauchen den passenden Header.", "Vérifiez l'orthographe du membre, la déclaration de la classe et l'#include. Les noms std:: exigent l'en-tête correspondant.", "Проверьте написание члена, объявление класса и #include. Для имён std:: нужен соответствующий заголовок." },
            ["識別子が不正"] = new[] { "Invalid identifier", "标识符无效", "식별자가 잘못되었습니다", "Identificador no válido", "Identificador inválido", "Ungültiger Bezeichner", "Identificateur non valide", "Недопустимый идентификатор" },
            ["型名の綴りと、その型の #include を確かめます。循環 include のときもこのエラーが出ます。"] = new[] { "Check the type name's spelling and that type's #include. Circular includes also cause this error.", "检查类型名的拼写和该类型的 #include。循环 include 时也会出现此错误。", "타입 이름의 철자와 그 타입의 #include를 확인합니다. 순환 include일 때도 이 오류가 나옵니다.", "Revise la ortografía del tipo y su #include. Los include circulares también causan este error.", "Verifique a grafia do tipo e seu #include. Include circular também causa este erro.", "Schreibweise des Typnamens und dessen #include prüfen. Auch zirkuläre Includes verursachen diesen Fehler.", "Vérifiez l'orthographe du type et son #include. Les include circulaires provoquent aussi cette erreur.", "Проверьте написание типа и его #include. Циклические include тоже дают эту ошибку." },
            ["未定義の型を使っている"] = new[] { "Using an undefined type", "使用了未定义的类型", "정의되지 않은 타입을 쓰고 있습니다", "Se usa un tipo no definido", "Usando um tipo não definido", "Undefinierter Typ wird verwendet", "Utilisation d'un type non défini", "Используется неопределённый тип" },
            ["前方宣言だけで、定義(#include)がありません。メンバーを使う側のファイルで、定義のあるヘッダーを include します。"] = new[] { "There is only a forward declaration, no definition (#include). In the file that uses the members, include the header with the definition.", "只有前向声明，没有定义（#include）。在使用成员的文件中 include 有定义的头文件。", "전방 선언만 있고 정의(#include)가 없습니다. 멤버를 쓰는 파일에서 정의가 있는 헤더를 include합니다.", "Solo hay una declaración adelantada, sin definición (#include). En el archivo que usa los miembros, incluya el encabezado con la definición.", "Só há declaração antecipada, sem definição (#include). No arquivo que usa os membros, inclua o cabeçalho com a definição.", "Nur eine Vorwärtsdeklaration, keine Definition (#include). In der Datei, die Member nutzt, den Header mit der Definition einbinden.", "Seulement une déclaration anticipée, pas de définition (#include). Dans le fichier qui utilise les membres, incluez l'en-tête avec la définition.", "Есть только предварительное объявление, нет определения (#include). В файле, где используются члены, подключите заголовок с определением." },
            ["未定義のクラスのオブジェクトは作れない"] = new[] { "Cannot create an object of an undefined class", "无法创建未定义类的对象", "정의되지 않은 클래스의 객체는 만들 수 없습니다", "No se puede crear un objeto de una clase no definida", "Não é possível criar objeto de uma classe não definida", "Objekt einer undefinierten Klasse nicht möglich", "Impossible de créer un objet d'une classe non définie", "Нельзя создать объект неопределённого класса" },
            ["前方宣言だけでは、値としては持てません。定義を include するか、ポインターにします。"] = new[] { "A forward declaration alone does not let you hold it by value. Include the definition or use a pointer.", "仅有前向声明，无法按值持有。请 include 定义，或改为指针。", "전방 선언만으로는 값으로 가질 수 없습니다. 정의를 include하거나 포인터로 합니다.", "Con solo una declaración adelantada no se puede tener por valor. Incluya la definición o use un puntero.", "Só com a declaração antecipada não dá para ter por valor. Inclua a definição ou use um ponteiro.", "Mit nur einer Vorwärtsdeklaration ist kein Halten als Wert möglich. Definition einbinden oder Zeiger nutzen.", "Une déclaration anticipée seule ne permet pas de le détenir par valeur. Incluez la définition ou utilisez un pointeur.", "С одним предварительным объявлением нельзя хранить по значению. Подключите определение или используйте указатель." },
            ["基底クラスが未定義"] = new[] { "Base class is undefined", "基类未定义", "기본 클래스가 정의되지 않았습니다", "Clase base no definida", "Classe base não definida", "Basisklasse nicht definiert", "Classe de base non définie", "Базовый класс не определён" },
            ["基底クラスのヘッダーを include します。循環 include も疑います。"] = new[] { "Include the base class's header. Also suspect a circular include.", "include 基类的头文件。也要怀疑循环 include。", "기본 클래스의 헤더를 include합니다. 순환 include도 의심합니다.", "Incluya el encabezado de la clase base. Sospeche también de include circulares.", "Inclua o cabeçalho da classe base. Desconfie também de include circular.", "Header der Basisklasse einbinden. Auch zirkuläre Includes verdächtigen.", "Incluez l'en-tête de la classe de base. Soupçonnez aussi un include circulaire.", "Подключите заголовок базового класса. Также проверьте циклические include." },
            ["同じ名前を別の型で再定義している"] = new[] { "Same name redefined with a different type", "同一名称以不同类型重定义", "같은 이름을 다른 타입으로 재정의하고 있습니다", "El mismo nombre se redefine con otro tipo", "O mesmo nome é redefinido com outro tipo", "Gleicher Name mit anderem Typ neu definiert", "Même nom redéfini avec un autre type", "То же имя переопределено с другим типом" },
            ["同じ名前の定義が 2 か所にあります。include ガード(#pragma once)と、名前の衝突を確かめます。"] = new[] { "The same name is defined in two places. Check include guards (#pragma once) and name clashes.", "同名的定义有两处。检查 include 防护（#pragma once）和名称冲突。", "같은 이름의 정의가 두 곳에 있습니다. include 가드(#pragma once)와 이름 충돌을 확인합니다.", "El mismo nombre se define en dos sitios. Revise las guardas de include (#pragma once) y los choques de nombres.", "O mesmo nome é definido em dois lugares. Verifique as guardas de include (#pragma once) e conflitos de nomes.", "Derselbe Name ist an zwei Stellen definiert. Include-Guards (#pragma once) und Namenskonflikte prüfen.", "Le même nom est défini à deux endroits. Vérifiez les gardes d'inclusion (#pragma once) et les conflits de noms.", "Одно имя определено в двух местах. Проверьте защиту от повторного включения (#pragma once) и конфликты имён." },
            ["型が二重に定義されている"] = new[] { "Type defined twice", "类型被重复定义", "타입이 중복 정의되어 있습니다", "Tipo definido dos veces", "Tipo definido duas vezes", "Typ doppelt definiert", "Type défini deux fois", "Тип определён дважды" },
            ["ヘッダーに #pragma once(または include ガード)がありません。"] = new[] { "The header has no #pragma once (or include guard).", "头文件中没有 #pragma once（或 include 防护）。", "헤더에 #pragma once(또는 include 가드)가 없습니다.", "El encabezado no tiene #pragma once (ni guarda de include).", "O cabeçalho não tem #pragma once (nem guarda de include).", "Dem Header fehlt #pragma once (oder ein Include-Guard).", "L'en-tête n'a pas de #pragma once (ni de garde d'inclusion).", "В заголовке нет #pragma once (или защиты от повторного включения)." },
            ["変数が二重に定義されている"] = new[] { "Variable defined twice", "变量被重复定义", "변수가 중복 정의되어 있습니다", "Variable definida dos veces", "Variável definida duas vezes", "Variable doppelt definiert", "Variable définie deux fois", "Переменная определена дважды" },
            ["同じ名前の変数を、同じスコープで 2 回宣言しています。"] = new[] { "A variable with the same name is declared twice in the same scope.", "在同一作用域中两次声明了同名变量。", "같은 이름의 변수를 같은 스코프에서 두 번 선언하고 있습니다.", "Se declara dos veces una variable con el mismo nombre en el mismo ámbito.", "Uma variável com o mesmo nome é declarada duas vezes no mesmo escopo.", "Eine Variable gleichen Namens wird im selben Bereich zweimal deklariert.", "Une variable du même nom est déclarée deux fois dans la même portée.", "Переменная с тем же именем объявлена дважды в одной области." },
            ["関数が二重に定義されている"] = new[] { "Function defined twice", "函数被重复定义", "함수가 중복 정의되어 있습니다", "Función definida dos veces", "Função definida duas vezes", "Funktion doppelt definiert", "Fonction définie deux fois", "Функция определена дважды" },
            ["同じ関数の本体を 2 回書いています。ヘッダーの include ガードも確かめます。"] = new[] { "The same function body is written twice. Also check the header's include guard.", "同一函数的本体写了两次。也检查头文件的 include 防护。", "같은 함수의 본문을 두 번 쓰고 있습니다. 헤더의 include 가드도 확인합니다.", "El cuerpo de la misma función se escribe dos veces. Revise también la guarda de include del encabezado.", "O corpo da mesma função foi escrito duas vezes. Verifique também a guarda de include do cabeçalho.", "Derselbe Funktionsrumpf steht zweimal da. Auch den Include-Guard des Headers prüfen.", "Le corps de la même fonction est écrit deux fois. Vérifiez aussi la garde d'inclusion de l'en-tête.", "Тело одной функции написано дважды. Проверьте и защиту заголовка от повторного включения." },
            ["テンプレート引数リストが必要"] = new[] { "Template argument list required", "需要模板参数列表", "템플릿 인수 목록이 필요합니다", "Se requiere lista de argumentos de plantilla", "Lista de argumentos de template necessária", "Template-Argumentliste erforderlich", "Liste d'arguments de template requise", "Требуется список аргументов шаблона" },
            ["クラス テンプレートは、<型> を付けて使います(C++17 では、コンストラクターから推論できる場合もあります)。"] = new[] { "Use a class template with <type> (in C++17 it can sometimes be deduced from the constructor).", "类模板要加上 <类型> 使用（C++17 中有时可以从构造函数推导）。", "클래스 템플릿은 <타입>을 붙여 씁니다(C++17에서는 생성자로부터 추론할 수 있는 경우도 있습니다).", "Use la plantilla de clase con <tipo> (en C++17 a veces se deduce del constructor).", "Use o template de classe com <tipo> (no C++17 às vezes é deduzido do construtor).", "Klassen-Templates mit <Typ> verwenden (in C++17 teils aus dem Konstruktor ableitbar).", "Utilisez le template de classe avec <type> (en C++17, il peut parfois être déduit du constructeur).", "Используйте шаблон класса с <тип> (в C++17 иногда выводится из конструктора)." },
            ["構文エラー"] = new[] { "Syntax error", "语法错误", "구문 오류", "Error de sintaxis", "Erro de sintaxe", "Syntaxfehler", "Erreur de syntaxe", "Синтаксическая ошибка" },
            ["多くは、エラーの行より前の行で、「;」「)」「}」が足りません。エラーの 1 つ前の文を見ます。"] = new[] { "Usually a \";\", \")\" or \"}\" is missing on a line before the error line. Look at the statement just before the error.", "多数情况下，是错误行之前的行缺少“;”“)”“}”。请看错误前的一个语句。", "대개 오류 줄보다 앞 줄에서 \";\" \")\" \"}\"가 부족합니다. 오류 바로 앞 문장을 봅니다.", "Casi siempre falta \";\", \")\" o \"}\" en una línea anterior a la del error. Mire la sentencia justo antes del error.", "Quase sempre falta \";\", \")\" ou \"}\" numa linha antes da do erro. Olhe a instrução logo antes do erro.", "Meist fehlt vor der Fehlerzeile ein \";\", \")\" oder \"}\". Die Anweisung direkt vor dem Fehler ansehen.", "Le plus souvent, il manque un « ; », « ) » ou « } » sur une ligne avant celle de l'erreur. Regardez l'instruction juste avant.", "Обычно в строке перед ошибкой не хватает «;», «)» или «}». Посмотрите на оператор прямо перед ошибкой." },
            ["構文エラー(識別子の手前に記号がない)"] = new[] { "Syntax error (missing symbol before identifier)", "语法错误（标识符前缺少符号）", "구문 오류(식별자 앞에 기호가 없음)", "Error de sintaxis (falta un símbolo antes del identificador)", "Erro de sintaxe (falta um símbolo antes do identificador)", "Syntaxfehler (Zeichen vor Bezeichner fehlt)", "Erreur de syntaxe (symbole manquant avant l'identificateur)", "Синтаксическая ошибка (нет символа перед идентификатором)" },
            ["直前の行の「;」の抜けか、型名が未宣言のことが多いです。"] = new[] { "Often a missing \";\" on the previous line, or an undeclared type name.", "多数是上一行漏了“;”，或类型名未声明。", "바로 앞 줄의 \";\" 누락이거나 타입 이름이 선언되지 않은 경우가 많습니다.", "Suele ser un \";\" que falta en la línea anterior o un nombre de tipo no declarado.", "Costuma ser um \";\" faltando na linha anterior ou um nome de tipo não declarado.", "Oft fehlt \";\" in der Zeile davor, oder ein Typname ist nicht deklariert.", "Souvent un « ; » manquant à la ligne précédente, ou un nom de type non déclaré.", "Чаще всего нет «;» в предыдущей строке или тип не объявлен." },
            ["示されたトークンの手前で文が崩れています。直前の行の閉じ忘れを疑います。"] = new[] { "The statement breaks just before the token shown. Suspect something left unclosed on the previous line.", "在所示记号之前语句就乱了。怀疑上一行有未闭合的地方。", "표시된 토큰 앞에서 문장이 무너져 있습니다. 바로 앞 줄에서 닫는 것을 잊었는지 의심합니다.", "La sentencia se rompe justo antes del token indicado. Sospeche algo sin cerrar en la línea anterior.", "A instrução quebra logo antes do token indicado. Desconfie de algo não fechado na linha anterior.", "Die Anweisung bricht direkt vor dem angezeigten Token ab. Etwas Ungeschlossenes in der Zeile davor vermuten.", "L'instruction se casse juste avant le jeton indiqué. Soupçonnez un élément non fermé à la ligne précédente.", "Оператор ломается прямо перед указанной лексемой. Подозревайте что-то незакрытое в предыдущей строке." },
            ["関数の本体の「{」がない"] = new[] { "Missing \"{\" for the function body", "缺少函数体的“{”", "함수 본문의 \"{\"가 없습니다", "Falta la \"{\" del cuerpo de la función", "Falta a \"{\" do corpo da função", "\"{\" des Funktionsrumpfs fehlt", "« { » du corps de la fonction manquante", "Нет «{» тела функции" },
            ["関数の定義の途中に、おかしな記述があります。引数リストの手前を確かめます。"] = new[] { "There is something odd in the middle of the function definition. Check just before the parameter list.", "函数定义中间有奇怪的写法。检查参数列表之前的部分。", "함수 정의 중간에 이상한 기술이 있습니다. 인수 목록 앞을 확인합니다.", "Hay algo extraño en medio de la definición de la función. Revise justo antes de la lista de parámetros.", "Há algo estranho no meio da definição da função. Verifique logo antes da lista de parâmetros.", "Mitten in der Funktionsdefinition steht etwas Seltsames. Direkt vor der Parameterliste prüfen.", "Il y a quelque chose d'anormal au milieu de la définition de la fonction. Vérifiez juste avant la liste des paramètres.", "В середине определения функции что-то не так. Проверьте место перед списком параметров." },
            ["予期しないファイル終端"] = new[] { "Unexpected end of file", "意外的文件结尾", "예기치 않은 파일 끝", "Fin de archivo inesperado", "Fim de arquivo inesperado", "Unerwartetes Dateiende", "Fin de fichier inattendue", "Неожиданный конец файла" },
            ["どこかの「{」や「/*」「#if」が閉じていません。"] = new[] { "A \"{\", \"/*\" or \"#if\" somewhere is not closed.", "某处的“{”或“/*”“#if”没有闭合。", "어딘가의 \"{\"나 \"/*\" \"#if\"가 닫히지 않았습니다.", "Algún \"{\", \"/*\" o \"#if\" no está cerrado.", "Algum \"{\", \"/*\" ou \"#if\" não está fechado.", "Irgendwo ist ein \"{\", \"/*\" oder \"#if\" nicht geschlossen.", "Un « { », « /* » ou « #if » n'est pas fermé quelque part.", "Где-то не закрыта «{», «/*» или «#if»." },
            ["対応する括弧がない"] = new[] { "No matching bracket", "没有对应的括号", "대응하는 괄호가 없습니다", "Falta el paréntesis correspondiente", "Falta o parêntese correspondente", "Keine passende Klammer", "Pas de parenthèse correspondante", "Нет парной скобки" },
            ["示された括弧に対応する閉じ括弧が見つかりません。"] = new[] { "No closing bracket matching the bracket shown was found.", "找不到与所示括号对应的闭括号。", "표시된 괄호에 대응하는 닫는 괄호를 찾을 수 없습니다.", "No se encuentra el cierre que corresponde al paréntesis indicado.", "Não foi encontrado o fechamento correspondente ao parêntese indicado.", "Zur angezeigten Klammer wurde keine schließende gefunden.", "Aucune parenthèse fermante correspondant à celle indiquée.", "Не найдена закрывающая скобка для указанной." },
            ["文字列定数が改行している"] = new[] { "String constant contains a newline", "字符串常量中换行了", "문자열 상수가 줄바꿈되어 있습니다", "La constante de cadena contiene un salto de línea", "A constante de string contém quebra de linha", "Zeichenfolgenkonstante enthält einen Zeilenumbruch", "La constante de chaîne contient un saut de ligne", "Строковая константа содержит перевод строки" },
            ["文字列の終わりの「\"」が抜けています。"] = new[] { "The closing \"\"\" of the string is missing.", "字符串结尾的“\"”漏掉了。", "문자열 끝의 \"\"\"가 빠져 있습니다.", "Falta la \"\"\" de cierre de la cadena.", "Falta a \"\"\" de fechamento da string.", "Das abschließende \"\"\" der Zeichenfolge fehlt.", "Le « \" » fermant de la chaîne manque.", "Нет закрывающей «\"» строки." },
            ["引数を変換できません"] = new[] { "Cannot convert argument", "无法转换参数", "인수를 변환할 수 없습니다", "No se puede convertir el argumento", "Não é possível converter o argumento", "Argument kann nicht konvertiert werden", "Impossible de convertir l'argument", "Не удаётся преобразовать аргумент" },
            ["N 番目の引数の型が、関数の宣言と合っていません。const・参照・ポインターの違いと、ほかの型への暗黙の変換がない点を見ます。"] = new[] { "The type of the Nth argument does not match the function declaration. Look at const / reference / pointer differences and the lack of an implicit conversion to the other type.", "第 N 个参数的类型与函数声明不符。注意 const、引用、指针的差异，以及没有到其他类型的隐式转换。", "N번째 인수의 타입이 함수 선언과 맞지 않습니다. const·참조·포인터의 차이와, 다른 타입으로의 암묵 변환이 없다는 점을 봅니다.", "El tipo del N-ésimo argumento no coincide con la declaración. Mire diferencias de const / referencia / puntero y la falta de conversión implícita al otro tipo.", "O tipo do N-ésimo argumento não bate com a declaração. Veja diferenças de const / referência / ponteiro e a falta de conversão implícita para o outro tipo.", "Der Typ des N-ten Arguments passt nicht zur Deklaration. Auf Unterschiede bei const / Referenz / Zeiger und fehlende implizite Konvertierung achten.", "Le type du N-ième argument ne correspond pas à la déclaration. Regardez les différences const / référence / pointeur et l'absence de conversion implicite.", "Тип N-го аргумента не совпадает с объявлением. Смотрите различия const / ссылка / указатель и отсутствие неявного преобразования." },
            ["どのオーバーロードにも合わない"] = new[] { "No overload matches", "没有匹配的重载", "어떤 오버로드에도 맞지 않습니다", "Ninguna sobrecarga coincide", "Nenhuma sobrecarga corresponde", "Keine Überladung passt", "Aucune surcharge ne correspond", "Ни одна перегрузка не подходит" },
            ["渡した引数の個数と型を、候補の宣言と見比べます。"] = new[] { "Compare the number and types of the arguments you passed with the candidate declarations.", "将传入参数的个数和类型与候选声明对照。", "넘긴 인수의 개수와 타입을 후보 선언과 비교합니다.", "Compare número y tipos de los argumentos pasados con las declaraciones candidatas.", "Compare número e tipos dos argumentos passados com as declarações candidatas.", "Anzahl und Typen der übergebenen Argumente mit den Kandidaten vergleichen.", "Comparez le nombre et les types des arguments passés avec les déclarations candidates.", "Сравните число и типы переданных аргументов с объявлениями-кандидатами." },
