            ["const のオブジェクトから非 const へは変換できません。"] = new[] { "A const object cannot be converted to non-const.", "不能从 const 对象转换为非 const。", "const 객체에서 비 const로는 변환할 수 없습니다.", "Un objeto const no se puede convertir a no const.", "Um objeto const não pode ser convertido para não const.", "Ein const-Objekt lässt sich nicht in nicht-const konvertieren.", "Un objet const ne peut pas être converti en non const.", "Объект const нельзя преобразовать в не-const." },
            ["既定コンストラクターがありません"] = new[] { "No default constructor", "没有默认构造函数", "기본 생성자가 없습니다", "No hay constructor predeterminado", "Não há construtor padrão", "Kein Standardkonstruktor", "Pas de constructeur par défaut", "Нет конструктора по умолчанию" },
            ["引数なしでは作れません。引数を渡すか、既定コンストラクターを足します。メンバーや基底クラスの初期化リストも確かめます。"] = new[] { "It cannot be created without arguments. Pass arguments or add a default constructor. Also check the initializer lists of members and base classes.", "不能无参创建。传入参数，或添加默认构造函数。也检查成员和基类的初始化列表。", "인수 없이는 만들 수 없습니다. 인수를 넘기거나 기본 생성자를 추가합니다. 멤버와 기본 클래스의 초기화 목록도 확인합니다.", "No se puede crear sin argumentos. Pase argumentos o añada un constructor predeterminado. Revise también las listas de inicialización de miembros y bases.", "Não pode ser criado sem argumentos. Passe argumentos ou adicione um construtor padrão. Verifique também as listas de inicialização de membros e bases.", "Ohne Argumente nicht erzeugbar. Argumente übergeben oder Standardkonstruktor hinzufügen. Auch Initialisierungslisten von Membern und Basisklassen prüfen.", "Impossible de le créer sans arguments. Passez des arguments ou ajoutez un constructeur par défaut. Vérifiez aussi les listes d'initialisation des membres et bases.", "Без аргументов создать нельзя. Передайте аргументы или добавьте конструктор по умолчанию. Проверьте и списки инициализации членов и базовых классов." },
            ["削除された関数を呼んでいます (コピーできない型のコピーなど)"] = new[] { "Calling a deleted function (e.g. copying a non-copyable type)", "调用了已删除的函数（如复制不可复制的类型）", "삭제된 함수를 호출하고 있습니다(복사할 수 없는 타입의 복사 등)", "Se llama a una función eliminada (p. ej. copiar un tipo no copiable)", "Chamando uma função excluída (ex.: copiar um tipo não copiável)", "Aufruf einer gelöschten Funktion (z. B. Kopie eines nicht kopierbaren Typs)", "Appel d'une fonction supprimée (ex. copie d'un type non copiable)", "Вызов удалённой функции (например, копирование некопируемого типа)" },
            ["コピーできない型(unique_ptr、mutex など)をコピーしています。std::move を使うか、参照で渡します。"] = new[] { "A non-copyable type (unique_ptr, mutex, etc.) is being copied. Use std::move or pass by reference.", "正在复制不可复制的类型（unique_ptr、mutex 等）。使用 std::move，或按引用传递。", "복사할 수 없는 타입(unique_ptr, mutex 등)을 복사하고 있습니다. std::move를 쓰거나 참조로 넘깁니다.", "Se copia un tipo no copiable (unique_ptr, mutex, etc.). Use std::move o pase por referencia.", "Um tipo não copiável (unique_ptr, mutex etc.) está sendo copiado. Use std::move ou passe por referência.", "Ein nicht kopierbarer Typ (unique_ptr, mutex usw.) wird kopiert. std::move nutzen oder per Referenz übergeben.", "Un type non copiable (unique_ptr, mutex, etc.) est copié. Utilisez std::move ou passez par référence.", "Копируется некопируемый тип (unique_ptr, mutex и т. п.). Используйте std::move или передавайте по ссылке." },
            ["const のオブジェクトから非 const の関数は呼べない"] = new[] { "Cannot call a non-const function on a const object", "不能从 const 对象调用非 const 函数", "const 객체에서 비 const 함수는 호출할 수 없습니다", "No se puede llamar a una función no const desde un objeto const", "Não é possível chamar função não const em objeto const", "Nicht-const-Funktion auf const-Objekt nicht aufrufbar", "Impossible d'appeler une fonction non const sur un objet const", "Нельзя вызвать не-const функцию у const-объекта" },
