            ["コンパイラが知らない属性を無視しました。綴りか、言語標準を確かめます。"] = new[] { "The compiler ignored an attribute it does not know. Check the spelling or the language standard.", "编译器忽略了它不认识的属性。检查拼写或语言标准。", "컴파일러가 모르는 특성을 무시했습니다. 철자나 언어 표준을 확인합니다.", "El compilador ignoró un atributo que no conoce. Revise la ortografía o el estándar.", "O compilador ignorou um atributo desconhecido. Verifique a grafia ou o padrão.", "Der Compiler hat ein unbekanntes Attribut ignoriert. Schreibweise oder Sprachstandard prüfen.", "Le compilateur a ignoré un attribut inconnu. Vérifiez l'orthographe ou la norme du langage.", "Компилятор проигнорировал незнакомый атрибут. Проверьте написание или стандарт языка." },
            ["HLSL: 構文エラー"] = new[] { "HLSL: Syntax error", "HLSL：语法错误", "HLSL: 구문 오류", "HLSL: error de sintaxis", "HLSL: erro de sintaxe", "HLSL: Syntaxfehler", "HLSL : erreur de syntaxe", "HLSL: синтаксическая ошибка" },
            ["直前の行の「;」「)」「}」の抜けが多いです。"] = new[] { "Often a \";\", \")\" or \"}\" is missing on the previous line.", "多为上一行缺少“;”“)”“}”。", "바로 앞 줄의 \";\" \")\" \"}\" 누락이 많습니다.", "Suele faltar \";\", \")\" o \"}\" en la línea anterior.", "Costuma faltar \";\", \")\" ou \"}\" na linha anterior.", "Oft fehlt \";\", \")\" oder \"}\" in der Zeile davor.", "Il manque souvent « ; », « ) » ou « } » à la ligne précédente.", "Часто в предыдущей строке нет «;», «)» или «}»." },
            ["HLSL: 宣言されていない識別子"] = new[] { "HLSL: Undeclared identifier", "HLSL：未声明的标识符", "HLSL: 선언되지 않은 식별자", "HLSL: identificador no declarado", "HLSL: identificador não declarado", "HLSL: Nicht deklarierter Bezeichner", "HLSL : identificateur non déclaré", "HLSL: необъявленный идентификатор" },
            ["綴りと、変数のスコープ、#include を確かめます。"] = new[] { "Check the spelling, the variable's scope and #include.", "检查拼写、变量的作用域和 #include。", "철자와 변수의 스코프, #include를 확인합니다.", "Revise la ortografía, el ámbito de la variable y el #include.", "Verifique a grafia, o escopo da variável e o #include.", "Schreibweise, Gültigkeitsbereich der Variable und #include prüfen.", "Vérifiez l'orthographe, la portée de la variable et l'#include.", "Проверьте написание, область видимости переменной и #include." },
            ["HLSL: 引数に合う関数がない"] = new[] { "HLSL: No function matches the arguments", "HLSL：没有与参数匹配的函数", "HLSL: 인수에 맞는 함수가 없습니다", "HLSL: ninguna función coincide con los argumentos", "HLSL: nenhuma função corresponde aos argumentos", "HLSL: Keine Funktion passt zu den Argumenten", "HLSL : aucune fonction ne correspond aux arguments", "HLSL: нет функции под эти аргументы" },
            ["渡した引数の型・個数を確かめます。候補は下に出ます。"] = new[] { "Check the types and number of arguments passed. Candidates are shown below.", "检查传入参数的类型和个数。候选显示在下方。", "넘긴 인수의 타입·개수를 확인합니다. 후보는 아래에 나옵니다.", "Revise tipos y número de argumentos. Las candidatas aparecen abajo.", "Verifique tipos e número de argumentos. Os candidatos aparecem abaixo.", "Typen und Anzahl der Argumente prüfen. Kandidaten stehen unten.", "Vérifiez les types et le nombre d'arguments. Les candidats sont affichés ci-dessous.", "Проверьте типы и число аргументов. Кандидаты показаны ниже." },
            ["HLSL: 引数の数が違う"] = new[] { "HLSL: Wrong number of arguments", "HLSL：参数个数不对", "HLSL: 인수 개수가 다릅니다", "HLSL: número de argumentos incorrecto", "HLSL: número de argumentos incorreto", "HLSL: Falsche Argumentanzahl", "HLSL : nombre d'arguments incorrect", "HLSL: неверное число аргументов" },
            ["関数の引数の個数を確かめます。"] = new[] { "Check the number of the function's arguments.", "检查函数参数的个数。", "함수 인수의 개수를 확인합니다.", "Revise el número de argumentos de la función.", "Verifique o número de argumentos da função.", "Anzahl der Funktionsargumente prüfen.", "Vérifiez le nombre d'arguments de la fonction.", "Проверьте число аргументов функции." },
            ["HLSL: 暗黙の型変換ができない"] = new[] { "HLSL: Implicit type conversion not possible", "HLSL：无法隐式类型转换", "HLSL: 암묵 타입 변환을 할 수 없습니다", "HLSL: no es posible la conversión implícita", "HLSL: conversão implícita impossível", "HLSL: Implizite Typkonvertierung nicht möglich", "HLSL : conversion implicite impossible", "HLSL: неявное преобразование невозможно" },
            ["float3 と float4 のような、次元の違いが多いです。.xyz などで切り出します。"] = new[] { "Often a dimension mismatch like float3 vs float4. Slice with .xyz etc.", "多为 float3 与 float4 这样的维数差异。用 .xyz 等截取。", "float3와 float4 같은 차원 차이가 많습니다. .xyz 등으로 잘라냅니다.", "Suele ser una diferencia de dimensión como float3 y float4. Recorte con .xyz, etc.", "Costuma ser diferença de dimensão como float3 e float4. Recorte com .xyz etc.", "Oft ein Dimensionsunterschied wie float3 und float4. Mit .xyz usw. herausschneiden.", "Souvent une différence de dimension comme float3 et float4. Extrayez avec .xyz, etc.", "Обычно разная размерность, как float3 и float4. Выделяйте через .xyz и т. п." },
