            ["HLSL: 型が合わない"] = new[] { "HLSL: Type mismatch", "HLSL：类型不符", "HLSL: 타입이 맞지 않습니다", "HLSL: los tipos no coinciden", "HLSL: tipos não coincidem", "HLSL: Typen passen nicht", "HLSL : types incompatibles", "HLSL: типы не совпадают" },
            ["比較や代入の左右の型をそろえます。"] = new[] { "Make the left and right types of the comparison or assignment match.", "让比较或赋值左右两边的类型一致。", "비교나 대입의 좌우 타입을 맞춥니다.", "Iguale los tipos a ambos lados de la comparación o asignación.", "Iguale os tipos dos dois lados da comparação ou atribuição.", "Typen links und rechts von Vergleich oder Zuweisung angleichen.", "Harmonisez les types de part et d'autre de la comparaison ou de l'affectation.", "Выровняйте типы слева и справа в сравнении или присваивании." },
            ["HLSL: グローバル変数は暗黙の const"] = new[] { "HLSL: Global variables are implicitly const", "HLSL：全局变量隐式为 const", "HLSL: 전역 변수는 암묵적으로 const", "HLSL: las variables globales son const implícitamente", "HLSL: variáveis globais são implicitamente const", "HLSL: Globale Variablen sind implizit const", "HLSL : les variables globales sont implicitement const", "HLSL: глобальные переменные неявно const" },
            ["シェーダー内でグローバルを書き換えられません。static を付けるか、ローカルにします。"] = new[] { "Globals cannot be modified in a shader. Add static or make it local.", "着色器中不能修改全局变量。加上 static，或改为局部变量。", "셰이더 안에서 전역을 바꿀 수 없습니다. static을 붙이거나 지역으로 합니다.", "En un shader no se pueden modificar globales. Añada static o hágala local.", "Num shader não é possível alterar globais. Adicione static ou torne-a local.", "Globale können im Shader nicht geändert werden. static hinzufügen oder lokal machen.", "On ne peut pas modifier une globale dans un shader. Ajoutez static ou rendez-la locale.", "В шейдере глобальные менять нельзя. Добавьте static или сделайте переменную локальной." },
            ["HLSL: 出力の型が不正"] = new[] { "HLSL: Invalid output type", "HLSL：输出类型无效", "HLSL: 출력 타입이 잘못되었습니다", "HLSL: tipo de salida no válido", "HLSL: tipo de saída inválido", "HLSL: Ungültiger Ausgabetyp", "HLSL : type de sortie non valide", "HLSL: недопустимый тип вывода" },
