            ["HLSL: ループ変数が二重に宣言されている"] = new[] { "HLSL: Loop variable declared twice", "HLSL：循环变量被重复声明", "HLSL: 루프 변수가 중복 선언되어 있습니다", "HLSL: variable de bucle declarada dos veces", "HLSL: variável de laço declarada duas vezes", "HLSL: Schleifenvariable doppelt deklariert", "HLSL : variable de boucle déclarée deux fois", "HLSL: переменная цикла объявлена дважды" },
