            ["HLSL: 出力が初期化されていない"] = new[] { "HLSL: Output not initialized", "HLSL：输出未初始化", "HLSL: 출력이 초기화되지 않았습니다", "HLSL: salida no inicializada", "HLSL: saída não inicializada", "HLSL: Ausgabe nicht initialisiert", "HLSL : sortie non initialisée", "HLSL: выход не инициализирован" },
            ["戻り値の構造体のメンバーを、すべて初期化します。"] = new[] { "Initialize all members of the returned struct.", "初始化返回结构体的所有成员。", "반환하는 구조체의 멤버를 모두 초기화합니다.", "Inicialice todos los miembros de la estructura devuelta.", "Inicialize todos os membros da estrutura retornada.", "Alle Member der zurückgegebenen Struktur initialisieren.", "Initialisez tous les membres de la structure renvoyée.", "Инициализируйте все члены возвращаемой структуры." },
            ["戻り値のすべての成分を設定します。"] = new[] { "Set all components of the return value.", "设置返回值的所有分量。", "반환값의 모든 성분을 설정합니다.", "Asigne todos los componentes del valor devuelto.", "Defina todos os componentes do valor retornado.", "Alle Komponenten des Rückgabewerts setzen.", "Définissez toutes les composantes de la valeur de retour.", "Задайте все компоненты возвращаемого значения." },
            ["HLSL: サンプラー引数の使い方が不正"] = new[] { "HLSL: Invalid use of sampler argument", "HLSL：采样器参数的用法无效", "HLSL: 샘플러 인수 사용법이 잘못되었습니다", "HLSL: uso no válido del argumento sampler", "HLSL: uso inválido do argumento sampler", "HLSL: Ungültige Verwendung des Sampler-Arguments", "HLSL : utilisation non valide de l'argument échantillonneur", "HLSL: недопустимое использование аргумента-сэмплера" },
            ["SamplerState の使い方を確かめます。"] = new[] { "Check how SamplerState is used.", "检查 SamplerState 的用法。", "SamplerState 사용법을 확인합니다.", "Revise cómo se usa SamplerState.", "Verifique como SamplerState é usado.", "Verwendung von SamplerState prüfen.", "Vérifiez l'utilisation de SamplerState.", "Проверьте, как используется SamplerState." },
