            ["2 (反復子のデバッグあり。Debug)"] = new[] { "2 (iterator debugging on. Debug)", "2（有迭代器调试。Debug）", "2 (반복기 디버그 있음. Debug)", "2 (con depuración de iteradores. Debug)", "2 (com depuração de iteradores. Debug)", "2 (Iterator-Debugging an. Debug)", "2 (débogage d'itérateurs actif. Debug)", "2 (с отладкой итераторов. Debug)" },
            ["0 (ASan の注釈なし)"] = new[] { "0 (no ASan annotations)", "0（无 ASan 注释）", "0 (ASan 주석 없음)", "0 (sin anotaciones de ASan)", "0 (sem anotações do ASan)", "0 (keine ASan-Annotationen)", "0 (pas d'annotations ASan)", "0 (без аннотаций ASan)" },
            ["{0} (ASan の注釈あり)"] = new[] { "{0} (with ASan annotations)", "{0}（有 ASan 注释）", "{0} (ASan 주석 있음)", "{0} (con anotaciones de ASan)", "{0} (com anotações do ASan)", "{0} (mit ASan-Annotationen)", "{0} (avec annotations ASan)", "{0} (с аннотациями ASan)" },
            ["private / protected のメンバーは、ここから使えません"] = new[] { "A private / protected member cannot be used from here", "private / protected 的成员不能在这里使用", "private / protected 멤버는 여기서 쓸 수 없습니다", "Un miembro private / protected no se puede usar desde aquí", "Um membro private / protected não pode ser usado daqui", "private- / protected-Member ist hier nicht verwendbar", "Un membre private / protected n'est pas utilisable ici", "Член private / protected отсюда недоступен" },
            ["メンバーの公開範囲(public / protected / private)が、使う場所に合っていません。public にするか、公開用の関数(Getter など)を用意するか、friend にします。"] = new[] { "The member's access level (public / protected / private) does not fit where it is used. Make it public, provide a public function (a Getter, etc.), or use friend.", "成员的访问级别（public / protected / private）与使用位置不符。改为 public，或准备公开的函数（Getter 等），或设为 friend。", "멤버의 공개 범위(public / protected / private)가 쓰는 위치에 맞지 않습니다. public으로 하거나, 공개용 함수(Getter 등)를 준비하거나, friend로 합니다.", "El nivel de acceso del miembro (public / protected / private) no encaja donde se usa. Hágalo public, ofrezca una función pública (un Getter, etc.) o use friend.", "O nível de acesso do membro (public / protected / private) não combina com onde é usado. Torne-o public, ofereça uma função pública (um Getter etc.) ou use friend.", "Die Sichtbarkeit des Members (public / protected / private) passt nicht zur Verwendungsstelle. public machen, eine öffentliche Funktion (Getter usw.) anbieten oder friend nutzen.", "Le niveau d'accès du membre (public / protected / private) ne convient pas à l'endroit d'utilisation. Rendez-le public, fournissez une fonction publique (un Getter, etc.) ou utilisez friend.", "Уровень доступа члена (public / protected / private) не подходит к месту использования. Сделайте его public, добавьте открытую функцию (Getter и т. п.) или используйте friend." },
            ["class Foo { int x_; };        // 何も書かないクラスは private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // 直し方 1: public にする\nclass Foo { int x_; public: int GetX() const { return x_; } };   // 直し方 2: 関数を用意する"] = new[] { "class Foo { int x_; };        // a class with nothing written is private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Fix 1: make it public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Fix 2: provide a function", "class Foo { int x_; };        // 什么都不写的类是 private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // 修正 1：改为 public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // 修正 2：准备函数", "class Foo { int x_; };        // 아무것도 안 쓴 클래스는 private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // 고치는 법 1: public으로 한다\nclass Foo { int x_; public: int GetX() const { return x_; } };   // 고치는 법 2: 함수를 준비한다", "class Foo { int x_; };        // una clase sin nada escrito es private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Arreglo 1: hacerlo public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Arreglo 2: ofrecer una función", "class Foo { int x_; };        // uma classe sem nada escrito é private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Correção 1: torná-lo public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Correção 2: oferecer uma função", "class Foo { int x_; };        // eine Klasse ohne Angabe ist private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Lösung 1: public machen\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Lösung 2: Funktion anbieten", "class Foo { int x_; };        // une classe sans rien d'écrit est private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Correction 1 : le rendre public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Correction 2 : fournir une fonction", "class Foo { int x_; };        // в классе без указаний всё private\nfoo.x_ = 1;                   // C2248\n\nclass Foo { public: int x_; };   // Исправление 1: сделать public\nclass Foo { int x_; public: int GetX() const { return x_; } };   // Исправление 2: добавить функцию" },
            ["抽象クラスのオブジェクトは作れません"] = new[] { "Cannot create an object of an abstract class", "不能创建抽象类的对象", "추상 클래스의 객체는 만들 수 없습니다", "No se puede crear un objeto de una clase abstracta", "Não é possível criar objeto de classe abstrata", "Objekt einer abstrakten Klasse nicht möglich", "Impossible de créer un objet d'une classe abstraite", "Нельзя создать объект абстрактного класса" },
            ["実装されていない純粋仮想関数(= 0)が残っているクラスは、オブジェクトを作れません。派生クラスで、すべて override して実装し、派生クラスのオブジェクトを作ります。override したつもりで、const や引数の違いで別の関数になっていることもあります。"] = new[] { "A class with unimplemented pure virtual functions (= 0) cannot be instantiated. Override and implement them all in a derived class, and create an object of the derived class. Sometimes what you meant as an override is a different function because of const or parameter differences.", "留有未实现的纯虚函数（= 0）的类不能创建对象。在派生类中全部 override 并实现，然后创建派生类的对象。有时本以为 override 了，却因 const 或参数差异成了别的函数。", "구현되지 않은 순수 가상 함수(= 0)가 남은 클래스는 객체를 만들 수 없습니다. 파생 클래스에서 모두 override해 구현하고, 파생 클래스의 객체를 만듭니다. override한 줄 알았는데 const나 인수 차이로 다른 함수가 된 경우도 있습니다.", "Una clase con funciones virtuales puras (= 0) sin implementar no se puede instanciar. Sobrescríbalas e impleméntelas todas en una derivada y cree un objeto de la derivada. A veces lo que creía un override es otra función por const o por los parámetros.", "Uma classe com funções virtuais puras (= 0) não implementadas não pode ser instanciada. Sobrescreva e implemente todas numa derivada e crie um objeto da derivada. Às vezes o que parecia override é outra função por causa de const ou parâmetros.", "Eine Klasse mit nicht implementierten rein virtuellen Funktionen (= 0) ist nicht instanziierbar. In einer abgeleiteten Klasse alle per override implementieren und davon ein Objekt erzeugen. Manchmal ist das vermeintliche override wegen const oder Parametern eine andere Funktion.", "Une classe avec des fonctions virtuelles pures (= 0) non implémentées ne peut pas être instanciée. Redéfinissez-les toutes avec override dans une classe dérivée et créez un objet de celle-ci. Parfois, ce que vous pensiez redéfinir est une autre fonction à cause de const ou des paramètres.", "Класс с нереализованными чисто виртуальными функциями (= 0) нельзя инстанцировать. Переопределите и реализуйте их все в производном классе и создайте его объект. Бывает, что задуманный override из-за const или параметров оказался другой функцией." },
            ["struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // 直し方: 実装した派生クラスを作る"] = new[] { "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Fix: create the implemented derived class", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // 修正：创建已实现的派生类", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // 고치는 법: 구현한 파생 클래스를 만든다", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Arreglo: crear la clase derivada implementada", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Correção: criar a classe derivada implementada", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Lösung: die implementierte abgeleitete Klasse erzeugen", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Correction : créer la classe dérivée implémentée", "struct Shape { virtual void Draw() = 0; };\nShape s;                       // C2259\n\nstruct Circle : Shape { void Draw() override {} };\nCircle c;                      // Исправление: создать реализованный производный класс" },
            ["「::」の右が不正 (min / max マクロの衝突)"] = new[] { "Invalid right side of \"::\" (min / max macro clash)", "“::”的右边无效（min / max 宏冲突）", "\"::\"의 오른쪽이 잘못되었습니다(min / max 매크로 충돌)", "Lado derecho de \"::\" no válido (choque con las macros min / max)", "Lado direito de \"::\" inválido (conflito com macros min / max)", "Rechte Seite von \"::\" ungültig (Konflikt mit min-/max-Makro)", "Partie droite de « :: » non valide (conflit des macros min / max)", "Недопустимая правая часть «::» (конфликт с макросами min / max)" },
            ["windows.h が定義する min / max マクロと、std::numeric_limits<T>::max() や std::min の名前がぶつかっています。windows.h を include する前に NOMINMAX を定義するか、括弧で囲みます。"] = new[] { "The min / max macros defined by windows.h clash with names like std::numeric_limits<T>::max() or std::min. Define NOMINMAX before including windows.h, or wrap it in parentheses.", "windows.h 定义的 min / max 宏与 std::numeric_limits<T>::max() 或 std::min 的名称冲突。在 include windows.h 之前定义 NOMINMAX，或用括号括起来。", "windows.h가 정의하는 min / max 매크로와 std::numeric_limits<T>::max()나 std::min의 이름이 부딪힙니다. windows.h를 include하기 전에 NOMINMAX를 정의하거나 괄호로 감쌉니다.", "Las macros min / max de windows.h chocan con nombres como std::numeric_limits<T>::max() o std::min. Defina NOMINMAX antes de incluir windows.h o use paréntesis.", "As macros min / max do windows.h conflitam com nomes como std::numeric_limits<T>::max() ou std::min. Defina NOMINMAX antes de incluir o windows.h ou use parênteses.", "Die min-/max-Makros aus windows.h kollidieren mit Namen wie std::numeric_limits<T>::max() oder std::min. NOMINMAX vor windows.h definieren oder in Klammern setzen.", "Les macros min / max de windows.h entrent en conflit avec std::numeric_limits<T>::max() ou std::min. Définissez NOMINMAX avant d'inclure windows.h, ou mettez des parenthèses.", "Макросы min / max из windows.h конфликтуют с именами вроде std::numeric_limits<T>::max() или std::min. Определите NOMINMAX до подключения windows.h или возьмите в скобки." },
            ["#define NOMINMAX            // windows.h より前に書く\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // 括弧で囲む直し方"] = new[] { "#define NOMINMAX            // write before windows.h\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // fix by wrapping in parentheses", "#define NOMINMAX            // 写在 windows.h 之前\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // 用括号括起来的修正", "#define NOMINMAX            // windows.h보다 앞에 쓴다\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // 괄호로 감싸는 고치는 법", "#define NOMINMAX            // escribir antes de windows.h\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // arreglo con paréntesis", "#define NOMINMAX            // escrever antes do windows.h\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // correção com parênteses", "#define NOMINMAX            // vor windows.h schreiben\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // Lösung mit Klammern", "#define NOMINMAX            // à écrire avant windows.h\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // correction avec parenthèses", "#define NOMINMAX            // писать до windows.h\n#include <windows.h>\n\nauto v = (std::numeric_limits<int>::max)();   // исправление скобками" },
            ["その型はここに書けません (前のエラーの影響が多い)"] = new[] { "That type cannot be written here (often caused by a previous error)", "此处不能写该类型（多为前一个错误的影响）", "그 타입은 여기에 쓸 수 없습니다(앞 오류의 영향이 많음)", "Ese tipo no puede ir aquí (suele deberse a un error anterior)", "Esse tipo não pode ficar aqui (costuma ser efeito de um erro anterior)", "Dieser Typ ist hier nicht erlaubt (oft Folge eines vorigen Fehlers)", "Ce type ne peut pas être écrit ici (souvent dû à une erreur précédente)", "Этот тип здесь писать нельзя (часто следствие предыдущей ошибки)" },
            ["直前のエラー(C2589 や C2143 など)の影響で出ることが多いです。まず、上のエラーを直します。"] = new[] { "Often caused by the previous error (C2589, C2143, etc.). Fix the error above first.", "多为前一个错误（C2589 或 C2143 等）的影响。先修正上面的错误。", "직전 오류(C2589나 C2143 등)의 영향으로 나오는 경우가 많습니다. 먼저 위의 오류를 고칩니다.", "Suele deberse al error anterior (C2589, C2143, etc.). Corrija primero el de arriba.", "Costuma ser efeito do erro anterior (C2589, C2143 etc.). Corrija primeiro o de cima.", "Oft Folge des vorigen Fehlers (C2589, C2143 usw.). Zuerst den Fehler oben beheben.", "Souvent dû à l'erreur précédente (C2589, C2143, etc.). Corrigez d'abord celle du dessus.", "Чаще всего следствие предыдущей ошибки (C2589, C2143 и т. п.). Сначала исправьте ошибку выше." },
            ["警告がエラーとして扱われています (/WX)"] = new[] { "Warnings are treated as errors (/WX)", "警告被视为错误（/WX）", "경고가 오류로 취급되고 있습니다(/WX)", "Los avisos se tratan como errores (/WX)", "Avisos são tratados como erros (/WX)", "Warnungen werden als Fehler behandelt (/WX)", "Les avertissements sont traités comme des erreurs (/WX)", "Предупреждения считаются ошибками (/WX)" },
            ["下の警告が、エラー扱いになってビルドが止まっています。警告そのものを直すのが一番です。直せないときは、プロジェクトの「警告をエラーとして扱う」(C/C++ > 全般)を外します。"] = new[] { "The warnings below are treated as errors and stop the build. Fixing the warning itself is best. If you cannot, turn off the project's \"Treat Warnings As Errors\" (C/C++ > General).", "下面的警告被当作错误，生成停止了。最好是修正警告本身。无法修正时，关闭项目的“将警告视为错误”（C/C++ > 常规）。", "아래 경고가 오류로 취급되어 빌드가 멈췄습니다. 경고 자체를 고치는 것이 가장 좋습니다. 고칠 수 없을 때는 프로젝트의 \"경고를 오류로 처리\"(C/C++ > 일반)를 끕니다.", "Los avisos de abajo se tratan como errores y detienen la compilación. Lo mejor es corregir el aviso. Si no puede, desactive \"Tratar advertencias como errores\" (C/C++ > General).", "Os avisos abaixo são tratados como erros e param a compilação. O melhor é corrigir o aviso. Se não puder, desligue \"Tratar avisos como erros\" (C/C++ > Geral).", "Die Warnungen unten gelten als Fehler und stoppen den Build. Am besten die Warnung selbst beheben. Sonst \"Warnungen als Fehler behandeln\" (C/C++ > Allgemein) ausschalten.", "Les avertissements ci-dessous sont traités comme des erreurs et arrêtent la génération. Le mieux est de les corriger. Sinon, désactivez « Considérer les avertissements comme des erreurs » (C/C++ > Général).", "Предупреждения ниже считаются ошибками и останавливают сборку. Лучше исправить само предупреждение. Если нельзя, отключите «Обрабатывать предупреждения как ошибки» (C/C++ > Общие)." },
            ["override と書いたのに、基底クラスに同じ関数がありません (オーバーライドになっていません)"] = new[] { "override is written, but the base class has no such function (it is not an override)", "写了 override，但基类中没有相同的函数（没有构成重写）", "override라고 썼는데 기본 클래스에 같은 함수가 없습니다(오버라이드가 되지 않음)", "Se escribió override, pero la clase base no tiene esa función (no es un override)", "override foi escrito, mas a classe base não tem essa função (não é override)", "override angegeben, aber die Basisklasse hat diese Funktion nicht (kein Überschreiben)", "override est écrit, mais la classe de base n'a pas cette fonction (ce n'est pas une redéfinition)", "Написан override, но в базовом классе такой функции нет (это не переопределение)" },
            ["override を付けた関数は、基底クラスの仮想関数と、名前・引数の型・const・参照修飾までそろっていないと、オーバーライドになりません。どこかが 1 つ違うと、このエラーになります。基底クラスの宣言と見比べます。"] = new[] { "A function marked override only overrides if its name, parameter types, const and ref-qualifiers all match the base class's virtual function. If even one differs, you get this error. Compare with the base class declaration.", "加了 override 的函数，只有在名称、参数类型、const、引用限定都与基类的虚函数一致时才构成重写。只要有一处不同就会出现此错误。请与基类的声明对照。", "override를 붙인 함수는 기본 클래스의 가상 함수와 이름·인수 타입·const·참조 한정자까지 맞아야 오버라이드가 됩니다. 하나라도 다르면 이 오류가 됩니다. 기본 클래스의 선언과 비교합니다.", "Una función con override solo sobrescribe si nombre, tipos de parámetros, const y calificadores de referencia coinciden con la virtual de la base. Si algo difiere, sale este error. Compárela con la declaración de la base.", "Uma função com override só sobrescreve se nome, tipos de parâmetros, const e qualificadores de referência baterem com a virtual da base. Se algo diferir, surge este erro. Compare com a declaração da base.", "Eine Funktion mit override überschreibt nur, wenn Name, Parametertypen, const und Ref-Qualifizierer zur virtuellen Funktion der Basis passen. Weicht etwas ab, kommt dieser Fehler. Mit der Basisdeklaration vergleichen.", "Une fonction marquée override ne redéfinit que si nom, types de paramètres, const et qualificatifs de référence correspondent à la virtuelle de la base. Si un seul diffère, cette erreur apparaît. Comparez avec la déclaration de base.", "Функция с override переопределяет, только если имя, типы параметров, const и ссылочные квалификаторы совпадают с виртуальной функцией базы. Если хоть что-то отличается, будет эта ошибка. Сравните с объявлением в базовом классе." },
            ["struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const が違う\n\nstruct D : Base { void Run() const override; };   // 直し方: 基底クラスとそろえる"] = new[] { "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const differs\n\nstruct D : Base { void Run() const override; };   // Fix: match the base class", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const 不同\n\nstruct D : Base { void Run() const override; };   // 修正：与基类一致", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const가 다르다\n\nstruct D : Base { void Run() const override; };   // 고치는 법: 기본 클래스와 맞춘다", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const no coincide\n\nstruct D : Base { void Run() const override; };   // Arreglo: igualar con la base", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const difere\n\nstruct D : Base { void Run() const override; };   // Correção: igualar à base", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const weicht ab\n\nstruct D : Base { void Run() const override; };   // Lösung: an Basis angleichen", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: const diffère\n\nstruct D : Base { void Run() const override; };   // Correction : aligner sur la base", "struct Base { virtual void Run() const; };\nstruct D : Base { void Run() override; };       // C3668: отличается const\n\nstruct D : Base { void Run() const override; };   // Исправление: как в базовом классе" },
            ["final の関数を、派生クラスで上書きしようとしています"] = new[] { "Trying to override a final function in a derived class", "试图在派生类中重写 final 函数", "final 함수를 파생 클래스에서 덮어쓰려 하고 있습니다", "Se intenta sobrescribir una función final en una derivada", "Tentando sobrescrever uma função final numa derivada", "Eine final-Funktion soll in einer abgeleiteten Klasse überschrieben werden", "Tentative de redéfinir une fonction final dans une classe dérivée", "Попытка переопределить final-функцию в производном классе" },
            ["基底クラスの関数に final が付いているので、派生クラスでは上書きできません。上書きしたいなら、基底クラスの final を外します。上書きするつもりがないなら、派生クラスの関数を消すか、別の名前にします。"] = new[] { "The base class function is final, so it cannot be overridden in a derived class. To override it, remove final from the base class. If you did not mean to override, delete the derived function or rename it.", "基类的函数带有 final，所以派生类中不能重写。若要重写，就去掉基类的 final。若无意重写，就删除派生类的函数或改名。", "기본 클래스의 함수에 final이 붙어 있어 파생 클래스에서 덮어쓸 수 없습니다. 덮어쓰고 싶다면 기본 클래스의 final을 뗍니다. 덮어쓸 생각이 없다면 파생 클래스의 함수를 지우거나 다른 이름으로 합니다.", "La función de la base es final y no se puede sobrescribir. Para hacerlo, quite final en la base. Si no quería sobrescribir, borre la función derivada o renómbrela.", "A função da base é final e não pode ser sobrescrita. Para isso, remova final na base. Se não queria sobrescrever, apague a função derivada ou renomeie.", "Die Basisfunktion ist final und kann nicht überschrieben werden. Zum Überschreiben final in der Basis entfernen. Sonst die abgeleitete Funktion löschen oder umbenennen.", "La fonction de base est final et ne peut pas être redéfinie. Pour la redéfinir, retirez final dans la base. Sinon, supprimez ou renommez la fonction dérivée.", "Функция базы помечена final, её нельзя переопределить. Чтобы переопределить, уберите final в базе. Если не собирались — удалите функцию в производном классе или переименуйте." },
            ["const の関数の中で、メンバー変数を書き換えています"] = new[] { "Modifying a member variable inside a const function", "在 const 函数中修改了成员变量", "const 함수 안에서 멤버 변수를 바꾸고 있습니다", "Se modifica una variable miembro dentro de una función const", "Modificando uma variável membro dentro de função const", "Membervariable wird in einer const-Funktion geändert", "Modification d'une variable membre dans une fonction const", "Изменение переменной-члена в const-функции" },
            ["const を付けたメンバー関数の中では、メンバー変数は読むだけです。書き換えたいなら、関数の const を外します。キャッシュのような「見た目は変わらない」値だけなら、その変数を mutable にします。"] = new[] { "Inside a const member function, member variables are read-only. To modify them, remove const from the function. For values that do not change what is visible, like a cache, make that variable mutable.", "在加了 const 的成员函数中，成员变量只能读。要修改就去掉函数的 const。像缓存这种“外观不变”的值，可把该变量设为 mutable。", "const를 붙인 멤버 함수 안에서는 멤버 변수를 읽기만 합니다. 바꾸고 싶다면 함수의 const를 뗍니다. 캐시처럼 \"겉보기는 변하지 않는\" 값이라면 그 변수를 mutable로 합니다.", "En una función miembro const, las variables miembro son de solo lectura. Para modificarlas, quite const de la función. Para valores que no cambian lo visible, como una caché, haga la variable mutable.", "Numa função membro const, as variáveis membro são só leitura. Para modificá-las, remova const da função. Para valores que não alteram o visível, como um cache, torne a variável mutable.", "In einer const-Memberfunktion sind Membervariablen schreibgeschützt. Zum Ändern const an der Funktion entfernen. Für \"äußerlich unveränderte\" Werte wie einen Cache die Variable mutable machen.", "Dans une fonction membre const, les variables membres sont en lecture seule. Pour les modifier, retirez const. Pour une valeur qui ne change pas l'apparence, comme un cache, rendez la variable mutable.", "В const-функции-члене переменные-члены только читаются. Чтобы менять, уберите const у функции. Для значений, не меняющих видимое состояние (кэш), сделайте переменную mutable." },
            ["int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // 直し方 1: const を外す\nmutable int count_ = 0;                 // 直し方 2: mutable にする"] = new[] { "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Fix 1: remove const\nmutable int count_ = 0;                 // Fix 2: make it mutable", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // 修正 1：去掉 const\nmutable int count_ = 0;                 // 修正 2：设为 mutable", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // 고치는 법 1: const를 뗀다\nmutable int count_ = 0;                 // 고치는 법 2: mutable로 한다", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Arreglo 1: quitar const\nmutable int count_ = 0;                 // Arreglo 2: hacerlo mutable", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Correção 1: remover const\nmutable int count_ = 0;                 // Correção 2: torná-lo mutable", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Lösung 1: const entfernen\nmutable int count_ = 0;                 // Lösung 2: mutable machen", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Correction 1 : retirer const\nmutable int count_ = 0;                 // Correction 2 : le rendre mutable", "int count_ = 0;\nvoid Inc() const { ++count_; }          // C3490\n\nvoid Inc() { ++count_; }                // Исправление 1: убрать const\nmutable int count_ = 0;                 // Исправление 2: сделать mutable" },
            ["const の変数に、代入しています"] = new[] { "Assigning to a const variable", "给 const 变量赋值", "const 변수에 대입하고 있습니다", "Se asigna a una variable const", "Atribuindo a uma variável const", "Zuweisung an eine const-Variable", "Affectation à une variable const", "Присваивание const-переменной" },
            ["const(constexpr)の変数は、最初に決めた値から変えられません。値を変えたいなら、const を外します。変えるつもりがないなら、代入している行が間違っています。"] = new[] { "A const (constexpr) variable cannot change from its initial value. To change it, remove const. If you did not mean to change it, the assignment line is wrong.", "const（constexpr）变量不能从最初的值改变。要改值就去掉 const。若无意改变，就是赋值的那一行写错了。", "const(constexpr) 변수는 처음 정한 값에서 바꿀 수 없습니다. 값을 바꾸고 싶다면 const를 뗍니다. 바꿀 생각이 없다면 대입하는 줄이 잘못되었습니다.", "Una variable const (constexpr) no puede cambiar su valor inicial. Para cambiarla, quite const. Si no quería cambiarla, la línea de asignación está mal.", "Uma variável const (constexpr) não pode mudar o valor inicial. Para mudar, remova const. Se não queria mudar, a linha de atribuição está errada.", "Eine const- (constexpr-)Variable kann ihren Anfangswert nicht ändern. Zum Ändern const entfernen. Sonst ist die Zuweisungszeile falsch.", "Une variable const (constexpr) ne peut pas changer sa valeur initiale. Pour la changer, retirez const. Sinon, la ligne d'affectation est erronée.", "Переменную const (constexpr) нельзя изменить после инициализации. Чтобы менять, уберите const. Если менять не нужно, ошибочна строка с присваиванием." },
            ["引数と同じ名前の変数を、関数の中で作っています"] = new[] { "A variable with the same name as a parameter is created inside the function", "在函数中创建了与参数同名的变量", "인수와 같은 이름의 변수를 함수 안에서 만들고 있습니다", "Se crea dentro de la función una variable con el nombre de un parámetro", "Uma variável com o nome de um parâmetro é criada dentro da função", "In der Funktion wird eine Variable mit Parameternamen angelegt", "Une variable du même nom qu'un paramètre est créée dans la fonction", "Внутри функции создаётся переменная с именем параметра" },
            ["関数の引数と同じ名前の変数を、関数の一番外側の { } の中でもう一度宣言しています。名前を変えるか、宣言をやめて、引数にそのまま代入します。"] = new[] { "A variable with the same name as a function parameter is declared again in the function's outermost { }. Rename it, or drop the declaration and assign to the parameter directly.", "在函数最外层的 { } 中，再次声明了与函数参数同名的变量。改名，或去掉声明直接给参数赋值。", "함수의 인수와 같은 이름의 변수를 함수 가장 바깥 { } 안에서 다시 선언하고 있습니다. 이름을 바꾸거나 선언을 그만두고 인수에 그대로 대입합니다.", "En las { } más externas de la función se vuelve a declarar una variable con el nombre de un parámetro. Renómbrela o quite la declaración y asigne al parámetro.", "Nas { } mais externas da função, uma variável com o nome de um parâmetro é declarada de novo. Renomeie ou remova a declaração e atribua ao parâmetro.", "Im äußersten { } der Funktion wird eine Variable mit Parameternamen erneut deklariert. Umbenennen oder die Deklaration weglassen und dem Parameter zuweisen.", "Dans les { } les plus externes de la fonction, une variable portant le nom d'un paramètre est redéclarée. Renommez-la ou supprimez la déclaration et affectez le paramètre.", "Во внешних { } функции повторно объявлена переменная с именем параметра. Переименуйте её или уберите объявление и присвойте параметру." },
            ["void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // 直し方 1: 宣言をやめて代入にする\n}"] = new[] { "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Fix 1: drop the declaration and assign\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // 修正 1：去掉声明改为赋值\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // 고치는 법 1: 선언을 그만두고 대입한다\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Arreglo 1: quitar la declaración y asignar\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Correção 1: remover a declaração e atribuir\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Lösung 1: Deklaration weglassen, zuweisen\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Correction 1 : supprimer la déclaration et affecter\n}", "void F(int a) {\n  int a = 2;        // C2082\n}\n\nvoid F(int a) {\n  a = 2;            // Исправление 1: убрать объявление и присвоить\n}" },
            ["同じ名前の変数を、同じ場所で 2 回初期化しています"] = new[] { "A variable with the same name is initialized twice in the same place", "在同一处两次初始化了同名变量", "같은 이름의 변수를 같은 곳에서 두 번 초기화하고 있습니다", "Se inicializa dos veces una variable con el mismo nombre en el mismo lugar", "Uma variável com o mesmo nome é inicializada duas vezes no mesmo lugar", "Gleichnamige Variable wird an derselben Stelle zweimal initialisiert", "Une variable du même nom est initialisée deux fois au même endroit", "Переменная с тем же именем инициализирована дважды в одном месте" },
            ["同じスコープに、同じ名前の変数が 2 つあります。後ろの宣言の名前を変えるか、宣言をやめて代入にします。for の中の { } の入れ子は、別のスコープなので別の変数にできますが、同じ名前は紛らわしくなります。"] = new[] { "There are two variables with the same name in the same scope. Rename the later declaration, or drop it and assign instead. A nested { } inside a for is a separate scope, so it can be a different variable, but the same name gets confusing.", "同一作用域中有两个同名变量。改掉后一个声明的名字，或去掉声明改为赋值。for 中嵌套的 { } 是另一作用域，可以是不同的变量，但同名容易混淆。", "같은 스코프에 같은 이름의 변수가 둘 있습니다. 뒤쪽 선언의 이름을 바꾸거나 선언을 그만두고 대입으로 합니다. for 안의 { } 중첩은 다른 스코프라 다른 변수로 할 수 있지만 같은 이름은 헷갈립니다.", "Hay dos variables con el mismo nombre en el mismo ámbito. Renombre la segunda declaración o quítela y asigne. Unas { } anidadas en un for son otro ámbito y pueden ser otra variable, pero el mismo nombre confunde.", "Há duas variáveis com o mesmo nome no mesmo escopo. Renomeie a segunda declaração ou remova-a e atribua. { } aninhadas num for são outro escopo e podem ser outra variável, mas o mesmo nome confunde.", "Im selben Bereich gibt es zwei gleichnamige Variablen. Die spätere Deklaration umbenennen oder weglassen und zuweisen. Verschachtelte { } in einem for sind ein eigener Bereich, aber gleiche Namen verwirren.", "Deux variables du même nom existent dans la même portée. Renommez la seconde déclaration ou supprimez-la et affectez. Des { } imbriquées dans un for forment une autre portée, mais le même nom prête à confusion.", "В одной области две переменные с одним именем. Переименуйте вторую или уберите её объявление и присвойте. Вложенные { } в for — другая область, там можно, но одинаковые имена путают." },
            ["auto の変数に、初期化の式がありません"] = new[] { "auto variable has no initializer", "auto 变量没有初始化表达式", "auto 변수에 초기화 식이 없습니다", "La variable auto no tiene inicializador", "A variável auto não tem inicializador", "auto-Variable ohne Initialisierer", "Variable auto sans initialiseur", "У переменной auto нет инициализатора" },
            ["auto は、初期化の式から型を決めます。式がないと型が決まりません。「auto x = 値;」と書くか、型を自分で書きます。範囲 for の `for (auto e : 5)` で出るときは、回す対象が配列やコンテナになっていません。"] = new[] { "auto decides the type from the initializer. Without one, the type cannot be decided. Write \"auto x = value;\" or write the type yourself. If it appears in a range-based for like `for (auto e : 5)`, what you loop over is not an array or container.", "auto 根据初始化表达式确定类型。没有表达式就无法确定类型。写成“auto x = 值;”，或自己写出类型。若出现在范围 for 的 `for (auto e : 5)` 中，说明遍历对象不是数组或容器。", "auto는 초기화 식으로 타입을 정합니다. 식이 없으면 타입이 정해지지 않습니다. \"auto x = 값;\"으로 쓰거나 타입을 직접 씁니다. 범위 for의 `for (auto e : 5)`에서 나올 때는 돌리는 대상이 배열이나 컨테이너가 아닙니다.", "auto deduce el tipo del inicializador. Sin él, no hay tipo. Escriba \"auto x = valor;\" o el tipo. Si aparece en un for de rango como `for (auto e : 5)`, lo recorrido no es un array ni un contenedor.", "auto deduz o tipo do inicializador. Sem ele, não há tipo. Escreva \"auto x = valor;\" ou o tipo. Se aparecer num for de intervalo como `for (auto e : 5)`, o que é percorrido não é array nem contêiner.", "auto bestimmt den Typ aus dem Initialisierer. Ohne ihn gibt es keinen Typ. \"auto x = Wert;\" oder den Typ selbst schreiben. Bei bereichsbasiertem for wie `for (auto e : 5)` ist das Durchlaufene kein Array oder Container.", "auto déduit le type de l'initialiseur. Sans lui, pas de type. Écrivez « auto x = valeur; » ou le type vous-même. Dans un for sur plage comme `for (auto e : 5)`, ce qui est parcouru n'est ni un tableau ni un conteneur.", "auto выводит тип из инициализатора. Без него тип не определить. Напишите «auto x = значение;» или укажите тип. Если ошибка в for по диапазону вроде `for (auto e : 5)`, перебираемое — не массив и не контейнер." },
            ["構造化束縛(auto [a, b])できない型です"] = new[] { "Type cannot be used with structured binding (auto [a, b])", "该类型不能使用结构化绑定（auto [a, b]）", "구조화된 바인딩(auto [a, b])을 할 수 없는 타입입니다", "El tipo no admite enlace estructurado (auto [a, b])", "O tipo não admite structured binding (auto [a, b])", "Typ nicht für strukturierte Bindung (auto [a, b]) geeignet", "Type non utilisable avec une liaison structurée (auto [a, b])", "Тип нельзя использовать в структурной привязке (auto [a, b])" },
            ["auto [a, b] = x; で分解できるのは、配列、メンバーがすべて public のクラス・構造体、std::pair / std::tuple のように分解の仕組みを持つ型だけです。int のような 1 つの値は分解できません。"] = new[] { "auto [a, b] = x; can only decompose arrays, classes / structs whose members are all public, and types with a decomposition mechanism like std::pair / std::tuple. A single value like int cannot be decomposed.", "auto [a, b] = x; 只能分解数组、成员全为 public 的类和结构体，以及 std::pair / std::tuple 这样具有分解机制的类型。int 这样的单个值无法分解。", "auto [a, b] = x;로 분해할 수 있는 것은 배열, 멤버가 모두 public인 클래스·구조체, std::pair / std::tuple처럼 분해 구조를 가진 타입뿐입니다. int 같은 값 하나는 분해할 수 없습니다.", "auto [a, b] = x; solo descompone arrays, clases o structs con todos los miembros public y tipos con mecanismo de descomposición como std::pair / std::tuple. Un valor único como int no se descompone.", "auto [a, b] = x; só decompõe arrays, classes / structs com todos os membros public e tipos com mecanismo de decomposição como std::pair / std::tuple. Um valor único como int não se decompõe.", "auto [a, b] = x; zerlegt nur Arrays, Klassen/Strukturen mit nur public-Membern und Typen mit Zerlegungsmechanismus wie std::pair / std::tuple. Ein Einzelwert wie int lässt sich nicht zerlegen.", "auto [a, b] = x; ne décompose que les tableaux, les classes / structures dont tous les membres sont public et les types ayant un mécanisme de décomposition comme std::pair / std::tuple. Une valeur unique comme int ne se décompose pas.", "auto [a, b] = x; раскладывает только массивы, классы / структуры со всеми public-членами и типы с механизмом разложения вроде std::pair / std::tuple. Одно значение вроде int разложить нельзя." },
            ["条件式の中で、= (代入) を使っています"] = new[] { "= (assignment) used in a condition", "在条件表达式中使用了 =（赋值）", "조건식 안에서 =(대입)를 쓰고 있습니다", "Se usa = (asignación) en una condición", "= (atribuição) usado numa condição", "= (Zuweisung) in einer Bedingung", "= (affectation) utilisé dans une condition", "В условии используется = (присваивание)" },
            ["if (x = 3) は、代入して、その値で判断します。比較のつもりなら == と書きます。代入が意図なら、if ((x = 3) != 0) のように括弧と比較で、意図を示します。"] = new[] { "if (x = 3) assigns and then tests that value. If you meant to compare, write ==. If the assignment is intended, show it with parentheses and a comparison, like if ((x = 3) != 0).", "if (x = 3) 会先赋值，再用该值判断。本意是比较就写 ==。确实要赋值时，像 if ((x = 3) != 0) 这样用括号和比较表明意图。", "if (x = 3)은 대입한 뒤 그 값으로 판단합니다. 비교할 생각이라면 ==로 씁니다. 대입이 의도라면 if ((x = 3) != 0)처럼 괄호와 비교로 의도를 나타냅니다.", "if (x = 3) asigna y evalúa ese valor. Si quería comparar, escriba ==. Si la asignación es intencionada, muéstrelo con paréntesis y comparación: if ((x = 3) != 0).", "if (x = 3) atribui e avalia esse valor. Se queria comparar, escreva ==. Se a atribuição é intencional, mostre com parênteses e comparação: if ((x = 3) != 0).", "if (x = 3) weist zu und prüft dann den Wert. Für einen Vergleich == schreiben. Ist die Zuweisung gewollt, mit Klammern und Vergleich zeigen: if ((x = 3) != 0).", "if (x = 3) affecte puis teste cette valeur. Pour comparer, écrivez ==. Si l'affectation est voulue, montrez-le avec parenthèses et comparaison : if ((x = 3) != 0).", "if (x = 3) присваивает и проверяет это значение. Для сравнения пишите ==. Если присваивание задумано, покажите это скобками и сравнением: if ((x = 3) != 0)." },
            ["constexpr に使えない式です (コンパイル時に決まりません)"] = new[] { "Expression not usable in constexpr (not known at compile time)", "不能用于 constexpr 的表达式（编译时无法确定）", "constexpr에 쓸 수 없는 식입니다(컴파일 시 정해지지 않음)", "Expresión no válida en constexpr (no se conoce al compilar)", "Expressão não válida em constexpr (não é conhecida na compilação)", "In constexpr unzulässiger Ausdruck (zur Kompilierzeit unbekannt)", "Expression non utilisable en constexpr (inconnue à la compilation)", "Выражение нельзя использовать в constexpr (не известно при компиляции)" },
            ["constexpr の変数や関数の引数に、実行時にしか決まらない値(const でない変数、constexpr でない関数の呼び出し)が入っています。その関数に constexpr を付けるか、constexpr をやめます。"] = new[] { "A constexpr variable or function argument gets a value known only at run time (a non-const variable, a call to a non-constexpr function). Add constexpr to that function, or drop constexpr.", "constexpr 的变量或函数参数中有只能在运行时确定的值（非 const 变量、非 constexpr 函数的调用）。给该函数加上 constexpr，或不用 constexpr。", "constexpr 변수나 함수 인수에 실행 시에만 정해지는 값(const가 아닌 변수, constexpr가 아닌 함수 호출)이 들어 있습니다. 그 함수에 constexpr를 붙이거나 constexpr를 그만둡니다.", "Una variable o argumento constexpr recibe un valor que solo se conoce en ejecución (variable no const, llamada a función no constexpr). Añada constexpr a esa función o quite constexpr.", "Uma variável ou argumento constexpr recebe um valor só conhecido em execução (variável não const, chamada a função não constexpr). Adicione constexpr à função ou remova constexpr.", "Eine constexpr-Variable oder ein Argument erhält einen erst zur Laufzeit bekannten Wert (nicht-const-Variable, Aufruf einer nicht-constexpr-Funktion). Funktion constexpr machen oder constexpr entfernen.", "Une variable ou un argument constexpr reçoit une valeur connue seulement à l'exécution (variable non const, appel d'une fonction non constexpr). Ajoutez constexpr à cette fonction ou retirez constexpr.", "Переменная или аргумент constexpr получает значение, известное только при выполнении (не-const переменная, вызов не-constexpr функции). Добавьте функции constexpr или откажитесь от constexpr." },
            ["struct A { int x; }      // ← ; がない\nstruct B { };                // C2628 / C2632 (次の行で出る)\n\nstruct A { int x; };     // 直し方: } のあとに ;"] = new[] { "struct A { int x; }      // ← no ;\nstruct B { };                // C2628 / C2632 (appears on the next line)\n\nstruct A { int x; };     // Fix: ; after }", "struct A { int x; }      // ← 缺少 ;\nstruct B { };                // C2628 / C2632 (在下一行出现)\n\nstruct A { int x; };     // 修正：} 后面加 ;", "struct A { int x; }      // ← ;가 없다\nstruct B { };                // C2628 / C2632 (다음 줄에서 나온다)\n\nstruct A { int x; };     // 고치는 법: } 뒤에 ;", "struct A { int x; }      // ← falta ;\nstruct B { };                // C2628 / C2632 (aparece en la línea siguiente)\n\nstruct A { int x; };     // Arreglo: ; tras }", "struct A { int x; }      // ← falta ;\nstruct B { };                // C2628 / C2632 (aparece na linha seguinte)\n\nstruct A { int x; };     // Correção: ; após }", "struct A { int x; }      // ← ; fehlt\nstruct B { };                // C2628 / C2632 (erscheint in der nächsten Zeile)\n\nstruct A { int x; };     // Lösung: ; nach }", "struct A { int x; }      // ← pas de ;\nstruct B { };                // C2628 / C2632 (apparaît à la ligne suivante)\n\nstruct A { int x; };     // Correction : ; après }", "struct A { int x; }      // ← нет ;\nstruct B { };                // C2628 / C2632 (появляется на следующей строке)\n\nstruct A { int x; };     // Исправление: ; после }" },
            ["型の後に別の型が続いています (; の忘れ)"] = new[] { "Another type follows a type (forgotten ;)", "类型后面又跟了另一个类型（忘了 ;）", "타입 뒤에 다른 타입이 이어집니다(; 빠뜨림)", "Un tipo va seguido de otro (falta ;)", "Um tipo é seguido de outro (falta ;)", "Auf einen Typ folgt ein weiterer (; vergessen)", "Un type est suivi d'un autre (; oublié)", "За типом следует другой тип (забыт ;)" },
            ["多くは、クラスや構造体の定義の最後の「}」のあとの「;」の忘れです。エラーの 1 つ前の宣言を見ます。"] = new[] { "Usually a forgotten \";\" after the final \"}\" of a class or struct definition. Look at the declaration just before the error.", "多为类或结构体定义末尾的“}”后面忘了“;”。看错误前的一个声明。", "대개 클래스나 구조체 정의 마지막 \"}\" 뒤의 \";\"를 빠뜨린 것입니다. 오류 바로 앞 선언을 봅니다.", "Casi siempre falta \";\" tras la \"}\" final de una clase o struct. Mire la declaración anterior al error.", "Quase sempre falta \";\" após a \"}\" final de uma classe ou struct. Olhe a declaração antes do erro.", "Meist fehlt \";\" nach dem letzten \"}\" einer Klassen- oder Strukturdefinition. Die Deklaration vor dem Fehler ansehen.", "Le plus souvent, un « ; » oublié après la « } » finale d'une classe ou structure. Regardez la déclaration juste avant l'erreur.", "Обычно забыт «;» после последней «}» определения класса или структуры. Посмотрите на объявление перед ошибкой." },
            ["戻り値の型だけが違うオーバーロードです"] = new[] { "Overload that differs only in return type", "只有返回类型不同的重载", "반환 타입만 다른 오버로드입니다", "Sobrecarga que solo difiere en el tipo de retorno", "Sobrecarga que difere só no tipo de retorno", "Überladung, die sich nur im Rückgabetyp unterscheidet", "Surcharge qui ne diffère que par le type de retour", "Перегрузка, отличающаяся только типом возврата" },
            ["引数が同じで、戻り値の型だけが違う関数は、オーバーロードにできません。ヘッダーの宣言と、cpp の定義で、戻り値か引数が食い違っていることが多いです。(Alt+G で引数を、Alt+R で相手を作れます)"] = new[] { "Functions with the same parameters that differ only in return type cannot be overloads. Often the header declaration and the cpp definition disagree on the return type or parameters. (Alt+G copies parameters, Alt+R creates the counterpart)", "参数相同、仅返回类型不同的函数不能构成重载。多为头文件的声明与 cpp 的定义在返回值或参数上不一致。（Alt+G 可同步参数，Alt+R 可创建另一方）", "인수가 같고 반환 타입만 다른 함수는 오버로드가 될 수 없습니다. 헤더의 선언과 cpp의 정의에서 반환값이나 인수가 어긋난 경우가 많습니다. (Alt+G로 인수를, Alt+R로 상대를 만들 수 있습니다)", "Funciones con los mismos parámetros que solo difieren en el retorno no pueden ser sobrecargas. Suele ocurrir que la declaración del encabezado y la definición del cpp no coinciden en el retorno o los parámetros. (Alt+G copia parámetros, Alt+R crea la contraparte)", "Funções com os mesmos parâmetros que diferem só no retorno não podem ser sobrecargas. Costuma acontecer que a declaração do cabeçalho e a definição do cpp divergem no retorno ou nos parâmetros. (Alt+G copia parâmetros, Alt+R cria a contraparte)", "Funktionen mit gleichen Parametern, die sich nur im Rückgabetyp unterscheiden, sind keine Überladungen. Oft weichen Header-Deklaration und cpp-Definition bei Rückgabe oder Parametern ab. (Alt+G übernimmt Parameter, Alt+R erzeugt das Gegenstück)", "Des fonctions aux mêmes paramètres ne différant que par le type de retour ne peuvent pas être des surcharges. Souvent, la déclaration de l'en-tête et la définition du cpp divergent sur le retour ou les paramètres. (Alt+G copie les paramètres, Alt+R crée la contrepartie)", "Функции с одинаковыми параметрами, отличающиеся только типом возврата, не могут быть перегрузками. Часто объявление в заголовке и определение в cpp расходятся в типе возврата или параметрах. (Alt+G переносит параметры, Alt+R создаёт парную сторону)" },
            ["同じ名前を、違う型修飾で再定義しています"] = new[] { "Same name redefined with different type qualifiers", "以不同的类型修饰重定义了同一名称", "같은 이름을 다른 타입 한정자로 재정의하고 있습니다", "El mismo nombre se redefine con otros calificadores de tipo", "O mesmo nome é redefinido com outros qualificadores de tipo", "Gleicher Name mit anderen Typqualifizierern neu definiert", "Même nom redéfini avec d'autres qualificatifs de type", "То же имя переопределено с другими квалификаторами типа" },
            ["同じ名前の関数や変数を、const・参照・ポインターなどが違う型で宣言しています。宣言と定義の型をそろえます。"] = new[] { "A function or variable with the same name is declared with types differing in const, reference, pointer, etc. Make the declaration and definition types match.", "同名的函数或变量以 const、引用、指针等不同的类型声明。统一声明与定义的类型。", "같은 이름의 함수나 변수를 const·참조·포인터 등이 다른 타입으로 선언하고 있습니다. 선언과 정의의 타입을 맞춥니다.", "Una función o variable con el mismo nombre se declara con tipos que difieren en const, referencia, puntero, etc. Iguale los tipos de declaración y definición.", "Uma função ou variável com o mesmo nome é declarada com tipos que diferem em const, referência, ponteiro etc. Iguale os tipos da declaração e da definição.", "Gleichnamige Funktion oder Variable wird mit abweichendem const, Referenz, Zeiger usw. deklariert. Typen von Deklaration und Definition angleichen.", "Une fonction ou variable du même nom est déclarée avec des types différant par const, référence, pointeur, etc. Harmonisez les types de la déclaration et de la définition.", "Функция или переменная с тем же именем объявлена с другими const, ссылкой, указателем и т. п. Согласуйте типы в объявлении и определении." },
            ["既定の引数が重複しています"] = new[] { "Default argument duplicated", "默认参数重复", "기본 인수가 중복되어 있습니다", "Argumento predeterminado duplicado", "Argumento padrão duplicado", "Standardargument doppelt", "Argument par défaut en double", "Повтор аргумента по умолчанию" },
            ["既定の引数(= 値)は、宣言(ヘッダー)にだけ書きます。cpp の定義には書きません。(Alt+G は、引数を写すとき、cpp 側の既定値を外します)"] = new[] { "Write default arguments (= value) only in the declaration (header), not in the cpp definition. (Alt+G removes cpp-side defaults when copying parameters)", "默认参数（= 值）只写在声明（头文件）中，不写在 cpp 的定义中。（Alt+G 同步参数时会去掉 cpp 端的默认值）", "기본 인수(= 값)는 선언(헤더)에만 씁니다. cpp의 정의에는 쓰지 않습니다. (Alt+G는 인수를 옮길 때 cpp 쪽 기본값을 뺍니다)", "Escriba los argumentos predeterminados (= valor) solo en la declaración (encabezado), no en la definición del cpp. (Alt+G quita los valores predeterminados del cpp al copiar parámetros)", "Escreva argumentos padrão (= valor) só na declaração (cabeçalho), não na definição do cpp. (Alt+G remove os valores padrão do cpp ao copiar parâmetros)", "Standardargumente (= Wert) nur in die Deklaration (Header) schreiben, nicht in die cpp-Definition. (Alt+G entfernt beim Übernehmen die cpp-Standardwerte)", "N'écrivez les arguments par défaut (= valeur) que dans la déclaration (en-tête), pas dans la définition du cpp. (Alt+G retire les valeurs par défaut côté cpp en copiant les paramètres)", "Аргументы по умолчанию (= значение) пишут только в объявлении (заголовке), не в определении в cpp. (Alt+G при переносе параметров убирает значения по умолчанию в cpp)" },
            ["// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // 直し方: 定義には書かない"] = new[] { "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Fix: do not write it in the definition", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // 修正：定义中不写", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // 고치는 법: 정의에는 쓰지 않는다", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Arreglo: no escribirlo en la definición", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Correção: não escrever na definição", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Lösung: nicht in die Definition schreiben", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Correction : ne pas l'écrire dans la définition", "// Foo.h\nvoid Run(int n = 3);\n\n// Foo.cpp\nvoid Foo::Run(int n = 3) {}   // C2572\nvoid Foo::Run(int n) {}       // Исправление: не писать в определении" },
            ["オブジェクトなしで、非 static のメンバーを使っています"] = new[] { "Using a non-static member without an object", "在没有对象的情况下使用非 static 成员", "객체 없이 비 static 멤버를 쓰고 있습니다", "Se usa un miembro no static sin objeto", "Usando membro não static sem objeto", "Nicht-static-Member ohne Objekt verwendet", "Membre non static utilisé sans objet", "Не-static член используется без объекта" },
            ["static 関数の中や、オブジェクトを持たない場所で、インスタンスのメンバーを使っています。オブジェクトを通して使うか、メンバーを static にします。"] = new[] { "An instance member is used inside a static function or where there is no object. Use it through an object, or make the member static.", "在 static 函数中或没有对象的地方使用了实例成员。通过对象使用，或把成员设为 static。", "static 함수 안이나 객체가 없는 곳에서 인스턴스 멤버를 쓰고 있습니다. 객체를 통해 쓰거나 멤버를 static으로 합니다.", "Se usa un miembro de instancia dentro de una función static o donde no hay objeto. Úselo mediante un objeto o haga el miembro static.", "Um membro de instância é usado numa função static ou onde não há objeto. Use-o por um objeto ou torne o membro static.", "Ein Instanzmember wird in einer static-Funktion oder ohne Objekt verwendet. Über ein Objekt nutzen oder den Member static machen.", "Un membre d'instance est utilisé dans une fonction static ou sans objet. Utilisez-le via un objet ou rendez-le static.", "Член экземпляра используется в static-функции или там, где нет объекта. Обращайтесь через объект или сделайте член static." },
            ["オブジェクトなしで、非 static のメンバー関数を呼んでいます"] = new[] { "Calling a non-static member function without an object", "在没有对象的情况下调用非 static 成员函数", "객체 없이 비 static 멤버 함수를 호출하고 있습니다", "Se llama a una función miembro no static sin objeto", "Chamando função membro não static sem objeto", "Nicht-static-Memberfunktion ohne Objekt aufgerufen", "Appel d'une fonction membre non static sans objet", "Вызов не-static функции-члена без объекта" },
            ["クラス名::関数() の形で、インスタンス用のメンバー関数を呼んでいます。オブジェクトを作って呼ぶか、関数を static にします。"] = new[] { "An instance member function is called as ClassName::Function(). Create an object and call it, or make the function static.", "以“类名::函数()”的形式调用了实例用的成员函数。创建对象后调用，或把函数设为 static。", "클래스명::함수() 형태로 인스턴스용 멤버 함수를 호출하고 있습니다. 객체를 만들어 호출하거나 함수를 static으로 합니다.", "Se llama a una función miembro de instancia como Clase::Función(). Cree un objeto y llámela, o haga la función static.", "Uma função membro de instância é chamada como Classe::Função(). Crie um objeto e chame, ou torne a função static.", "Eine Instanz-Memberfunktion wird als Klasse::Funktion() aufgerufen. Objekt erzeugen und aufrufen oder Funktion static machen.", "Une fonction membre d'instance est appelée sous la forme Classe::Fonction(). Créez un objet pour l'appeler ou rendez-la static.", "Функция-член экземпляра вызывается как Класс::Функция(). Создайте объект и вызовите или сделайте функцию static." },
            ["const の違いで、メンバー関数を呼べません"] = new[] { "Cannot call the member function because of const", "因 const 的差异无法调用成员函数", "const 차이로 멤버 함수를 호출할 수 없습니다", "No se puede llamar a la función miembro por const", "Não é possível chamar a função membro por causa de const", "Memberfunktion wegen const nicht aufrufbar", "Impossible d'appeler la fonction membre à cause de const", "Нельзя вызвать функцию-член из-за const" },
            ["const のオブジェクトから、const が付いていないメンバー関数を呼んでいます(その逆もあります)。その関数に const を付けるか、const 版と非 const 版の両方を用意します。"] = new[] { "A const object calls a member function without const (or the reverse). Add const to that function, or provide both const and non-const versions.", "从 const 对象调用了未加 const 的成员函数（也可能相反）。给该函数加 const，或同时提供 const 版和非 const 版。", "const 객체에서 const가 붙지 않은 멤버 함수를 호출하고 있습니다(그 반대도 있습니다). 그 함수에 const를 붙이거나 const 판과 비 const 판을 둘 다 준비합니다.", "Un objeto const llama a una función miembro sin const (o al revés). Añada const a la función o proporcione versiones const y no const.", "Um objeto const chama uma função membro sem const (ou o contrário). Adicione const à função ou ofereça versões const e não const.", "Ein const-Objekt ruft eine Memberfunktion ohne const auf (oder umgekehrt). Funktion const machen oder const- und Nicht-const-Version anbieten.", "Un objet const appelle une fonction membre sans const (ou l'inverse). Ajoutez const à la fonction ou fournissez une version const et une non const.", "const-объект вызывает функцию-член без const (или наоборот). Добавьте функции const или сделайте обе версии — const и не-const." },
            ["どのオーバーロードか、1 つに決まりません"] = new[] { "Cannot narrow down to one overload", "无法确定为一个重载", "어느 오버로드인지 하나로 정해지지 않습니다", "No se puede elegir una sola sobrecarga", "Não dá para escolher uma só sobrecarga", "Überladung nicht eindeutig bestimmbar", "Impossible de retenir une seule surcharge", "Не удаётся выбрать одну перегрузку" },
            ["複数のオーバーロードが、同じくらい合っています。引数に static_cast を付けて型を明示するか、オーバーロードを整理します。"] = new[] { "Several overloads match equally well. Add static_cast to an argument to make the type explicit, or tidy up the overloads.", "多个重载同样匹配。给参数加 static_cast 明确类型，或整理重载。", "여러 오버로드가 똑같이 맞습니다. 인수에 static_cast를 붙여 타입을 명시하거나 오버로드를 정리합니다.", "Varias sobrecargas coinciden igual de bien. Añada static_cast a un argumento o reorganice las sobrecargas.", "Várias sobrecargas combinam igualmente. Adicione static_cast a um argumento ou reorganize as sobrecargas.", "Mehrere Überladungen passen gleich gut. Argument mit static_cast versehen oder Überladungen aufräumen.", "Plusieurs surcharges conviennent autant. Ajoutez static_cast à un argument ou réorganisez les surcharges.", "Несколько перегрузок подходят одинаково. Добавьте static_cast к аргументу или упорядочьте перегрузки." },
            ["初期化子リストに、メンバーでも基底クラスでもない名前があります"] = new[] { "The initializer list has a name that is neither a member nor a base class", "初始化列表中有既非成员也非基类的名称", "초기화 목록에 멤버도 기본 클래스도 아닌 이름이 있습니다", "La lista de inicialización tiene un nombre que no es miembro ni clase base", "A lista de inicialização tem um nome que não é membro nem classe base", "Die Initialisierungsliste enthält einen Namen, der weder Member noch Basisklasse ist", "La liste d'initialisation contient un nom qui n'est ni un membre ni une classe de base", "В списке инициализации имя, не являющееся ни членом, ни базовым классом" },
            ["コンストラクターの「: a_(1), b_(2)」に、そのクラスのメンバーにも基底クラスにもない名前があります。綴りと、メンバーの宣言を確かめます。"] = new[] { "The constructor's \": a_(1), b_(2)\" has a name that is neither a member nor a base class of the class. Check the spelling and the member declarations.", "构造函数的“: a_(1), b_(2)”中有既不是该类成员也不是基类的名称。检查拼写和成员的声明。", "생성자의 \": a_(1), b_(2)\"에 그 클래스의 멤버도 기본 클래스도 아닌 이름이 있습니다. 철자와 멤버 선언을 확인합니다.", "En \": a_(1), b_(2)\" del constructor hay un nombre que no es miembro ni base de la clase. Revise la ortografía y las declaraciones de miembros.", "Em \": a_(1), b_(2)\" do construtor há um nome que não é membro nem base da classe. Verifique a grafia e as declarações dos membros.", "Im \": a_(1), b_(2)\" des Konstruktors steht ein Name, der weder Member noch Basisklasse ist. Schreibweise und Memberdeklarationen prüfen.", "Dans « : a_(1), b_(2) » du constructeur figure un nom qui n'est ni membre ni base de la classe. Vérifiez l'orthographe et les déclarations des membres.", "В «: a_(1), b_(2)» конструктора есть имя, не являющееся членом или базой класса. Проверьте написание и объявления членов." },
            ["参照メンバーは初期化が必要です"] = new[] { "Reference members must be initialized", "引用成员必须初始化", "참조 멤버는 초기화가 필요합니다", "Los miembros referencia deben inicializarse", "Membros referência precisam ser inicializados", "Referenzmember müssen initialisiert werden", "Les membres référence doivent être initialisés", "Члены-ссылки нужно инициализировать" },
            ["参照型や const のメンバーは、コンストラクターの初期化子リストで初期化します。"] = new[] { "Initialize reference and const members in the constructor's initializer list.", "引用类型和 const 成员要在构造函数的初始化列表中初始化。", "참조 타입이나 const 멤버는 생성자의 초기화 목록에서 초기화합니다.", "Inicialice los miembros referencia y const en la lista de inicialización del constructor.", "Inicialize membros referência e const na lista de inicialização do construtor.", "Referenz- und const-Member in der Initialisierungsliste des Konstruktors initialisieren.", "Initialisez les membres référence et const dans la liste d'initialisation du constructeur.", "Инициализируйте члены-ссылки и const в списке инициализации конструктора." },
            ["struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // 初期化子リストで初期化する\n};"] = new[] { "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // initialize in the initializer list\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // 在初始化列表中初始化\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // 초기화 목록에서 초기화한다\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // inicializar en la lista de inicialización\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // inicializar na lista de inicialização\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // in der Initialisierungsliste initialisieren\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // initialiser dans la liste d'initialisation\n};", "struct Foo {\n  int& r_;\n  Foo(int& r) : r_(r) {}   // инициализировать в списке инициализации\n};" },
            ["const の変数は、宣言と同時に初期化が必要です"] = new[] { "A const variable must be initialized when declared", "const 变量必须在声明时初始化", "const 변수는 선언과 동시에 초기화가 필요합니다", "Una variable const debe inicializarse al declararla", "Uma variável const deve ser inicializada ao ser declarada", "Eine const-Variable muss bei der Deklaration initialisiert werden", "Une variable const doit être initialisée à sa déclaration", "Переменную const нужно инициализировать при объявлении" },
            ["const 変数には、宣言と同時に値を入れます。"] = new[] { "Give a const variable its value when you declare it.", "const 变量要在声明的同时赋值。", "const 변수에는 선언과 동시에 값을 넣습니다.", "Dé valor a la variable const al declararla.", "Dê valor à variável const ao declará-la.", "Einer const-Variable bei der Deklaration einen Wert geben.", "Donnez sa valeur à la variable const lors de sa déclaration.", "Задайте значение const-переменной при объявлении." },
            ["const のものへ代入しています"] = new[] { "Assigning to something const", "给 const 的东西赋值", "const인 것에 대입하고 있습니다", "Se asigna a algo const", "Atribuindo a algo const", "Zuweisung an etwas const", "Affectation à quelque chose de const", "Присваивание чему-то const" },
            ["const の変数や、const 関数の中のメンバーへ代入しています。const を外すか、代入をやめます。"] = new[] { "Assigning to a const variable or to a member inside a const function. Remove const, or stop assigning.", "给 const 变量或 const 函数中的成员赋值。去掉 const，或不再赋值。", "const 변수나 const 함수 안의 멤버에 대입하고 있습니다. const를 떼거나 대입을 그만둡니다.", "Se asigna a una variable const o a un miembro dentro de una función const. Quite const o no asigne.", "Atribuindo a uma variável const ou a um membro dentro de função const. Remova const ou não atribua.", "Zuweisung an eine const-Variable oder einen Member in einer const-Funktion. const entfernen oder nicht zuweisen.", "Affectation à une variable const ou à un membre dans une fonction const. Retirez const ou n'affectez pas.", "Присваивание const-переменной или члену в const-функции. Уберите const или не присваивайте." },
            ["初期化子が多すぎます"] = new[] { "Too many initializers", "初始值设定项过多", "초기화자가 너무 많습니다", "Demasiados inicializadores", "Inicializadores demais", "Zu viele Initialisierer", "Trop d'initialiseurs", "Слишком много инициализаторов" },
            ["配列や構造体のメンバーより多い値を、{ } に書いています。数を数え直します。"] = new[] { "More values are written in { } than the array or struct has members. Count again.", "在 { } 中写的值多于数组或结构体的成员数。重新数一下。", "배열이나 구조체 멤버보다 많은 값을 { }에 쓰고 있습니다. 수를 다시 셉니다.", "Hay más valores en { } que miembros en el array o la estructura. Vuelva a contar.", "Há mais valores em { } que membros no array ou estrutura. Conte de novo.", "In { } stehen mehr Werte als Array oder Struktur Member hat. Neu zählen.", "Il y a plus de valeurs dans { } que de membres dans le tableau ou la structure. Recomptez.", "В { } больше значений, чем членов у массива или структуры. Пересчитайте." },
            ["型を、式として使っています"] = new[] { "Using a type as an expression", "把类型当作表达式使用", "타입을 식으로 쓰고 있습니다", "Se usa un tipo como expresión", "Usando um tipo como expressão", "Typ wird als Ausdruck verwendet", "Type utilisé comme expression", "Тип используется как выражение" },
            ["型名を、値が要る場所で使っています。テンプレートの中の「typename T::type」の typename の付け忘れや、() の付け忘れが多いです。"] = new[] { "A type name is used where a value is needed. Common causes are forgetting typename in \"typename T::type\" inside a template, or forgetting ().", "在需要值的地方使用了类型名。常见的是模板中“typename T::type”忘了加 typename，或忘了加 ()。", "값이 필요한 곳에서 타입 이름을 쓰고 있습니다. 템플릿 안의 \"typename T::type\"에서 typename을 빠뜨리거나 ()를 빠뜨린 경우가 많습니다.", "Se usa un nombre de tipo donde se necesita un valor. Suele faltar typename en \"typename T::type\" dentro de una plantilla, o faltar ().", "Um nome de tipo é usado onde é preciso um valor. Costuma faltar typename em \"typename T::type\" num template, ou faltar ().", "Ein Typname steht dort, wo ein Wert nötig ist. Oft fehlt typename bei \"typename T::type\" im Template oder ein ().", "Un nom de type est utilisé là où une valeur est attendue. Souvent, typename manque dans « typename T::type » d'un template, ou des () manquent.", "Имя типа стоит там, где нужно значение. Часто забыт typename в «typename T::type» внутри шаблона или забыты ()." },
            ["オブジェクト ファイルが大きすぎます (/bigobj)"] = new[] { "Object file too large (/bigobj)", "目标文件过大（/bigobj）", "오브젝트 파일이 너무 큽니다(/bigobj)", "Archivo objeto demasiado grande (/bigobj)", "Arquivo objeto grande demais (/bigobj)", "Objektdatei zu groß (/bigobj)", "Fichier objet trop volumineux (/bigobj)", "Объектный файл слишком велик (/bigobj)" },
            ["1 つの cpp のセクションが多すぎます(テンプレートを大量に使うとき)。C/C++ > コマンド ライン に /bigobj を足します。"] = new[] { "One cpp has too many sections (when using many templates). Add /bigobj to C/C++ > Command Line.", "一个 cpp 的节太多（大量使用模板时）。在“C/C++ > 命令行”中添加 /bigobj。", "cpp 하나의 섹션이 너무 많습니다(템플릿을 대량으로 쓸 때). C/C++ > 명령줄에 /bigobj를 추가합니다.", "Un cpp tiene demasiadas secciones (con muchas plantillas). Añada /bigobj en C/C++ > Línea de comandos.", "Um cpp tem seções demais (com muitos templates). Adicione /bigobj em C/C++ > Linha de comando.", "Eine cpp hat zu viele Abschnitte (bei vielen Templates). /bigobj unter C/C++ > Befehlszeile hinzufügen.", "Un cpp a trop de sections (avec beaucoup de templates). Ajoutez /bigobj dans C/C++ > Ligne de commande.", "В одном cpp слишком много секций (при обилии шаблонов). Добавьте /bigobj в «C/C++ > Командная строка»." },
            ["PDB を開けません (並列ビルドの競合)"] = new[] { "Cannot open PDB (parallel build conflict)", "无法打开 PDB（并行生成冲突）", "PDB를 열 수 없습니다(병렬 빌드 충돌)", "No se puede abrir el PDB (conflicto de compilación paralela)", "Não é possível abrir o PDB (conflito de compilação paralela)", "PDB kann nicht geöffnet werden (Konflikt beim parallelen Build)", "Impossible d'ouvrir le PDB (conflit de génération parallèle)", "Не удаётся открыть PDB (конфликт параллельной сборки)" },
            ["複数の cl.exe が、同じ .pdb に書こうとしています。C/C++ > コマンド ライン に /FS を足します。"] = new[] { "Several cl.exe processes try to write the same .pdb. Add /FS to C/C++ > Command Line.", "多个 cl.exe 试图写同一个 .pdb。在“C/C++ > 命令行”中添加 /FS。", "여러 cl.exe가 같은 .pdb에 쓰려 하고 있습니다. C/C++ > 명령줄에 /FS를 추가합니다.", "Varios cl.exe intentan escribir el mismo .pdb. Añada /FS en C/C++ > Línea de comandos.", "Vários cl.exe tentam escrever o mesmo .pdb. Adicione /FS em C/C++ > Linha de comando.", "Mehrere cl.exe wollen dieselbe .pdb schreiben. /FS unter C/C++ > Befehlszeile hinzufügen.", "Plusieurs cl.exe tentent d'écrire le même .pdb. Ajoutez /FS dans C/C++ > Ligne de commande.", "Несколько cl.exe пишут в один .pdb. Добавьте /FS в «C/C++ > Командная строка»." },
            ["PDB を更新できません"] = new[] { "Cannot update PDB", "无法更新 PDB", "PDB를 업데이트할 수 없습니다", "No se puede actualizar el PDB", "Não é possível atualizar o PDB", "PDB kann nicht aktualisiert werden", "Impossible de mettre à jour le PDB", "Не удаётся обновить PDB" },
            ["並列ビルドや、ウイルス対策ソフトとの競合が多いです。/FS を足すか、リビルドします。"] = new[] { "Often a conflict with parallel builds or antivirus software. Add /FS or rebuild.", "多为并行生成或与杀毒软件冲突。添加 /FS，或重新生成。", "병렬 빌드나 백신 소프트웨어와의 충돌이 많습니다. /FS를 추가하거나 다시 빌드합니다.", "Suele ser conflicto con compilación paralela o antivirus. Añada /FS o recompile.", "Costuma ser conflito com compilação paralela ou antivírus. Adicione /FS ou recompile.", "Oft Konflikt mit parallelem Build oder Virenscanner. /FS hinzufügen oder neu erstellen.", "Souvent un conflit avec la génération parallèle ou l'antivirus. Ajoutez /FS ou régénérez.", "Обычно конфликт параллельной сборки или антивируса. Добавьте /FS или пересоберите." },
            ["include が深すぎます (循環 include)"] = new[] { "include nested too deeply (circular include)", "include 嵌套过深（循环 include）", "include가 너무 깊습니다(순환 include)", "include anidado demasiado (include circular)", "include aninhado demais (include circular)", "include zu tief verschachtelt (zirkuläres include)", "include trop imbriqué (include circulaire)", "Слишком глубокая вложенность include (циклический include)" },
            ["ヘッダーが、間接的に自分自身を include し続けています。#pragma once を付け、前方宣言で循環を断ちます。"] = new[] { "A header keeps including itself indirectly. Add #pragma once and break the cycle with forward declarations.", "头文件间接地不断 include 自身。加上 #pragma once，并用前向声明打断循环。", "헤더가 간접적으로 자기 자신을 계속 include하고 있습니다. #pragma once를 붙이고 전방 선언으로 순환을 끊습니다.", "Un encabezado se incluye a sí mismo indirectamente. Añada #pragma once y rompa el ciclo con declaraciones adelantadas.", "Um cabeçalho se inclui indiretamente sem parar. Adicione #pragma once e quebre o ciclo com declarações antecipadas.", "Ein Header bindet sich indirekt immer wieder selbst ein. #pragma once setzen und den Kreis mit Vorwärtsdeklarationen brechen.", "Un en-tête s'inclut lui-même indirectement en boucle. Ajoutez #pragma once et cassez le cycle par des déclarations anticipées.", "Заголовок косвенно подключает сам себя. Добавьте #pragma once и разорвите цикл предварительными объявлениями." },
            ["#if と #endif の対応が合っていません"] = new[] { "#if and #endif do not match", "#if 与 #endif 不对应", "#if와 #endif의 짝이 맞지 않습니다", "#if y #endif no coinciden", "#if e #endif não batem", "#if und #endif passen nicht zusammen", "#if et #endif ne correspondent pas", "#if и #endif не парны" },
            ["#if / #ifdef に対応する #endif が足りない(または多い)ファイルです。"] = new[] { "A file where #endif for #if / #ifdef is missing (or extra).", "这个文件中与 #if / #ifdef 对应的 #endif 不足（或过多）。", "#if / #ifdef에 대응하는 #endif가 부족한(또는 많은) 파일입니다.", "Archivo al que le falta (o sobra) un #endif para #if / #ifdef.", "Arquivo em que falta (ou sobra) #endif para #if / #ifdef.", "Datei, in der ein #endif zu #if / #ifdef fehlt (oder zu viel ist).", "Fichier où il manque (ou il y a en trop) un #endif pour #if / #ifdef.", "В файле не хватает (или лишний) #endif для #if / #ifdef." },
            ["コメントが閉じていません"] = new[] { "Comment not closed", "注释没有闭合", "주석이 닫히지 않았습니다", "Comentario sin cerrar", "Comentário não fechado", "Kommentar nicht geschlossen", "Commentaire non fermé", "Комментарий не закрыт" },
            ["「/*」に対応する「*/」がありません。"] = new[] { "There is no \"*/\" matching \"/*\".", "没有与“/*”对应的“*/”。", "\"/*\"에 대응하는 \"*/\"가 없습니다.", "No hay \"*/\" que cierre \"/*\".", "Não há \"*/\" fechando \"/*\".", "Zu \"/*\" fehlt das \"*/\".", "Il n'y a pas de « */ » correspondant à « /* ».", "Нет «*/» для «/*»." },
            ["コンパイラのメモリが足りません"] = new[] { "Compiler out of memory", "编译器内存不足", "컴파일러 메모리가 부족합니다", "El compilador se quedó sin memoria", "O compilador ficou sem memória", "Compiler hat zu wenig Speicher", "Mémoire insuffisante pour le compilateur", "Компилятору не хватает памяти" },
            ["64 ビット版のコンパイラ(x64 ホストのツール)を使うか、ファイルを分けます。"] = new[] { "Use the 64-bit compiler (x64-hosted tools), or split the file.", "使用 64 位编译器（x64 主机的工具），或拆分文件。", "64비트 컴파일러(x64 호스트 도구)를 쓰거나 파일을 나눕니다.", "Use el compilador de 64 bits (herramientas con host x64) o divida el archivo.", "Use o compilador de 64 bits (ferramentas com host x64) ou divida o arquivo.", "64-Bit-Compiler (x64-gehostete Tools) verwenden oder die Datei aufteilen.", "Utilisez le compilateur 64 bits (outils hébergés x64) ou scindez le fichier.", "Используйте 64-битный компилятор (инструменты для хоста x64) или разделите файл." },
            ["コンパイラの内部ヒープの上限です"] = new[] { "Compiler internal heap limit reached", "达到编译器内部堆的上限", "컴파일러 내부 힙의 상한입니다", "Se alcanzó el límite del montón interno del compilador", "Limite do heap interno do compilador atingido", "Interne Heap-Grenze des Compilers erreicht", "Limite du tas interne du compilateur atteinte", "Достигнут предел внутренней кучи компилятора" },
            ["C/C++ > コマンド ライン に /Zm を足して上限を上げるか、テンプレートの深い入れ子を減らします。"] = new[] { "Add /Zm to C/C++ > Command Line to raise the limit, or reduce deep template nesting.", "在“C/C++ > 命令行”中添加 /Zm 提高上限，或减少模板的深层嵌套。", "C/C++ > 명령줄에 /Zm을 추가해 상한을 올리거나 템플릿의 깊은 중첩을 줄입니다.", "Añada /Zm en C/C++ > Línea de comandos para subir el límite o reduzca el anidamiento profundo de plantillas.", "Adicione /Zm em C/C++ > Linha de comando para elevar o limite ou reduza o aninhamento profundo de templates.", "/Zm unter C/C++ > Befehlszeile hinzufügen, um die Grenze zu erhöhen, oder tiefe Template-Verschachtelung verringern.", "Ajoutez /Zm dans C/C++ > Ligne de commande pour relever la limite, ou réduisez l'imbrication profonde des templates.", "Добавьте /Zm в «C/C++ > Командная строка», чтобы поднять предел, или уменьшите глубину вложенности шаблонов." },
            ["コンパイラの内部エラー"] = new[] { "Compiler internal error", "编译器内部错误", "컴파일러 내부 오류", "Error interno del compilador", "Erro interno do compilador", "Interner Compilerfehler", "Erreur interne du compilateur", "Внутренняя ошибка компилятора" },
            ["コンパイラの不具合です。メッセージにあるファイルと行の付近の、新しい書き方(テンプレートなど)を単純にして、再ビルドします。Visual Studio の更新で直ることもあります。"] = new[] { "This is a compiler bug. Simplify any newer constructs (templates, etc.) near the file and line in the message, then rebuild. Updating Visual Studio may also fix it.", "这是编译器的缺陷。把消息中文件和行附近的新写法（模板等）简化后重新生成。更新 Visual Studio 有时也能解决。", "컴파일러의 결함입니다. 메시지에 있는 파일과 줄 근처의 새로운 작성법(템플릿 등)을 단순하게 하고 다시 빌드합니다. Visual Studio 업데이트로 고쳐지기도 합니다.", "Es un fallo del compilador. Simplifique las construcciones nuevas (plantillas, etc.) cerca del archivo y línea del mensaje y recompile. Actualizar Visual Studio también puede arreglarlo.", "É um bug do compilador. Simplifique construções novas (templates etc.) perto do arquivo e linha da mensagem e recompile. Atualizar o Visual Studio também pode resolver.", "Ein Compilerfehler. Neuere Konstrukte (Templates usw.) nahe Datei und Zeile aus der Meldung vereinfachen und neu erstellen. Ein Visual-Studio-Update kann auch helfen.", "C'est un bogue du compilateur. Simplifiez les constructions récentes (templates, etc.) près du fichier et de la ligne du message, puis régénérez. Une mise à jour de Visual Studio peut aussi corriger.", "Это ошибка компилятора. Упростите новые конструкции (шаблоны и т. п.) рядом с файлом и строкой из сообщения и пересоберите. Может помочь и обновление Visual Studio." },
            ["宣言が、前のローカル宣言を隠しています"] = new[] { "Declaration hides a previous local declaration", "声明隐藏了之前的局部声明", "선언이 앞의 지역 선언을 가리고 있습니다", "La declaración oculta una declaración local anterior", "A declaração oculta uma declaração local anterior", "Deklaration verdeckt eine vorige lokale Deklaration", "La déclaration masque une déclaration locale précédente", "Объявление скрывает предыдущее локальное" },
            ["同じ名前の変数を、内側のスコープで宣言しています。名前を変えるか、内側の宣言をやめます。"] = new[] { "A variable with the same name is declared in an inner scope. Rename it, or drop the inner declaration.", "在内层作用域中声明了同名变量。改名，或去掉内层的声明。", "같은 이름의 변수를 안쪽 스코프에서 선언하고 있습니다. 이름을 바꾸거나 안쪽 선언을 그만둡니다.", "Se declara una variable con el mismo nombre en un ámbito interior. Renómbrela o quite la declaración interior.", "Uma variável com o mesmo nome é declarada num escopo interno. Renomeie ou remova a declaração interna.", "Eine gleichnamige Variable wird in einem inneren Bereich deklariert. Umbenennen oder die innere Deklaration entfernen.", "Une variable du même nom est déclarée dans une portée interne. Renommez-la ou supprimez la déclaration interne.", "Во внутренней области объявлена переменная с тем же именем. Переименуйте её или уберите внутреннее объявление." },
            ["宣言が、関数の引数を隠しています"] = new[] { "Declaration hides a function parameter", "声明隐藏了函数参数", "선언이 함수 인수를 가리고 있습니다", "La declaración oculta un parámetro de la función", "A declaração oculta um parâmetro da função", "Deklaration verdeckt einen Funktionsparameter", "La déclaration masque un paramètre de la fonction", "Объявление скрывает параметр функции" },
            ["引数と同じ名前の変数を宣言しています。名前を変えます。"] = new[] { "A variable with the same name as a parameter is declared. Rename it.", "声明了与参数同名的变量。请改名。", "인수와 같은 이름의 변수를 선언하고 있습니다. 이름을 바꿉니다.", "Se declara una variable con el nombre de un parámetro. Renómbrela.", "Uma variável com o nome de um parâmetro é declarada. Renomeie.", "Eine Variable mit Parameternamen wird deklariert. Umbenennen.", "Une variable du même nom qu'un paramètre est déclarée. Renommez-la.", "Объявлена переменная с именем параметра. Переименуйте её." },
            ["宣言が、グローバルな宣言を隠しています"] = new[] { "Declaration hides a global declaration", "声明隐藏了全局声明", "선언이 전역 선언을 가리고 있습니다", "La declaración oculta una declaración global", "A declaração oculta uma declaração global", "Deklaration verdeckt eine globale Deklaration", "La déclaration masque une déclaration globale", "Объявление скрывает глобальное" },
            ["グローバルと同じ名前の変数を宣言しています。名前を変えます。"] = new[] { "A variable with the same name as a global is declared. Rename it.", "声明了与全局同名的变量。请改名。", "전역과 같은 이름의 변수를 선언하고 있습니다. 이름을 바꿉니다.", "Se declara una variable con el nombre de una global. Renómbrela.", "Uma variável com o nome de uma global é declarada. Renomeie.", "Eine Variable mit dem Namen einer globalen wird deklariert. Umbenennen.", "Une variable du même nom qu'une globale est déclarée. Renommez-la.", "Объявлена переменная с именем глобальной. Переименуйте её." },
            ["条件式が定数です"] = new[] { "Conditional expression is constant", "条件表达式是常量", "조건식이 상수입니다", "La expresión condicional es constante", "A expressão condicional é constante", "Bedingungsausdruck ist konstant", "L'expression conditionnelle est constante", "Условное выражение константно" },
            ["if (1) や while (true) のように、条件が定数です。意図があれば無視できます。コンパイル時の分岐なら、if constexpr (C++17) を使います。"] = new[] { "The condition is a constant, like if (1) or while (true). If intended, you can ignore it. For a compile-time branch, use if constexpr (C++17).", "条件是常量，如 if (1) 或 while (true)。若有意为之可以忽略。若是编译时分支，用 if constexpr（C++17）。", "if (1)이나 while (true)처럼 조건이 상수입니다. 의도가 있다면 무시할 수 있습니다. 컴파일 시 분기라면 if constexpr(C++17)를 씁니다.", "La condición es constante, como if (1) o while (true). Si es intencionado, ignórelo. Para una rama en compilación, use if constexpr (C++17).", "A condição é constante, como if (1) ou while (true). Se for intencional, ignore. Para ramificação em compilação, use if constexpr (C++17).", "Die Bedingung ist konstant, etwa if (1) oder while (true). Wenn gewollt, ignorieren. Für Verzweigung zur Kompilierzeit if constexpr (C++17) nutzen.", "La condition est constante, comme if (1) ou while (true). Si c'est voulu, ignorez. Pour un branchement à la compilation, utilisez if constexpr (C++17).", "Условие константно, как if (1) или while (true). Если так задумано, можно игнорировать. Для ветвления при компиляции используйте if constexpr (C++17)." },
            ["非標準の拡張機能: 無名の構造体 / 共用体"] = new[] { "Nonstandard extension: nameless struct / union", "非标准扩展：无名结构体 / 联合体", "비표준 확장: 이름 없는 구조체 / 공용체", "Extensión no estándar: struct / union sin nombre", "Extensão não padrão: struct / union sem nome", "Nicht standardmäßige Erweiterung: namenlose struct / union", "Extension non standard : struct / union sans nom", "Нестандартное расширение: безымянная struct / union" },
            ["標準の C++ にはない書き方です。DirectXMath のような、数学ライブラリのヘッダーで出ます。意図があれば、#pragma warning(disable:4201) で止めます。"] = new[] { "This is not standard C++. It appears in math library headers like DirectXMath. If intended, silence it with #pragma warning(disable:4201).", "这是标准 C++ 中没有的写法。在 DirectXMath 这样的数学库头文件中会出现。若有意为之，用 #pragma warning(disable:4201) 关闭。", "표준 C++에는 없는 작성법입니다. DirectXMath 같은 수학 라이브러리 헤더에서 나옵니다. 의도가 있다면 #pragma warning(disable:4201)로 끕니다.", "No es C++ estándar. Aparece en encabezados de bibliotecas matemáticas como DirectXMath. Si es intencionado, silencie con #pragma warning(disable:4201).", "Não é C++ padrão. Aparece em cabeçalhos de bibliotecas matemáticas como DirectXMath. Se for intencional, silencie com #pragma warning(disable:4201).", "Kein Standard-C++. Tritt in Headern von Mathebibliotheken wie DirectXMath auf. Wenn gewollt, mit #pragma warning(disable:4201) abschalten.", "Ce n'est pas du C++ standard. Cela apparaît dans les en-têtes de bibliothèques mathématiques comme DirectXMath. Si c'est voulu, désactivez avec #pragma warning(disable:4201).", "Это не стандартный C++. Встречается в заголовках математических библиотек вроде DirectXMath. Если так задумано, отключите через #pragma warning(disable:4201)." },
            ["アラインメントのために、構造体にパディングが入りました"] = new[] { "Padding was added to a struct for alignment", "为了对齐，结构体中加入了填充", "정렬 때문에 구조체에 패딩이 들어갔습니다", "Se añadió relleno a una estructura por alineación", "Preenchimento foi adicionado a uma estrutura por alinhamento", "Struktur wurde wegen Ausrichtung aufgefüllt", "Du remplissage a été ajouté à une structure pour l'alignement", "В структуру добавлено выравнивание" },
            ["alignas や XMVECTOR のメンバーで、構造体の大きさが増えました。意図どおりなら無視できます。"] = new[] { "alignas or an XMVECTOR member increased the struct's size. If that is intended, you can ignore it.", "alignas 或 XMVECTOR 成员使结构体变大了。若符合预期可以忽略。", "alignas나 XMVECTOR 멤버로 구조체 크기가 늘었습니다. 의도대로라면 무시할 수 있습니다.", "alignas o un miembro XMVECTOR aumentó el tamaño de la estructura. Si es lo previsto, ignórelo.", "alignas ou um membro XMVECTOR aumentou o tamanho da estrutura. Se for o previsto, ignore.", "alignas oder ein XMVECTOR-Member hat die Strukturgröße erhöht. Wenn gewollt, ignorieren.", "alignas ou un membre XMVECTOR a augmenté la taille de la structure. Si c'est voulu, ignorez.", "alignas или член XMVECTOR увеличил размер структуры. Если так и нужно, можно игнорировать." },
            ["符号付きと符号なしを、== で比べています"] = new[] { "Comparing signed and unsigned with ==", "用 == 比较有符号与无符号", "부호 있는 값과 없는 값을 ==로 비교하고 있습니다", "Se comparan con signo y sin signo con ==", "Comparando com sinal e sem sinal com ==", "signed und unsigned werden mit == verglichen", "Comparaison signé / non signé avec ==", "Сравнение знакового и беззнакового через ==" },
            ["型をそろえます。負の値が大きな値になって、比較が思わぬ結果になります。"] = new[] { "Make the types match. Negative values become large values and the comparison gives surprising results.", "统一类型。负值会变成很大的值，比较会得到意外的结果。", "타입을 맞춥니다. 음수가 큰 값이 되어 비교가 뜻밖의 결과가 됩니다.", "Iguale los tipos. Los negativos se vuelven grandes y la comparación da resultados inesperados.", "Iguale os tipos. Negativos viram valores grandes e a comparação dá resultados inesperados.", "Typen angleichen. Negative Werte werden groß, der Vergleich liefert Überraschungen.", "Harmonisez les types. Les négatifs deviennent de grandes valeurs et la comparaison surprend.", "Выровняйте типы. Отрицательные значения становятся большими, и сравнение даёт неожиданный результат." },
            ["文字コードを表せない文字があります"] = new[] { "There are characters the code page cannot represent", "有无法用字符编码表示的字符", "문자 코드로 표현할 수 없는 문자가 있습니다", "Hay caracteres que la página de códigos no puede representar", "Há caracteres que a página de código não representa", "Es gibt Zeichen, die die Codepage nicht darstellen kann", "Des caractères ne sont pas représentables dans la page de codes", "Есть символы, которые нельзя представить в кодировке" },
            ["ソースを UTF-8 (BOM 付き)で保存し直すか、/utf-8 を付けます(C4819 と同じ原因です)。"] = new[] { "Resave the source as UTF-8 (with BOM), or add /utf-8 (same cause as C4819).", "把源文件重新保存为 UTF-8（带 BOM），或加上 /utf-8（与 C4819 原因相同）。", "소스를 UTF-8(BOM 포함)로 다시 저장하거나 /utf-8을 붙입니다(C4819와 같은 원인입니다).", "Vuelva a guardar el código en UTF-8 (con BOM) o añada /utf-8 (misma causa que C4819).", "Salve o código de novo em UTF-8 (com BOM) ou adicione /utf-8 (mesma causa do C4819).", "Quelldatei erneut als UTF-8 (mit BOM) speichern oder /utf-8 hinzufügen (gleiche Ursache wie C4819).", "Réenregistrez le source en UTF-8 (avec BOM) ou ajoutez /utf-8 (même cause que C4819).", "Пересохраните исходник в UTF-8 (с BOM) или добавьте /utf-8 (та же причина, что у C4819)." },
            ["DLL の宣言が、宣言と定義で食い違っています"] = new[] { "DLL linkage differs between declaration and definition", "DLL 的声明在声明与定义之间不一致", "DLL 선언이 선언과 정의에서 어긋나 있습니다", "La vinculación DLL difiere entre declaración y definición", "A vinculação DLL difere entre declaração e definição", "DLL-Bindung weicht zwischen Deklaration und Definition ab", "La liaison DLL diffère entre déclaration et définition", "Связывание DLL различается в объявлении и определении" },
            ["dllimport / dllexport が、宣言と定義で違います。DLL 側と利用側で、API マクロの切り替えが合っているか確かめます。"] = new[] { "dllimport / dllexport differs between declaration and definition. Check that the API macro switches correctly on the DLL side and the consumer side.", "dllimport / dllexport 在声明与定义中不同。确认 DLL 端与使用端的 API 宏切换是否正确。", "dllimport / dllexport가 선언과 정의에서 다릅니다. DLL 쪽과 사용하는 쪽에서 API 매크로 전환이 맞는지 확인합니다.", "dllimport / dllexport difiere entre declaración y definición. Compruebe que la macro de API cambia bien en la DLL y en quien la usa.", "dllimport / dllexport difere entre declaração e definição. Verifique se a macro de API alterna corretamente na DLL e em quem a usa.", "dllimport / dllexport unterscheidet sich zwischen Deklaration und Definition. Prüfen, ob das API-Makro auf DLL- und Nutzerseite richtig umschaltet.", "dllimport / dllexport diffère entre déclaration et définition. Vérifiez que la macro d'API bascule correctement côté DLL et côté utilisateur.", "dllimport / dllexport различается в объявлении и определении. Проверьте, что макрос API правильно переключается на стороне DLL и у пользователя." },
            ["PDB が見つかりません"] = new[] { "PDB not found", "找不到 PDB", "PDB를 찾을 수 없습니다", "No se encuentra el PDB", "PDB não encontrado", "PDB nicht gefunden", "PDB introuvable", "PDB не найден" },
            ["ライブラリを作ったときの .pdb が、.lib のそばにありません。警告のままでも動きます。デバッグ情報が要るなら、.pdb も一緒に置きます。"] = new[] { "The .pdb from when the library was built is not next to the .lib. It still works as a warning. If you need debug info, put the .pdb alongside it.", "生成库时的 .pdb 不在 .lib 旁边。保持警告也能运行。需要调试信息的话，把 .pdb 也放在一起。", "라이브러리를 만들 때의 .pdb가 .lib 옆에 없습니다. 경고인 채로도 동작합니다. 디버그 정보가 필요하다면 .pdb도 함께 둡니다.", "El .pdb de la compilación de la biblioteca no está junto al .lib. Funciona igual con el aviso. Si necesita depurar, ponga el .pdb al lado.", "O .pdb da compilação da biblioteca não está junto ao .lib. Funciona mesmo com o aviso. Se precisar depurar, coloque o .pdb junto.", "Die .pdb vom Erstellen der Bibliothek liegt nicht neben der .lib. Funktioniert trotz Warnung. Für Debuginfos die .pdb danebenlegen.", "Le .pdb de la génération de la bibliothèque n'est pas à côté du .lib. Cela fonctionne malgré l'avertissement. Pour le débogage, placez le .pdb à côté.", "Рядом с .lib нет .pdb от сборки библиотеки. Работает и с предупреждением. Если нужна отладочная информация, положите .pdb рядом." },
            ["インポートする予定のシンボルが、同じモジュールで定義されています"] = new[] { "A symbol meant to be imported is defined in the same module", "预定导入的符号在同一模块中定义", "가져올 예정인 심볼이 같은 모듈에 정의되어 있습니다", "Un símbolo que se iba a importar está definido en el mismo módulo", "Um símbolo que seria importado está definido no mesmo módulo", "Ein zu importierendes Symbol ist im selben Modul definiert", "Un symbole destiné à l'import est défini dans le même module", "Символ, предназначенный для импорта, определён в том же модуле" },
            ["dllimport で参照しているものが、同じ DLL(exe)の中で定義されています。dllimport と dllexport の、マクロの切り替えを確かめます。"] = new[] { "Something referenced via dllimport is defined in the same DLL (exe). Check how the macro switches between dllimport and dllexport.", "通过 dllimport 引用的东西在同一 DLL（exe）中定义。检查 dllimport 与 dllexport 的宏切换。", "dllimport로 참조하는 것이 같은 DLL(exe) 안에 정의되어 있습니다. dllimport와 dllexport의 매크로 전환을 확인합니다.", "Algo referenciado con dllimport está definido en la misma DLL (exe). Revise cómo la macro alterna entre dllimport y dllexport.", "Algo referenciado via dllimport está definido na mesma DLL (exe). Verifique como a macro alterna entre dllimport e dllexport.", "Etwas per dllimport Referenziertes ist in derselben DLL (exe) definiert. Umschaltung des Makros zwischen dllimport und dllexport prüfen.", "Un élément référencé via dllimport est défini dans la même DLL (exe). Vérifiez la bascule de la macro entre dllimport et dllexport.", "То, что используется через dllimport, определено в той же DLL (exe). Проверьте переключение макроса между dllimport и dllexport." },
            ["ファイルをコピーできません"] = new[] { "Cannot copy file", "无法复制文件", "파일을 복사할 수 없습니다", "No se puede copiar el archivo", "Não é possível copiar o arquivo", "Datei kann nicht kopiert werden", "Impossible de copier le fichier", "Не удаётся скопировать файл" },
            ["コピー先のファイル(exe など)が、実行中か、ほかのプロセスに使われています。アプリを終了して、ビルドし直します。"] = new[] { "The destination file (exe, etc.) is running or used by another process. Close the app and build again.", "复制目标文件（exe 等）正在运行，或被其他进程使用。关闭应用后重新生成。", "복사할 대상 파일(exe 등)이 실행 중이거나 다른 프로세스가 쓰고 있습니다. 앱을 종료하고 다시 빌드합니다.", "El archivo de destino (exe, etc.) está en ejecución o lo usa otro proceso. Cierre la aplicación y vuelva a compilar.", "O arquivo de destino (exe etc.) está em execução ou em uso por outro processo. Feche o app e compile de novo.", "Die Zieldatei (exe usw.) läuft oder wird von einem anderen Prozess genutzt. App beenden und neu erstellen.", "Le fichier de destination (exe, etc.) est en cours d'exécution ou utilisé par un autre processus. Fermez l'application et relancez la génération.", "Целевой файл (exe и т. п.) запущен или занят другим процессом. Закройте приложение и соберите снова." },
            ["ファイルのコピーを再試行しています"] = new[] { "Retrying file copy", "正在重试复制文件", "파일 복사를 재시도하고 있습니다", "Reintentando la copia del archivo", "Tentando copiar o arquivo de novo", "Dateikopie wird wiederholt", "Nouvelle tentative de copie du fichier", "Повторная попытка копирования файла" },
            ["コピー先が、ほかのプロセスに使われています。アプリを終了します。"] = new[] { "The destination is used by another process. Close the app.", "复制目标被其他进程使用。请关闭应用。", "복사 대상을 다른 프로세스가 쓰고 있습니다. 앱을 종료합니다.", "El destino lo usa otro proceso. Cierre la aplicación.", "O destino está em uso por outro processo. Feche o app.", "Das Ziel wird von einem anderen Prozess genutzt. App beenden.", "La destination est utilisée par un autre processus. Fermez l'application.", "Цель занята другим процессом. Закройте приложение." },
            ["ファイルをコピーできませんでした"] = new[] { "Could not copy file", "未能复制文件", "파일을 복사하지 못했습니다", "No se pudo copiar el archivo", "Não foi possível copiar o arquivo", "Datei konnte nicht kopiert werden", "La copie du fichier a échoué", "Не удалось скопировать файл" },
            ["コピー先が、ほかのプロセスに使われています。アプリを終了して、ビルドし直します。"] = new[] { "The destination is used by another process. Close the app and build again.", "复制目标被其他进程使用。关闭应用后重新生成。", "복사 대상을 다른 프로세스가 쓰고 있습니다. 앱을 종료하고 다시 빌드합니다.", "El destino lo usa otro proceso. Cierre la aplicación y vuelva a compilar.", "O destino está em uso por outro processo. Feche o app e compile de novo.", "Das Ziel wird von einem anderen Prozess genutzt. App beenden und neu erstellen.", "La destination est utilisée par un autre processus. Fermez l'application et relancez la génération.", "Цель занята другим процессом. Закройте приложение и соберите снова." },
            ["構成とプラットフォームの組み合わせがありません"] = new[] { "No such configuration / platform combination", "没有该配置与平台的组合", "구성과 플랫폼의 조합이 없습니다", "No existe esa combinación de configuración y plataforma", "Não existe essa combinação de configuração e plataforma", "Diese Kombination aus Konfiguration und Plattform fehlt", "Combinaison configuration / plateforme inexistante", "Нет такого сочетания конфигурации и платформы" },
            ["ソリューションの構成(Debug|x64 など)に、そのプロジェクトの構成がありません。構成マネージャーで、プラットフォームをそろえます。"] = new[] { "The solution configuration (Debug|x64, etc.) has no configuration for that project. Align the platforms in Configuration Manager.", "解决方案的配置（Debug|x64 等）中没有该项目的配置。在配置管理器中统一平台。", "솔루션 구성(Debug|x64 등)에 그 프로젝트의 구성이 없습니다. 구성 관리자에서 플랫폼을 맞춥니다.", "La configuración de la solución (Debug|x64, etc.) no tiene configuración para ese proyecto. Iguale las plataformas en el Administrador de configuración.", "A configuração da solução (Debug|x64 etc.) não tem configuração para esse projeto. Iguale as plataformas no Gerenciador de configurações.", "Die Projektmappenkonfiguration (Debug|x64 usw.) hat keine Konfiguration für dieses Projekt. Plattformen im Konfigurations-Manager angleichen.", "La configuration de la solution (Debug|x64, etc.) n'a pas de configuration pour ce projet. Harmonisez les plateformes dans le Gestionnaire de configurations.", "В конфигурации решения (Debug|x64 и т. п.) нет конфигурации этого проекта. Выровняйте платформы в диспетчере конфигураций." },
            ["「{0}」が、この場所から見えていません。まず綴りを確かめます。次に、{1} を宣言しているヘッダーの #include(カーソルを名前に置いて Alt+F)と、std の名前なら std:: を確かめます。"] = new[] { "\"{0}\" is not visible from here. First check the spelling. Next, check the #include of the header that declares {1} (put the cursor on the name and press Alt+F), and std:: for std names.", "“{0}”在此处不可见。先检查拼写。然后检查声明 {1} 的头文件的 #include（光标放在名称上按 Alt+F），如果是 std 的名称，检查 std::。", "\"{0}\"이(가) 이 위치에서 보이지 않습니다. 먼저 철자를 확인합니다. 다음으로 {1}을(를) 선언한 헤더의 #include(커서를 이름에 두고 Alt+F)와, std의 이름이라면 std::를 확인합니다.", "\"{0}\" no es visible desde aquí. Primero revise la ortografía. Luego, el #include del encabezado que declara {1} (cursor en el nombre y Alt+F) y, si es de std, el std::.", "\"{0}\" não é visível daqui. Primeiro verifique a grafia. Depois, o #include do cabeçalho que declara {1} (cursor no nome e Alt+F) e, se for de std, o std::.", "\"{0}\" ist von hier nicht sichtbar. Zuerst die Schreibweise prüfen. Dann das #include des Headers, der {1} deklariert (Cursor auf den Namen, Alt+F), und bei std-Namen das std::.", "« {0} » n'est pas visible ici. Vérifiez d'abord l'orthographe. Puis l'#include de l'en-tête qui déclare {1} (curseur sur le nom puis Alt+F) et, pour un nom std, le std::.", "«{0}» отсюда не видно. Сначала проверьте написание. Затем #include заголовка, где объявлен {1} (курсор на имя и Alt+F), а для имён std — префикс std::." },
            ["「{0}」に、「{1}」という名前はありません。まず綴りを確かめます(vector を vectr と書く、など)。綴りが合っているなら、その名前を宣言している標準ヘッダーの #include が足りません。"] = new[] { "\"{0}\" has no name \"{1}\". First check the spelling (e.g. vector written as vectr). If the spelling is right, the #include of the standard header that declares it is missing.", "“{0}”中没有名为“{1}”的名称。先检查拼写（如把 vector 写成 vectr）。拼写正确的话，就是缺少声明它的标准头文件的 #include。", "\"{0}\"에 \"{1}\"이라는 이름이 없습니다. 먼저 철자를 확인합니다(vector를 vectr로 쓰는 등). 철자가 맞다면 그 이름을 선언한 표준 헤더의 #include가 부족합니다.", "\"{0}\" no tiene el nombre \"{1}\". Primero revise la ortografía (p. ej. vector escrito vectr). Si es correcta, falta el #include del encabezado estándar que lo declara.", "\"{0}\" não tem o nome \"{1}\". Primeiro verifique a grafia (ex.: vector escrito vectr). Se estiver certa, falta o #include do cabeçalho padrão que o declara.", "\"{0}\" hat keinen Namen \"{1}\". Zuerst die Schreibweise prüfen (z. B. vector als vectr). Stimmt sie, fehlt das #include des Standardheaders, der ihn deklariert.", "« {0} » n'a pas de nom « {1} ». Vérifiez d'abord l'orthographe (ex. vector écrit vectr). Si elle est juste, il manque l'#include de l'en-tête standard qui le déclare.", "В «{0}» нет имени «{1}». Сначала проверьте написание (например, vectr вместо vector). Если оно верно, не хватает #include стандартного заголовка, где оно объявлено." },
            ["「{0}」に、「{1}」という名前のメンバーがありません。綴り、基底クラス、const の違い、クラスの宣言(ヘッダー)を確かめます。"] = new[] { "\"{0}\" has no member named \"{1}\". Check the spelling, base classes, const differences and the class declaration (header).", "“{0}”中没有名为“{1}”的成员。检查拼写、基类、const 的差异、类的声明（头文件）。", "\"{0}\"에 \"{1}\"이라는 이름의 멤버가 없습니다. 철자, 기본 클래스, const 차이, 클래스 선언(헤더)을 확인합니다.", "\"{0}\" no tiene un miembro llamado \"{1}\". Revise la ortografía, las clases base, diferencias de const y la declaración de la clase (encabezado).", "\"{0}\" não tem membro chamado \"{1}\". Verifique a grafia, classes base, diferenças de const e a declaração da classe (cabeçalho).", "\"{0}\" hat keinen Member namens \"{1}\". Schreibweise, Basisklassen, const-Unterschiede und Klassendeklaration (Header) prüfen.", "« {0} » n'a pas de membre nommé « {1} ». Vérifiez l'orthographe, les classes de base, les différences de const et la déclaration de la classe (en-tête).", "У «{0}» нет члена «{1}». Проверьте написание, базовые классы, различия const и объявление класса (заголовок)." },
            ["「{0}」は、private か protected で、この場所からは使えません。使う側を変えるか、クラスの公開範囲を変えます。"] = new[] { "\"{0}\" is private or protected and cannot be used from here. Change the caller, or change the class's access level.", "“{0}”是 private 或 protected，不能在此处使用。修改使用方，或修改类的访问级别。", "\"{0}\"은(는) private 또는 protected라서 이 위치에서는 쓸 수 없습니다. 쓰는 쪽을 바꾸거나 클래스의 공개 범위를 바꿉니다.", "\"{0}\" es private o protected y no se puede usar aquí. Cambie quien lo usa o el nivel de acceso de la clase.", "\"{0}\" é private ou protected e não pode ser usado daqui. Mude quem o usa ou o nível de acesso da classe.", "\"{0}\" ist private oder protected und hier nicht verwendbar. Aufrufer oder Sichtbarkeit der Klasse ändern.", "« {0} » est private ou protected et n'est pas utilisable ici. Modifiez l'appelant ou le niveau d'accès de la classe.", "«{0}» — private или protected, отсюда недоступен. Измените вызывающий код или уровень доступа класса." },
            ["「{0}」に、実装されていない純粋仮想関数があります。下の補足に、足りない関数が出ます。"] = new[] { "\"{0}\" has unimplemented pure virtual functions. The missing functions are shown in the notes below.", "“{0}”中有未实现的纯虚函数。缺少的函数显示在下方的补充中。", "\"{0}\"에 구현되지 않은 순수 가상 함수가 있습니다. 아래 보충에 부족한 함수가 나옵니다.", "\"{0}\" tiene funciones virtuales puras sin implementar. Las que faltan aparecen en las notas de abajo.", "\"{0}\" tem funções virtuais puras não implementadas. As que faltam aparecem nas notas abaixo.", "\"{0}\" hat nicht implementierte rein virtuelle Funktionen. Die fehlenden stehen in den Hinweisen unten.", "« {0} » a des fonctions virtuelles pures non implémentées. Celles qui manquent figurent dans les notes ci-dessous.", "В «{0}» есть нереализованные чисто виртуальные функции. Недостающие показаны в примечаниях ниже." },
            ["{0}「{1}」は、「{2}」になりません。{3}"] = new[] { "{0}\"{1}\" cannot become \"{2}\". {3}", "{0}“{1}”无法成为“{2}”。{3}", "{0}\"{1}\"은(는) \"{2}\"이(가) 될 수 없습니다. {3}", "{0}\"{1}\" no puede convertirse en \"{2}\". {3}", "{0}\"{1}\" não pode virar \"{2}\". {3}", "{0}\"{1}\" kann nicht zu \"{2}\" werden. {3}", "{0}« {1} » ne peut pas devenir « {2} ». {3}", "{0}«{1}» нельзя превратить в «{2}». {3}" },
            ["引数 {0} に渡した"] = new[] { "Passed to argument {0}: ", "传给参数 {0} 的", "인수 {0}에 넘긴 ", "Pasado al argumento {0}: ", "Passado ao argumento {0}: ", "An Argument {0} übergeben: ", "Passé à l'argument {0} : ", "Передано в аргумент {0}: " },
            ["「{0}」は、{1} 個の引数を受け取りません。宣言の引数の数(既定値つきの引数を含む)と、呼び出しの引数の数を数え直します。"] = new[] { "\"{0}\" does not take {1} arguments. Recount the parameters in the declaration (including those with defaults) and the arguments in the call.", "“{0}”不接受 {1} 个参数。重新数一下声明的参数个数（包括带默认值的参数）和调用的参数个数。", "\"{0}\"은(는) {1}개의 인수를 받지 않습니다. 선언의 인수 수(기본값이 있는 인수 포함)와 호출의 인수 수를 다시 셉니다.", "\"{0}\" no acepta {1} argumentos. Vuelva a contar los parámetros de la declaración (incluidos los predeterminados) y los argumentos de la llamada.", "\"{0}\" não aceita {1} argumentos. Reconte os parâmetros da declaração (incluindo os com padrão) e os argumentos da chamada.", "\"{0}\" nimmt keine {1} Argumente. Parameter der Deklaration (inkl. Standardwerten) und Argumente des Aufrufs neu zählen.", "« {0} » n'accepte pas {1} arguments. Recomptez les paramètres de la déclaration (y compris ceux par défaut) et les arguments de l'appel.", "«{0}» не принимает {1} аргументов. Пересчитайте параметры в объявлении (включая со значениями по умолчанию) и аргументы вызова." },
            ["「{0}」のテンプレート引数が決まりません。同じ型 T に、別の型(int と double など)を渡していないか確かめます。型を Name<double>(…) のように書いて決めるか、concept などの制約を満たす型を渡します。"] = new[] { "The template arguments of \"{0}\" cannot be determined. Check that you do not pass different types (int and double, etc.) for the same T. Fix the type by writing Name<double>(…), or pass a type that satisfies the constraints such as a concept.", "无法确定“{0}”的模板参数。确认没有给同一个 T 传入不同的类型（int 与 double 等）。像 Name<double>(…) 这样写出类型来确定，或传入满足 concept 等约束的类型。", "\"{0}\"의 템플릿 인수가 정해지지 않습니다. 같은 타입 T에 다른 타입(int와 double 등)을 넘기지 않았는지 확인합니다. Name<double>(…)처럼 타입을 써서 정하거나 concept 등의 제약을 만족하는 타입을 넘깁니다.", "No se pueden determinar los argumentos de plantilla de \"{0}\". Compruebe que no pasa tipos distintos (int y double, etc.) para el mismo T. Fije el tipo con Nombre<double>(…) o pase un tipo que cumpla las restricciones (concept, etc.).", "Não é possível determinar os argumentos de template de \"{0}\". Verifique se não passa tipos diferentes (int e double etc.) para o mesmo T. Fixe o tipo com Nome<double>(…) ou passe um tipo que atenda às restrições (concept etc.).", "Die Template-Argumente von \"{0}\" sind nicht bestimmbar. Prüfen, ob für dasselbe T verschiedene Typen (int und double usw.) übergeben werden. Typ mit Name<double>(…) festlegen oder einen Typ übergeben, der die Einschränkungen (concept usw.) erfüllt.", "Les arguments de template de « {0} » ne peuvent pas être déterminés. Vérifiez que vous ne passez pas des types différents (int et double, etc.) pour le même T. Fixez le type avec Nom<double>(…) ou passez un type satisfaisant les contraintes (concept, etc.).", "Не удаётся определить аргументы шаблона «{0}». Проверьте, не передаются ли разные типы (int и double и т. п.) для одного T. Задайте тип как Name<double>(…) или передайте тип, удовлетворяющий ограничениям (concept и т. п.)." },
            ["「{0}」は、引数なしでは作れません(既定コンストラクターがありません)。作る場所で引数を渡すか、クラスに {1}() = default; を足します。メンバーとして持つなら、初期化リストで引数を渡します。"] = new[] { "\"{0}\" cannot be created without arguments (there is no default constructor). Pass arguments where it is created, or add {1}() = default; to the class. If it is held as a member, pass arguments in the initializer list.", "“{0}”不能无参创建（没有默认构造函数）。在创建处传入参数，或给类加上 {1}() = default;。作为成员持有时，在初始化列表中传参数。", "\"{0}\"은(는) 인수 없이 만들 수 없습니다(기본 생성자가 없습니다). 만드는 위치에서 인수를 넘기거나 클래스에 {1}() = default;를 추가합니다. 멤버로 가진다면 초기화 목록에서 인수를 넘깁니다.", "\"{0}\" no se puede crear sin argumentos (no hay constructor predeterminado). Pase argumentos donde se crea o añada {1}() = default; a la clase. Si es un miembro, pase los argumentos en la lista de inicialización.", "\"{0}\" não pode ser criado sem argumentos (não há construtor padrão). Passe argumentos onde é criado ou adicione {1}() = default; à classe. Se for membro, passe os argumentos na lista de inicialização.", "\"{0}\" ist ohne Argumente nicht erzeugbar (kein Standardkonstruktor). Beim Erzeugen Argumente übergeben oder der Klasse {1}() = default; hinzufügen. Als Member die Argumente in der Initialisierungsliste übergeben.", "« {0} » ne peut pas être créé sans arguments (pas de constructeur par défaut). Passez des arguments à la création ou ajoutez {1}() = default; à la classe. Pour un membre, passez les arguments dans la liste d'initialisation.", "«{0}» нельзя создать без аргументов (нет конструктора по умолчанию). Передайте аргументы при создании или добавьте в класс {1}() = default;. Если это член, передайте аргументы в списке инициализации." },
            ["「{0}」は、delete されているので呼べません。コピーできない型(std::unique_ptr など)をコピーしていないか確かめます。std::move で渡すか、参照で受けます。"] = new[] { "\"{0}\" is deleted, so it cannot be called. Check that you are not copying a non-copyable type (std::unique_ptr, etc.). Pass with std::move, or take it by reference.", "“{0}”已被 delete，无法调用。确认没有复制不可复制的类型（std::unique_ptr 等）。用 std::move 传递，或按引用接收。", "\"{0}\"은(는) delete되어 있어 호출할 수 없습니다. 복사할 수 없는 타입(std::unique_ptr 등)을 복사하고 있지 않은지 확인합니다. std::move로 넘기거나 참조로 받습니다.", "\"{0}\" está eliminado (delete) y no se puede llamar. Compruebe que no copia un tipo no copiable (std::unique_ptr, etc.). Páselo con std::move o recíbalo por referencia.", "\"{0}\" está excluído (delete) e não pode ser chamado. Verifique se não copia um tipo não copiável (std::unique_ptr etc.). Passe com std::move ou receba por referência.", "\"{0}\" ist gelöscht (delete) und nicht aufrufbar. Prüfen, ob ein nicht kopierbarer Typ (std::unique_ptr usw.) kopiert wird. Mit std::move übergeben oder per Referenz annehmen.", "« {0} » est supprimé (delete) et ne peut pas être appelé. Vérifiez que vous ne copiez pas un type non copiable (std::unique_ptr, etc.). Passez-le avec std::move ou recevez-le par référence.", "«{0}» удалён (delete), вызвать нельзя. Проверьте, не копируется ли некопируемый тип (std::unique_ptr и т. п.). Передайте через std::move или принимайте по ссылке." },
            ["「{0}」に、演算子「{1}」が使えません。その型に演算子が定義されていないか、const の付いた値を書き換えようとしています(代入や += は、const の値には使えません)。"] = new[] { "Operator \"{1}\" cannot be used on \"{0}\". Either the type does not define the operator, or you are trying to modify a const value (assignment and += cannot be used on const values).", "“{0}”不能使用运算符“{1}”。要么该类型没有定义此运算符，要么试图修改带 const 的值（赋值或 += 不能用于 const 的值）。", "\"{0}\"에 연산자 \"{1}\"을(를) 쓸 수 없습니다. 그 타입에 연산자가 정의되어 있지 않거나, const가 붙은 값을 바꾸려 하고 있습니다(대입이나 +=는 const 값에 쓸 수 없습니다).", "No se puede usar el operador \"{1}\" con \"{0}\". O el tipo no lo define o intenta modificar un valor const (la asignación y += no sirven con valores const).", "O operador \"{1}\" não pode ser usado em \"{0}\". Ou o tipo não o define, ou você tenta modificar um valor const (atribuição e += não servem para valores const).", "Operator \"{1}\" ist auf \"{0}\" nicht anwendbar. Entweder definiert der Typ ihn nicht, oder ein const-Wert soll geändert werden (Zuweisung und += gehen bei const nicht).", "L'opérateur « {1} » n'est pas utilisable sur « {0} ». Soit le type ne le définit pas, soit vous tentez de modifier une valeur const (l'affectation et += ne s'appliquent pas aux valeurs const).", "К «{0}» нельзя применить оператор «{1}». Либо тип его не определяет, либо вы пытаетесь изменить const-значение (присваивание и += для const недопустимы)." },
            ["「{0}」が見つかりません。ファイルの場所と、追加のインクルード ディレクトリを確かめます。Alt+F が書く #include は、プロジェクトが使っているフォルダーの基準に合わせたパスです。"] = new[] { "\"{0}\" was not found. Check the file location and Additional Include Directories. The #include that Alt+F writes uses a path relative to the folders the project uses.", "找不到“{0}”。检查文件的位置和附加包含目录。Alt+F 写入的 #include 是按项目所用文件夹的基准生成的路径。", "\"{0}\"을(를) 찾을 수 없습니다. 파일 위치와 추가 포함 디렉터리를 확인합니다. Alt+F가 쓰는 #include는 프로젝트가 쓰는 폴더 기준에 맞춘 경로입니다.", "No se encuentra \"{0}\". Revise la ubicación del archivo y los Directorios de inclusión adicionales. El #include que escribe Alt+F usa una ruta relativa a las carpetas del proyecto.", "\"{0}\" não foi encontrado. Verifique o local do arquivo e os Diretórios de inclusão adicionais. O #include que o Alt+F escreve usa um caminho relativo às pastas do projeto.", "\"{0}\" nicht gefunden. Speicherort und Zusätzliche Includeverzeichnisse prüfen. Das von Alt+F geschriebene #include nutzt einen Pfad relativ zu den Projektordnern.", "« {0} » est introuvable. Vérifiez l'emplacement du fichier et les Répertoires Include supplémentaires. L'#include écrit par Alt+F utilise un chemin relatif aux dossiers du projet.", "«{0}» не найден. Проверьте расположение файла и «Дополнительные каталоги включаемых файлов». #include, который пишет Alt+F, использует путь относительно папок проекта." },
            ["const の付いた値は、const のない参照では受けられません。受ける側の参照に const を付けるか、コピーで受けます。"] = new[] { "A const value cannot be bound to a non-const reference. Add const to the receiving reference, or take it by copy.", "带 const 的值不能用非 const 的引用接收。给接收方的引用加 const，或按值复制接收。", "const가 붙은 값은 const 없는 참조로 받을 수 없습니다. 받는 쪽 참조에 const를 붙이거나 복사로 받습니다.", "Un valor const no se puede enlazar a una referencia no const. Añada const a la referencia que lo recibe o recíbalo por copia.", "Um valor const não pode ser ligado a referência não const. Adicione const à referência que recebe ou receba por cópia.", "Ein const-Wert kann nicht an eine nicht-const-Referenz gebunden werden. Die empfangende Referenz const machen oder als Kopie annehmen.", "Une valeur const ne peut pas être liée à une référence non const. Ajoutez const à la référence réceptrice ou recevez une copie.", "const-значение нельзя привязать к не-const ссылке. Добавьте const к принимающей ссылке или принимайте копию." },
            ["数値や一時オブジェクトのような「名前のない値」は、const のない参照には結びつけられません。変数に入れてから渡すか、受ける側を const 参照にします。"] = new[] { "An \"unnamed value\" like a number or a temporary cannot be bound to a non-const reference. Put it in a variable first, or make the receiver a const reference.", "数值或临时对象这样的“无名值”不能绑定到非 const 引用。先放进变量再传，或把接收方改为 const 引用。", "수치나 임시 객체 같은 \"이름 없는 값\"은 const 없는 참조에 묶을 수 없습니다. 변수에 넣은 뒤 넘기거나 받는 쪽을 const 참조로 합니다.", "Un \"valor sin nombre\" como un número o un temporal no se puede enlazar a una referencia no const. Guárdelo antes en una variable o haga que reciba una referencia const.", "Um \"valor sem nome\" como um número ou temporário não pode ser ligado a referência não const. Coloque-o antes numa variável ou faça receber uma referência const.", "Ein \"namenloser Wert\" wie eine Zahl oder ein Temporärobjekt kann nicht an eine nicht-const-Referenz gebunden werden. Erst in eine Variable legen oder als const-Referenz annehmen.", "Une « valeur sans nom », comme un nombre ou un temporaire, ne peut pas être liée à une référence non const. Mettez-la d'abord dans une variable ou recevez une référence const.", "«Безымянное значение» (число, временный объект) нельзя привязать к не-const ссылке. Сначала положите его в переменную или принимайте const-ссылку." },
            ["{ } の中の要素の型が、受け取る側の要素の型に合っていません。1 つずつ型を見比べます。"] = new[] { "The element types inside { } do not match the receiver's element type. Compare the types one by one.", "{ } 中元素的类型与接收方的元素类型不符。逐个对照类型。", "{ } 안의 요소 타입이 받는 쪽의 요소 타입과 맞지 않습니다. 하나씩 타입을 비교합니다.", "Los tipos de los elementos de { } no coinciden con el tipo de elemento del receptor. Compárelos uno a uno.", "Os tipos dos elementos em { } não batem com o tipo de elemento de quem recebe. Compare um a um.", "Die Elementtypen in { } passen nicht zum Elementtyp des Empfängers. Einzeln vergleichen.", "Les types des éléments dans { } ne correspondent pas au type d'élément du receveur. Comparez-les un par un.", "Типы элементов в { } не совпадают с типом элементов получателя. Сравните по одному." },
            ["文字列(\"…\")を、数値の変数に入れています。数値にしたいなら std::stoi などで変換します。"] = new[] { "A string (\"…\") is put into a numeric variable. To make it a number, convert with std::stoi or similar.", "把字符串（\"…\"）放进了数值变量。要转为数值，用 std::stoi 等转换。", "문자열(\"…\")을 수치 변수에 넣고 있습니다. 수치로 하려면 std::stoi 등으로 변환합니다.", "Se guarda una cadena (\"…\") en una variable numérica. Para convertirla a número use std::stoi u otra función.", "Uma string (\"…\") é colocada numa variável numérica. Para virar número, converta com std::stoi ou similar.", "Eine Zeichenfolge (\"…\") wird in eine Zahlenvariable gespeichert. Zum Umwandeln std::stoi o. Ä. verwenden.", "Une chaîne (\"…\") est mise dans une variable numérique. Pour en faire un nombre, convertissez avec std::stoi ou similaire.", "Строка («…») записывается в числовую переменную. Чтобы получить число, преобразуйте через std::stoi и т. п." },
            ["数値を、ポインターには入れられません(0 と nullptr だけが例外です)。アドレスを入れたいなら、& を付けたか確かめます。"] = new[] { "A number cannot be put into a pointer (only 0 and nullptr are exceptions). If you wanted an address, check that you added &.", "数值不能放进指针（只有 0 和 nullptr 例外）。想放地址的话，确认是否加了 &。", "수치를 포인터에 넣을 수 없습니다(0과 nullptr만 예외입니다). 주소를 넣고 싶다면 &를 붙였는지 확인합니다.", "Un número no se puede guardar en un puntero (salvo 0 y nullptr). Si quería una dirección, compruebe que puso &.", "Um número não pode ir num ponteiro (só 0 e nullptr são exceção). Se queria um endereço, verifique se colocou &.", "Eine Zahl kann nicht in einen Zeiger (Ausnahmen nur 0 und nullptr). Für eine Adresse prüfen, ob & gesetzt ist.", "Un nombre ne peut pas être mis dans un pointeur (seuls 0 et nullptr font exception). Pour une adresse, vérifiez la présence de &.", "Число нельзя записать в указатель (исключения — 0 и nullptr). Если нужен адрес, проверьте, стоит ли &." },
            ["数値から「{0}」を作る変換が用意されていません。{1}(値) のように明示的に作るか、「{2}」のコンストラクターが受け取る型を確かめます(std::string なら std::to_string を使います)。"] = new[] { "There is no conversion that creates \"{0}\" from a number. Create it explicitly like {1}(value), or check what types the constructor of \"{2}\" takes (for std::string, use std::to_string).", "没有从数值创建“{0}”的转换。像 {1}(值) 这样显式创建，或确认“{2}”的构造函数接受的类型（std::string 的话用 std::to_string）。", "수치에서 \"{0}\"을(를) 만드는 변환이 마련되어 있지 않습니다. {1}(값)처럼 명시적으로 만들거나 \"{2}\"의 생성자가 받는 타입을 확인합니다(std::string이라면 std::to_string을 씁니다).", "No hay conversión que cree \"{0}\" a partir de un número. Créelo explícitamente como {1}(valor) o revise qué tipos acepta el constructor de \"{2}\" (para std::string, use std::to_string).", "Não há conversão que crie \"{0}\" a partir de um número. Crie explicitamente como {1}(valor) ou veja que tipos o construtor de \"{2}\" aceita (para std::string, use std::to_string).", "Es gibt keine Konvertierung, die \"{0}\" aus einer Zahl erzeugt. Explizit wie {1}(Wert) erzeugen oder prüfen, welche Typen der Konstruktor von \"{2}\" annimmt (für std::string std::to_string nutzen).", "Aucune conversion ne crée « {0} » à partir d'un nombre. Créez-le explicitement comme {1}(valeur) ou vérifiez les types acceptés par le constructeur de « {2} » (pour std::string, utilisez std::to_string).", "Нет преобразования, создающего «{0}» из числа. Создайте явно как {1}(значение) или проверьте, какие типы принимает конструктор «{2}» (для std::string используйте std::to_string)." },
            ["「{0}」から数値への暗黙の変換はありません。enum class なら static_cast<{1}>(値) と書きます。クラスなら、変換演算子の有無を確かめます。"] = new[] { "There is no implicit conversion from \"{0}\" to a number. For an enum class, write static_cast<{1}>(value). For a class, check whether it has a conversion operator.", "没有从“{0}”到数值的隐式转换。enum class 的话写 static_cast<{1}>(值)。类的话，确认是否有转换运算符。", "\"{0}\"에서 수치로의 암묵 변환은 없습니다. enum class라면 static_cast<{1}>(값)로 씁니다. 클래스라면 변환 연산자 유무를 확인합니다.", "No hay conversión implícita de \"{0}\" a número. Para un enum class escriba static_cast<{1}>(valor). Para una clase, compruebe si tiene operador de conversión.", "Não há conversão implícita de \"{0}\" para número. Para enum class, escreva static_cast<{1}>(valor). Para classe, veja se há operador de conversão.", "Es gibt keine implizite Konvertierung von \"{0}\" in eine Zahl. Bei enum class static_cast<{1}>(Wert) schreiben. Bei Klassen prüfen, ob ein Konvertierungsoperator existiert.", "Il n'y a pas de conversion implicite de « {0} » vers un nombre. Pour un enum class, écrivez static_cast<{1}>(valeur). Pour une classe, vérifiez la présence d'un opérateur de conversion.", "Нет неявного преобразования «{0}» в число. Для enum class пишите static_cast<{1}>(значение). Для класса проверьте наличие оператора преобразования." },
            ["指す型が違うポインター同士は、代入できません。const の有無、継承していない型、void* からの変換を確かめます。"] = new[] { "Pointers to different types cannot be assigned to each other. Check const, unrelated (non-inherited) types and conversions from void*.", "指向不同类型的指针之间不能赋值。检查 const 的有无、无继承关系的类型、从 void* 的转换。", "가리키는 타입이 다른 포인터끼리는 대입할 수 없습니다. const 유무, 상속하지 않은 타입, void*에서의 변환을 확인합니다.", "No se pueden asignar punteros a tipos distintos. Revise const, tipos sin herencia y conversiones desde void*.", "Ponteiros para tipos diferentes não podem ser atribuídos entre si. Verifique const, tipos sem herança e conversões de void*.", "Zeiger auf verschiedene Typen sind nicht zuweisbar. const, nicht verwandte Typen und Konvertierung aus void* prüfen.", "Des pointeurs vers des types différents ne peuvent pas être affectés entre eux. Vérifiez const, les types sans héritage et les conversions depuis void*.", "Указатели на разные типы нельзя присваивать друг другу. Проверьте const, неродственные типы и преобразования из void*." },
            ["型の違いの原因を、上の「渡した型」と「期待する型」を見比べて確かめます。const・参照・名前空間の違いで、同じに見えて別の型になることがあります。"] = new[] { "Find the cause of the type difference by comparing \"Passed type\" and \"Expected type\" above. Differences in const, references or namespaces can make types that look the same different.", "对照上面的“传入的类型”和“期望的类型”，找出类型差异的原因。const、引用、命名空间的差异会让看似相同的类型成为不同的类型。", "위의 \"넘긴 타입\"과 \"기대하는 타입\"을 비교해 타입 차이의 원인을 확인합니다. const·참조·네임스페이스 차이로 같아 보여도 다른 타입이 되는 경우가 있습니다.", "Busque la causa comparando \"Tipo pasado\" y \"Tipo esperado\" de arriba. Diferencias de const, referencias o namespaces pueden hacer distintos tipos que parecen iguales.", "Encontre a causa comparando \"Tipo passado\" e \"Tipo esperado\" acima. Diferenças de const, referências ou namespaces podem tornar diferentes tipos que parecem iguais.", "Ursache durch Vergleich von \"Übergebener Typ\" und \"Erwarteter Typ\" oben finden. Unterschiede bei const, Referenzen oder Namespaces machen gleich aussehende Typen verschieden.", "Trouvez la cause en comparant « Type passé » et « Type attendu » ci-dessus. Des différences de const, de références ou de namespaces rendent distincts des types d'apparence identique.", "Найдите причину, сравнив «Переданный тип» и «Ожидаемый тип» выше. Из-за const, ссылок или пространств имён одинаковые на вид типы бывают разными." },
            ["このエラーの解説はまだありません"] = new[] { "No explanation for this error yet", "此错误暂时没有解说", "이 오류의 해설은 아직 없습니다", "Aún no hay explicación para este error", "Ainda não há explicação para este erro", "Zu diesem Fehler gibt es noch keine Erklärung", "Pas encore d'explication pour cette erreur", "Пояснения к этой ошибке пока нет" },
            ["メッセージを読み、示された場所と、その 1 つ前の行を確かめます。意味は、エラー コードを押すと、公式のページで調べられます。エラーが複数あるときは、一番上のものから直します。"] = new[] { "Read the message and check the indicated location and the line before it. Click the error code to look up its meaning on the official page. If there are several errors, fix the topmost first.", "阅读消息，检查所示位置及其前一行。点击错误代码，可在官方页面查询含义。有多个错误时，从最上面的开始修正。", "메시지를 읽고 표시된 위치와 그 한 줄 앞을 확인합니다. 의미는 오류 코드를 누르면 공식 페이지에서 찾을 수 있습니다. 오류가 여러 개라면 가장 위의 것부터 고칩니다.", "Lea el mensaje y revise el lugar indicado y la línea anterior. Pulse el código de error para ver su significado en la página oficial. Si hay varios errores, corrija primero el de más arriba.", "Leia a mensagem e verifique o local indicado e a linha anterior. Clique no código do erro para ver o significado na página oficial. Se houver vários erros, corrija o de cima primeiro.", "Meldung lesen, angegebene Stelle und die Zeile davor prüfen. Ein Klick auf den Fehlercode zeigt die Bedeutung auf der offiziellen Seite. Bei mehreren Fehlern den obersten zuerst beheben.", "Lisez le message et vérifiez l'emplacement indiqué ainsi que la ligne précédente. Cliquez sur le code d'erreur pour en voir le sens sur la page officielle. S'il y a plusieurs erreurs, corrigez d'abord la première.", "Прочитайте сообщение и проверьте указанное место и строку перед ним. Щёлкните код ошибки, чтобы узнать смысл на официальной странице. Если ошибок несколько, исправляйте с самой верхней." },
            ["警告"] = new[] { "Warning", "警告", "경고", "Advertencia", "Aviso", "Warnung", "Avertissement", "Предупреждение" },
            ["ビルドは止まりません。意図どおりか確かめます。意味は、エラー コードを押して調べられます。意図があるなら、#pragma warning で止められます。"] = new[] { "The build does not stop. Check that it is intended. Click the error code to look up its meaning. If intended, you can silence it with #pragma warning.", "生成不会停止。确认是否符合预期。点击错误代码可查询含义。若有意为之，可用 #pragma warning 关闭。", "빌드는 멈추지 않습니다. 의도대로인지 확인합니다. 의미는 오류 코드를 눌러 찾을 수 있습니다. 의도가 있다면 #pragma warning으로 끌 수 있습니다.", "La compilación no se detiene. Compruebe si es intencionado. Pulse el código para ver su significado. Si lo es, puede silenciarlo con #pragma warning.", "A compilação não para. Verifique se é intencional. Clique no código para ver o significado. Se for, pode silenciar com #pragma warning.", "Der Build stoppt nicht. Prüfen, ob es gewollt ist. Bedeutung per Klick auf den Fehlercode. Wenn gewollt, mit #pragma warning abschalten.", "La génération ne s'arrête pas. Vérifiez que c'est voulu. Cliquez sur le code pour en voir le sens. Si c'est voulu, désactivez-le avec #pragma warning.", "Сборка не останавливается. Проверьте, так ли задумано. Смысл можно узнать, щёлкнув код. Если задумано, отключите через #pragma warning." },
            ["ビルドの出力はまだありません。ビルドすると、ここにエラーが出ます。"] = new[] { "No build output yet. Build and the errors will appear here.", "还没有生成输出。生成后，错误会显示在这里。", "빌드 출력이 아직 없습니다. 빌드하면 여기에 오류가 나옵니다.", "Aún no hay salida de compilación. Compile y los errores aparecerán aquí.", "Ainda não há saída de compilação. Compile e os erros aparecerão aqui.", "Noch keine Build-Ausgabe. Nach dem Erstellen erscheinen die Fehler hier.", "Pas encore de sortie de génération. Générez et les erreurs apparaîtront ici.", "Вывода сборки пока нет. Соберите проект, и ошибки появятся здесь." },
            ["✖ ビルドに失敗しました"] = new[] { "✖ Build failed", "✖ 生成失败", "✖ 빌드에 실패했습니다", "✖ La compilación falló", "✖ A compilação falhou", "✖ Build fehlgeschlagen", "✖ Échec de la génération", "✖ Сборка не удалась" },
