            ["   警告 {0} 件"] = new[] { "   {0} warnings", "   警告 {0} 个", "   경고 {0}개", "   {0} advertencias", "   {0} avisos", "   {0} Warnungen", "   {0} avertissements", "   Предупреждений: {0}" },
            ["構成: {0}   "] = new[] { "Configuration: {0}   ", "配置：{0}   ", "구성: {0}   ", "Configuración: {0}   ", "Configuração: {0}   ", "Konfiguration: {0}   ", "Configuration : {0}   ", "Конфигурация: {0}   " },
            ["プロジェクト: {0}   "] = new[] { "Project: {0}   ", "项目：{0}   ", "프로젝트: {0}   ", "Proyecto: {0}   ", "Projeto: {0}   ", "Projekt: {0}   ", "Projet : {0}   ", "Проект: {0}   " },
            ["… 件数が多いので、ここから先は省略しました。「原文」表示で全部を読めます。"] = new[] { "… There are many, so the rest is omitted. You can read everything in the \"Raw\" view.", "… 数量太多，此后省略。在“原文”显示中可以看到全部。", "… 개수가 많아 여기서부터는 생략했습니다. \"원문\" 표시로 전부 읽을 수 있습니다.", "… Hay demasiados; se omite el resto. Puede leerlo todo en la vista \"Original\".", "… São muitos; o restante foi omitido. Dá para ler tudo na exibição \"Original\".", "… Zu viele, der Rest ist ausgelassen. Alles in der Ansicht \"Original\" lesbar.", "… Trop nombreux, la suite est omise. Tout est lisible dans la vue « Brut ».", "… Их слишком много, остальное опущено. Всё можно прочитать в режиме «Исходный»." },
            ["出力にエラーも警告もありません。"] = new[] { "The output has no errors or warnings.", "输出中没有错误也没有警告。", "출력에 오류도 경고도 없습니다.", "La salida no tiene errores ni advertencias.", "A saída não tem erros nem avisos.", "Die Ausgabe enthält weder Fehler noch Warnungen.", "La sortie ne contient ni erreur ni avertissement.", "В выводе нет ни ошибок, ни предупреждений." },
            ["ファイル別  "] = new[] { "By file  ", "按文件  ", "파일별  ", "Por archivo  ", "Por arquivo  ", "Nach Datei  ", "Par fichier  ", "По файлам  " },
            ["… ほか {0} ファイル"] = new[] { "… and {0} more files", "… 另外 {0} 个文件", "… 그 밖에 {0}개 파일", "… y {0} archivos más", "… e mais {0} arquivos", "… und {0} weitere Dateien", "… et {0} fichiers de plus", "… и ещё файлов: {0}" },
            ["まず: "] = new[] { "First: ", "首先：", "먼저: ", "Primero: ", "Primeiro: ", "Zuerst: ", "D'abord : ", "Сначала: " },
            ["一番上のエラーから直して、ビルドし直します。1 つの原因から、あとのエラーが連鎖して出ることが多いからです。"] = new[] { "Fix the topmost error and build again. One cause often produces a chain of later errors.", "从最上面的错误开始修正，然后重新生成。因为一个原因常常会连锁引出后面的错误。", "가장 위의 오류부터 고치고 다시 빌드합니다. 하나의 원인에서 뒤의 오류가 연쇄적으로 나오는 경우가 많기 때문입니다.", "Corrija el error de más arriba y vuelva a compilar. Una sola causa suele provocar una cadena de errores posteriores.", "Corrija o erro de cima e compile de novo. Uma causa costuma gerar uma cadeia de erros seguintes.", "Den obersten Fehler beheben und neu erstellen. Eine Ursache zieht oft eine Kette weiterer Fehler nach sich.", "Corrigez la première erreur et relancez la génération. Une seule cause entraîne souvent une cascade d'erreurs.", "Исправьте самую верхнюю ошибку и пересоберите. Одна причина часто порождает цепочку следующих ошибок." },
            ["この {0} 件のうち {1} 件は、上のエラーの影響で出ている可能性があります (「連鎖の可能性」と書いた項目)。"] = new[] { "Of these {0}, {1} may be caused by errors above (items marked \"Possible cascade\").", "这 {0} 个中有 {1} 个可能是上面错误的影响（标有“可能是连锁”的项）。", "이 {0}건 중 {1}건은 위의 오류 영향으로 나왔을 수 있습니다(\"연쇄 가능성\"이라고 적힌 항목).", "De estos {0}, {1} pueden deberse a errores de arriba (elementos marcados \"Posible cascada\").", "Destes {0}, {1} podem ser efeito de erros acima (itens marcados \"Possível cascata\").", "Von diesen {0} sind {1} möglicherweise Folge der Fehler oben (Einträge mit \"Mögliche Folge\").", "Sur ces {0}, {1} peuvent provenir des erreurs ci-dessus (éléments marqués « Cascade possible »).", "Из этих {0} ошибок {1} могут быть следствием ошибок выше (помечены «Возможная цепочка»)." },
            ["原因の候補: "] = new[] { "Likely cause: ", "可能的原因：", "원인 후보: ", "Causa probable: ", "Causa provável: ", "Vermutliche Ursache: ", "Cause probable : ", "Вероятная причина: " },
            ["■ 未解決の外部シンボル"] = new[] { "■ Unresolved external symbols", "■ 无法解析的外部符号", "■ 확인할 수 없는 외부 심볼", "■ Símbolos externos sin resolver", "■ Símbolos externos não resolvidos", "■ Nicht aufgelöste externe Symbole", "■ Symboles externes non résolus", "■ Неразрешённые внешние символы" },
            ["   {0} 件を、原因 {1} 個にまとめました"] = new[] { "   {0} grouped into {1} causes", "   将 {0} 个归纳为 {1} 个原因", "   {0}건을 원인 {1}개로 정리했습니다", "   {0} agrupados en {1} causas", "   {0} agrupados em {1} causas", "   {0} zu {1} Ursachen zusammengefasst", "   {0} regroupés en {1} causes", "   {0} сведены к {1} причинам" },
            ["リンカーの集計 (LNK1120): {0} 件"] = new[] { "Linker total (LNK1120): {0}", "链接器统计（LNK1120）：{0} 个", "링커 집계 (LNK1120): {0}건", "Total del enlazador (LNK1120): {0}", "Total do linker (LNK1120): {0}", "Linker-Summe (LNK1120): {0}", "Total de l'éditeur de liens (LNK1120) : {0}", "Итог компоновщика (LNK1120): {0}" },
            ["ソリューションの .lib とソースを検索中です。終わると、原因の分類が更新されます…"] = new[] { "Searching the solution's .lib files and sources. When done, the cause classification will be updated…", "正在搜索解决方案的 .lib 和源代码。完成后，原因的分类会更新…", "솔루션의 .lib와 소스를 검색 중입니다. 끝나면 원인 분류가 갱신됩니다…", "Buscando los .lib y el código de la solución. Al terminar se actualizará la clasificación de causas…", "Procurando os .lib e o código da solução. Ao terminar, a classificação das causas será atualizada…", "Durchsuche .lib-Dateien und Quellen der Projektmappe. Danach wird die Ursachenzuordnung aktualisiert…", "Recherche des .lib et des sources de la solution. Une fois fini, le classement des causes sera mis à jour…", "Идёт поиск .lib и исходников решения. По завершении классификация причин обновится…" },
            ["検索範囲: {0} の下の .lib と、ソース {1} ファイル"] = new[] { "Searched: .lib files under {0}, and {1} source files", "搜索范围：{0} 下的 .lib，以及源代码 {1} 个文件", "검색 범위: {0} 아래의 .lib와 소스 {1}개 파일", "Búsqueda: .lib bajo {0} y {1} archivos de código", "Busca: .lib sob {0} e {1} arquivos de código", "Durchsucht: .lib unter {0} und {1} Quelldateien", "Recherche : .lib sous {0} et {1} fichiers source", "Область поиска: .lib в {0} и исходники ({1} файлов)" },
