            ["名前や説明で検索"] = new[] { "Search by name or description", "", "", "", "", "", "", "" },
            ["最新の版 (GitHub)"] = new[] { "Latest version (GitHub)", "", "", "", "", "", "", "" },
            ["既定"] = new[] { "default", "", "", "", "", "", "", "" },
            ["ベースラインで版をそろえる (builtin-baseline)"] = new[] { "Pin versions with a baseline (builtin-baseline)", "", "", "", "", "", "", "" },
            ["入: vcpkg.json に builtin-baseline を書いて、全員が同じ版を使えるようにします。切: 書かずに、手元の vcpkg の最新のポートを使います。"] = new[] { "On: writes builtin-baseline to vcpkg.json so everyone uses the same versions. Off: omits it and uses the latest ports of your local vcpkg.", "", "", "", "", "", "", "" },
            ["builtin-baseline を、vcpkg.json から消しました (「元に戻す」で戻せます)。"] = new[] { "Removed builtin-baseline from vcpkg.json (you can restore it with Undo).", "", "", "", "", "", "", "" },
            ["vcpkg.json を置くフォルダーを選びます。ソリューションのフォルダーか、各プロジェクトのフォルダーです。まだ vcpkg.json がない場所を選んで追加すると、新しく作ります。"] = new[] { "Choose the folder that holds vcpkg.json: the solution folder or a project folder. If you pick a place without a vcpkg.json and add a package, one is created.", "", "", "", "", "", "", "" },
            ["トリプレットは、「どの CPU・OS・リンク方式で作るか」の組み合わせです。x64-windows は、64 ビットの Windows で DLL を使う設定、x64-windows-static は、ライブラリを実行ファイルに埋め込む設定です。プロジェクトの triplets フォルダーに置いた自作のものも並びます。"] = new[] { "A triplet is the combination of CPU, OS and link style to build for. x64-windows means 64-bit Windows with DLLs; x64-windows-static embeds the libraries in the executable. Custom triplets in the project's triplets folder are listed too.", "", "", "", "", "", "", "" },
            ["機能 (feature) は、パッケージの追加部品です。チェックを入れたものを、既定の機能に加えて入れます。[既定] と付いたものは、「既定の機能を使う」が入のとき、チェックが切でも入ります。"] = new[] { "A feature is an optional part of a package. Checked features are installed in addition to the default ones. Features marked [default] are installed even when unchecked, as long as 'Use default features' is on.", "", "", "", "", "", "", "" },
            ["入: パッケージが既定にしている機能が入ります。切: 既定の機能は入らず、下でチェックした機能だけが入ります。切にすると、動くのに必要な機能まで入らず、ビルドが通らなくなることがあります。"] = new[] { "On: the features the package marks as default are installed. Off: only the features you check below are installed. Turning it off can leave out what the package needs to work and break the build.", "", "", "", "", "", "", "" },
            ["ベースラインの版: vcpkg.json の builtin-baseline が指す時点の版が入ります。この版以上: 指定した版か、それより新しい版を使います。builtin-baseline がないと、版は指定できません。"] = new[] { "Baseline version: the version at the point builtin-baseline refers to. Version or newer: uses that version or a newer one. Without a builtin-baseline you cannot specify versions.", "", "", "", "", "", "", "" },
            ["ベースラインは、「パッケージの版を、ある時点にそろえる」ための印です。vcpkg の履歴の 1 点 (コミット) を指して、vcpkg.json の builtin-baseline に書きます。入: 誰がいつインストールしても、同じ版になります。切: 書かないので、手元の vcpkg にあるポートの、その時点の版が入ります。「ベースラインを更新」で、最新の時点に書き換えられます。"] = new[] { "A baseline pins package versions to one point in time. It points at one commit of vcpkg's history and is written as builtin-baseline in vcpkg.json. On: everyone gets the same versions whenever they install. Off: it is omitted and the ports in your local vcpkg are used as they are. 'Update baseline' moves it to the latest point.", "", "", "", "", "", "", "" },
            ["入っている版は、このフォルダーの vcpkg_installed から読みます。最新の版は、GitHub の vcpkg から取ります。実際にどの版が入るかは、ベースラインで決まるので、新しくしたいときは「ベースラインを更新」を使います。"] = new[] { "Installed versions are read from this folder's vcpkg_installed. Latest versions come from vcpkg on GitHub. The version actually installed is decided by the baseline, so use 'Update baseline' to get newer ones.", "", "", "", "", "", "", "" },
            ["vcpkg.json に書いたパッケージを、すべて入れます (vcpkg install)。出力は、下のログに流れます。失敗したときは、ログの末尾に原因の見当を書きます。"] = new[] { "Installs everything listed in vcpkg.json (vcpkg install). Output goes to the log below; on failure a likely cause is added at the end.", "", "", "", "", "", "", "" },
            ["このパッケージが、ほかのどのパッケージに依存しているかを、木の形でログに出します。"] = new[] { "Prints, as a tree in the log, which packages this package depends on.", "", "", "", "", "", "", "" },
            ["説明を見る"] = new[] { "Show help", "", "", "", "", "", "", "" },
            ["ビルド時の自動インストールは、2 つがそろうと働きます。(1) プロジェクトで、マニフェスト モード (VcpkgEnableManifest) が有効なこと。(2) Visual Studio と vcpkg が連携していること (vcpkg integrate install)。そろっていると、Visual Studio でビルドするたびに、vcpkg.json に書いたパッケージが、足りなければ自動で入ります。そのため「今すぐインストール」は、ビルドを待たずに入れたいときや、エラーの内容を先に見たいときだけ使えば足ります。パッケージを追加すると、この窓が、プロジェクトのマニフェスト モードを自動で有効にします。"] = new[] { "Automatic install at build time works when two things are in place: (1) the project has manifest mode (VcpkgEnableManifest) enabled, and (2) Visual Studio is integrated with vcpkg (vcpkg integrate install). Then every build in Visual Studio installs any missing packages listed in vcpkg.json. So 'Install now' is only needed to install without building or to see errors first. Adding a package makes this window enable manifest mode for the projects automatically.", "", "", "", "", "", "", "" },
            ["vcpkg.json に書いたパッケージを、すべて入れます (vcpkg install)。マニフェスト モードと VS との連携がそろっていれば、Visual Studio がビルド時に自動でやるので、押さなくても入ります。ここで押すのは、ビルドを待たずに入れたいときや、失敗の原因を先にログで見たいときです。出力は、下のログに流れます。"] = new[] { "Installs everything listed in vcpkg.json (vcpkg install). When manifest mode and the Visual Studio integration are in place, Visual Studio does this at build time, so you do not need to press it. Use it to install without building or to see the cause of a failure in the log first. Output goes to the log below.", "", "", "", "", "", "", "" },
            ["今すぐインストール (vcpkg install)"] = new[] { "Install now (vcpkg install)", "", "", "", "", "", "", "" },
            ["ビルド時に自動でインストールする"] = new[] { "Install automatically at build", "", "", "", "", "", "", "" },
            ["VS と連携する (integrate install)"] = new[] { "Integrate with VS (integrate install)", "", "", "", "", "", "", "" },
            ["ビルド時の自動インストール: vcpkg.json を作ると使えます"] = new[] { "Automatic install at build: available once a vcpkg.json exists", "", "", "", "", "", "", "" },
            ["ビルド時の自動インストール: プロジェクト (.vcxproj) が見つかりません (CMake などは、vcpkg の連携が別に要ります)"] = new[] { "Automatic install at build: no project (.vcxproj) found (CMake etc. need their own vcpkg integration)", "", "", "", "", "", "", "" },
            ["ビルド時の自動インストール: プロジェクト (.vcxproj) が見つかりません"] = new[] { "Automatic install at build: no project (.vcxproj) found", "", "", "", "", "", "", "" },
            ["ビルド時の自動インストール: ✔ 有効 ({0} 個のプロジェクト。ビルドすると、Visual Studio が自動で入れます)"] = new[] { "Automatic install at build: ✔ enabled ({0} project(s); Visual Studio installs when you build)", "", "", "", "", "", "", "" },
            ["マニフェスト モードが有効なのは、{0} 個中 {1} 個"] = new[] { "manifest mode is on in {1} of {0} projects", "", "", "", "", "", "", "" },
